export const ITEM_LEARNING: Record<string, any> = {"201":{"concept":"Keadilan prosedural","theory":"Keputusan adil memakai kriteria relevan secara konsisten, memeriksa bukti, dan memberi ruang klarifikasi. Hasil yang sama tidak selalu tepat ketika kondisi yang relevan berbeda.","why_correct":"Salah salin dapat mengubah pemenang dan masih dapat dikoreksi sebelum penugasan. Skor asli dan prosedur yang sama menjadi dasar, bukan dukungan pimpinan.","comparison":"Berbagi jabatan, mempertahankan hasil, atau membuat penilaian baru tidak memperbaiki kesalahan pencatatan dengan dasar seleksi semula.","check_question":"Mengapa koreksi skor asli lebih tepat daripada mengulang penilaian dengan skor baru?","check_answer":"Memeriksa skor asli, mengoreksi hasil melalui proses yang sama, dan menjelaskan perubahan sebelum penugasan berlaku. Alasannya: Salah salin dapat mengubah pemenang dan masih dapat dikoreksi sebelum penugasan. Skor asli dan prosedur yang sama menjadi dasar, bukan dukungan pimpinan.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"202":{"concept":"Komunikasi dua arah","theory":"Komunikasi efektif dinilai dari pemahaman penerima. Mendengar hambatan dan meminta klarifikasi membantu memperbaiki pesan serta respons, bukan hanya memperbanyak informasi.","why_correct":"Kriteria belum dijelaskan meskipun kebutuhan kompetensi sudah tercatat. Mengakui kekurangan penjelasan dan membuka pemeriksaan memisahkan transparansi dari tuduhan kedekatan.","comparison":"Menuntut penarikan tuduhan atau mengganti peserta tidak membuktikan dasar pemilihan; menunda seluruh keberatan meninggalkan kekurangan keterbukaan.","check_question":"Apa kekurangan proses yang perlu diakui walaupun pemilihan didasarkan pada kebutuhan kompetensi?","check_answer":"Mengakui kekurangan penjelasan, menunjukkan dasar kebutuhan, dan membuka pemeriksaan pilihan dengan tenggat yang jelas. Alasannya: Kriteria belum dijelaskan meskipun kebutuhan kompetensi sudah tercatat. Mengakui kekurangan penjelasan dan membuka pemeriksaan memisahkan transparansi dari tuduhan kedekatan.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"203":{"concept":"Praktik reflektif","theory":"Pemimpin menelaah keputusan serta dampaknya, mengakui bagian yang keliru, dan memperbaiki tindakan. Refleksi mengubah bukti pengalaman menjadi perbaikan yang spesifik.","why_correct":"Sekolah telah memberi pengumuman sebelum memeriksa syarat sehingga keluarga menanggung dampak. Koreksi prosedural perlu disertai tanggung jawab terhadap dampak tersebut.","comparison":"Pesan pribadi saja tidak meluruskan proses; pengecualian atau pembatalan semua tim tidak menyasar dua siswa yang tidak memenuhi syarat.","check_question":"Mengapa memperbaiki daftar belum cukup tanpa membahas dampak pembelian perlengkapan keluarga?","check_answer":"Mengakui kelalaian, memperbaiki daftar melalui prosedur lomba, dan membahas dampak pembelian dengan keluarga yang terdampak. Alasannya: Sekolah telah memberi pengumuman sebelum memeriksa syarat sehingga keluarga menanggung dampak. Koreksi prosedural perlu disertai tanggung jawab terhadap dampak tersebut.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"204":{"concept":"Konflik kepentingan","theory":"Kepentingan pribadi dapat mengganggu independensi keputusan, termasuk ketika belum terbukti ada keberpihakan. Pengungkapan dan pemisahan peran melindungi proses dari pengaruh tersebut.","why_correct":"Skor kepala sekolah menentukan hasil seri untuk kelas anaknya. Pengganti tersedia sehingga penilaian dapat tetap berjalan dengan rubrik sama dan lebih independen.","comparison":"Publikasi skor tidak menghapus konflik; skor sengaja rendah merusak penilaian; pengulangan seluruh panel melebihi kebutuhan koreksi.","check_question":"Mengapa keterbukaan skor tidak menggantikan pelepasan peran kepala sekolah pada karya terkait?","check_answer":"Mengungkap hubungan keluarga dan menyerahkan penilaian karya terkait kepada pengganti menggunakan rubrik yang sama. Alasannya: Skor kepala sekolah menentukan hasil seri untuk kelas anaknya. Pengganti tersedia sehingga penilaian dapat tetap berjalan dengan rubrik sama dan lebih independen.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"205":{"concept":"Penalaran berbasis bukti","theory":"Petunjuk, persepsi, dan hasil akhir mempunyai kekuatan serta batas berbeda. Kesimpulan perlu mengikuti bukti yang relevan dan diperiksa silang, bukan memilih data yang mendukung dugaan awal.","why_correct":"Angket umum, observasi positif, dan cerita terbatas memberi bukti dengan jangkauan berbeda. Pemeriksaan aman perlu membedakan kejadian terverifikasi dari kesan umum.","comparison":"Teguran dari angket saja terlalu cepat; menunda sampai semester mengabaikan petunjuk; konfirmasi terbuka dapat membahayakan keberanian siswa.","check_question":"Mengapa hasil angket dan observasi sebelumnya perlu diperiksa tanpa memilih salah satunya secara mutlak?","check_answer":"Mendengar siswa secara aman, mencari bukti pendukung, dan membedakan pola terverifikasi dari penilaian umum sebelum menetapkan pembinaan. Alasannya: Angket umum, observasi positif, dan cerita terbatas memberi bukti dengan jangkauan berbeda. Pemeriksaan aman perlu membedakan kejadian terverifikasi dari kesan umum.","reference":null,"reference_note":null},"206":{"concept":"Perlindungan dan kepentingan siswa","theory":"Tindak lanjut perlu mengurangi paparan risiko, menjaga martabat, dan membatasi penyebaran informasi sesuai kebutuhan penanganan. Mencari fakta berjalan bersama langkah perlindungan.","why_correct":"Ancaman dan kekhawatiran pembalasan menjadi dasar perlindungan segera, sementara penjelasan pihak terkait tetap perlu diperiksa secara terbatas.","comparison":"Mengumumkan alasan atau menyamarkan persoalan tanpa tindak lanjut dapat memperbesar risiko atau membiarkan ancaman.","check_question":"Apa yang perlu dilindungi segera meskipun klarifikasi kepada pengirim ancaman belum selesai?","check_answer":"Menyepakati langkah perlindungan dengan siswa, membatasi penyebaran informasi, dan memeriksa ancaman melalui penanganan yang adil. Alasannya: Ancaman dan kekhawatiran pembalasan menjadi dasar perlindungan segera, sementara penjelasan pihak terkait tetap perlu diperiksa secara terbatas.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"207":{"concept":"Keadilan prosedural","theory":"Keputusan adil memakai kriteria relevan secara konsisten, memeriksa bukti, dan memberi ruang klarifikasi. Hasil yang sama tidak selalu tepat ketika kondisi yang relevan berbeda.","why_correct":"Kontribusi tinggi tidak menghapus standar laporan yang berlaku bagi koordinator. Dukungan dapat menyesuaikan beban tanpa menghilangkan tanggung jawab.","comparison":"Mengecualikan guru andalan atau memindahkan seluruh kewajiban melemahkan standar yang harus diterapkan konsisten.","check_question":"Bagaimana menjaga kontribusi guru andalan tanpa memberinya pengecualian standar laporan?","check_answer":"Mempertahankan kewajiban evaluasi dengan format yang relevan dan menawarkan dukungan yang juga dapat diakses koordinator lain. Alasannya: Kontribusi tinggi tidak menghapus standar laporan yang berlaku bagi koordinator. Dukungan dapat menyesuaikan beban tanpa menghilangkan tanggung jawab.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"208":{"concept":"Komunikasi dua arah","theory":"Komunikasi efektif dinilai dari pemahaman penerima. Mendengar hambatan dan meminta klarifikasi membantu memperbaiki pesan serta respons, bukan hanya memperbanyak informasi.","why_correct":"Komunikasi singkat dianggap efisien oleh tim, tetapi guru baru belum memahami koreksi dan takut bertanya. Efektivitas perlu memeriksa pemahaman penerima.","comparison":"Mempercepat pesan atau menyalahkan kesiapan guru mempertahankan hambatan; panjangnya pesan saja tidak menjamin pemahaman.","check_question":"Mengapa komunikasi yang singkat belum dapat dianggap efektif untuk guru baru ini?","check_answer":"Menguji contoh umpan balik yang lebih jelas dan memeriksa pemahaman penerima sambil mempertahankan arahan yang ringkas. Alasannya: Komunikasi singkat dianggap efisien oleh tim, tetapi guru baru belum memahami koreksi dan takut bertanya. Efektivitas perlu memeriksa pemahaman penerima.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"209":{"concept":"Praktik reflektif","theory":"Pemimpin menelaah keputusan serta dampaknya, mengakui bagian yang keliru, dan memperbaiki tindakan. Refleksi mengubah bukti pengalaman menjadi perbaikan yang spesifik.","why_correct":"Catatan menunjukkan hambatan pada persetujuan pimpinan dan kelengkapan berkas guru, bukan operator saja. Pengajuan ulang perlu perbaikan alur bersama.","comparison":"Menyalahkan satu orang atau mengambil alih tanpa memperbaiki titik tunggu dapat mengulang keterlambatan.","check_question":"Apa dua hambatan yang perlu diatasi sebelum kesempatan pengajuan ulang digunakan?","check_answer":"Mengakui bagian tanggung jawab pimpinan dan mengatur penyelesaian berkas serta persetujuan untuk menggunakan kesempatan pengajuan ulang. Alasannya: Catatan menunjukkan hambatan pada persetujuan pimpinan dan kelengkapan berkas guru, bukan operator saja. Pengajuan ulang perlu perbaikan alur bersama.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"210":{"concept":"Konflik kepentingan","theory":"Kepentingan pribadi dapat mengganggu independensi keputusan, termasuk ketika belum terbukti ada keberpihakan. Pengungkapan dan pemisahan peran melindungi proses dari pengaruh tersebut.","why_correct":"Potongan pribadi datang dari penyedia yang sedang dinilai sekolah. Memisahkan kepentingan keluarga dari pemilihan menjaga independensi panitia.","comparison":"Kesetaraan mutu atau diskon kecil tidak menghapus hubungan kepentingan pribadi dalam keputusan penyedia.","check_question":"Mengapa potongan harga untuk keluarga tetap relevan dengan integritas pemilihan penyedia sekolah?","check_answer":"Menolak keuntungan pribadi dan meminta panitia membandingkan penawaran sekolah secara independen dengan kriteria yang tercatat. Alasannya: Potongan pribadi datang dari penyedia yang sedang dinilai sekolah. Memisahkan kepentingan keluarga dari pemilihan menjaga independensi panitia.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"211":{"concept":"Penalaran berbasis bukti","theory":"Petunjuk, persepsi, dan hasil akhir mempunyai kekuatan serta batas berbeda. Kesimpulan perlu mengikuti bukti yang relevan dan diperiksa silang, bukan memilih data yang mendukung dugaan awal.","why_correct":"Kelulusan mensyaratkan kehadiran dan tugas selesai. Daftar yang memakai satu syarat saja belum cukup, sedangkan data rinci tersedia sore ini.","comparison":"Memilih daftar yang lebih menguntungkan atau segera mengumumkan tidak memenuhi kedua syarat penyelenggara.","check_question":"Mengapa dua daftar tidak dapat diselesaikan hanya dengan memilih jumlah kelulusan yang lebih tinggi?","check_answer":"Menunda pengumuman status sampai kedua syarat dicocokkan pada tiap guru dan menjelaskan waktu pembaruan hasil. Alasannya: Kelulusan mensyaratkan kehadiran dan tugas selesai. Daftar yang memakai satu syarat saja belum cukup, sedangkan data rinci tersedia sore ini.","reference":null,"reference_note":null},"212":{"concept":"Partisipasi bermakna","theory":"Pihak terkait mempunyai kesempatan menyampaikan kebutuhan dan memeriksa dasar keputusan. Partisipasi bukan hanya hadir atau mendapat giliran, tetapi gagasannya dapat memengaruhi pembahasan.","why_correct":"Guru menafsirkan perbedaan sebagai penolakan sehingga gagasan tidak muncul. Forum perlu membedakan ruang masukan dari keputusan operasional yang mendesak.","comparison":"Semua keputusan cepat atau semua keputusan diperlambat tidak membedakan kebutuhan partisipasi dan urgensi.","check_question":"Bagaimana membuka ruang usulan tanpa menghambat keputusan operasional yang harus cepat?","check_answer":"Membedakan keputusan cepat dan ruang pengembangan, mengundang alternatif secara terarah, serta memantau pelaksanaan dan inisiatif guru. Alasannya: Guru menafsirkan perbedaan sebagai penolakan sehingga gagasan tidak muncul. Forum perlu membedakan ruang masukan dari keputusan operasional yang mendesak.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"213":{"concept":"Integritas dan akuntabilitas","theory":"Laporan dan pengakuan kontribusi harus mengikuti kenyataan yang dapat diperiksa. Akuntabilitas berarti keputusan dapat dijelaskan dengan bukti, bukan sekadar selesai secara administratif.","why_correct":"Meninjau mutu berbeda dari menulis isi. Karena laporan menjadi rujukan penghargaan, atribusi harus dikoreksi sebelum penilaian.","comparison":"Apresiasi pribadi tanpa koreksi laporan tetap mempertahankan informasi resmi yang salah.","check_question":"Peran apa yang perlu dibedakan pada atribusi penulisan modul?","check_answer":"Mengoreksi peran penulis dan peninjau dalam laporan sebelum penilaian serta menyampaikan pengakuan kepada ketiga guru. Alasannya: Meninjau mutu berbeda dari menulis isi. Karena laporan menjadi rujukan penghargaan, atribusi harus dikoreksi sebelum penilaian.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"214":{"concept":"Keadilan prosedural","theory":"Keputusan adil memakai kriteria relevan secara konsisten, memeriksa bukti, dan memberi ruang klarifikasi. Hasil yang sama tidak selalu tepat ketika kondisi yang relevan berbeda.","why_correct":"Nominasi dari siswa yang sering tampil belum mewakili bukti karakter sehari-hari. Observasi tambahan masih dapat dilakukan sebelum pengumuman.","comparison":"Popularitas atau keterlihatan bukan pengganti indikator karakter; mempercepat pengumuman mempertahankan bias kesempatan diamati.","check_question":"Bukti apa yang perlu ditambahkan agar penghargaan tidak hanya menguntungkan siswa yang sering tampil?","check_answer":"Memeriksa perilaku relevan dengan kriteria melalui beberapa sumber agar penghargaan tidak hanya mengikuti keterlihatan siswa. Alasannya: Nominasi dari siswa yang sering tampil belum mewakili bukti karakter sehari-hari. Observasi tambahan masih dapat dilakukan sebelum pengumuman.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"215":{"concept":"Kesetaraan kesempatan dan akses","theory":"Kesempatan yang adil memperhatikan hambatan biaya, waktu, bahasa, dan akses. Perlakuan seragam dapat menghasilkan kesempatan berbeda ketika kebutuhan pengguna tidak sama.","why_correct":"Sebagian keluarga baru dapat membaca pesan malam hari, sedangkan respons diminta siang. Saluran dan tenggat perlu menyesuaikan akses nyata.","comparison":"Satu saluran digital dan tenggat seragam dapat mengecualikan keluarga meskipun informasi telah dikirim.","check_question":"Mengapa pesan yang sudah terkirim belum membuktikan semua keluarga mendapat kesempatan merespons?","check_answer":"Menyediakan saluran setara dan batas respons sesuai akses keluarga, dengan cara khusus untuk pemberitahuan yang benar-benar mendesak. Alasannya: Sebagian keluarga baru dapat membaca pesan malam hari, sedangkan respons diminta siang. Saluran dan tenggat perlu menyesuaikan akses nyata.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"216":{"concept":"Partisipasi bermakna","theory":"Pihak terkait mempunyai kesempatan menyampaikan kebutuhan dan memeriksa dasar keputusan. Partisipasi bukan hanya hadir atau mendapat giliran, tetapi gagasannya dapat memengaruhi pembahasan.","why_correct":"Jumlah peserta dan kebutuhan pengaturan khusus sama-sama memengaruhi fungsi ruang. Alternatif aula serta ruang kecil perlu dibahas bersama.","comparison":"Jumlah terbanyak, satu kebutuhan tunggal, atau undian tidak memastikan ruang cocok bagi partisipasi kedua kelompok.","check_question":"Informasi fungsi ruang apa yang perlu dibandingkan selain jumlah peserta?","check_answer":"Membandingkan kebutuhan fungsi ruang dan menata alternatif bersama kedua kelompok agar partisipasi siswa tetap terlayani. Alasannya: Jumlah peserta dan kebutuhan pengaturan khusus sama-sama memengaruhi fungsi ruang. Alternatif aula serta ruang kecil perlu dibahas bersama.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"217":{"concept":"Kemitraan berorientasi kebutuhan","theory":"Sekolah dan mitra menyatukan tujuan serta peran untuk menjawab kebutuhan siswa. Banyaknya dukungan atau kegiatan tidak otomatis menunjukkan kualitas kerja sama.","why_correct":"Relawan tersedia lebih sering tetapi belum mengenal tujuan latihan. Pembagian tugas, arahan, dan pemantauan menjaga perluasan dukungan tetap bermutu.","comparison":"Banyaknya hari pendampingan tidak otomatis menjamin mutu jika relawan belum memahami sasaran latihan.","check_question":"Apa yang perlu disiapkan agar lima hari dukungan relawan tetap mengikuti tujuan latihan sekolah?","check_answer":"Menyepakati latihan, batas peran, dan rujukan masalah lalu memulai jadwal yang dapat dipantau sebelum memperluas pendampingan. Alasannya: Relawan tersedia lebih sering tetapi belum mengenal tujuan latihan. Pembagian tugas, arahan, dan pemantauan menjaga perluasan dukungan tetap bermutu.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"218":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Proyek menilai kerja sama, bukan ketersediaan waktu keluarga di luar sekolah. Sesi di kelas perlu dimanfaatkan untuk memberi kesempatan menunjukkan kompetensi.","comparison":"Nilai rendah karena hambatan jadwal atau pembebasan total dapat mengukur akses waktu alih-alih kerja sama.","check_question":"Bagaimana siswa dapat menunjukkan kerja sama tanpa bergantung pada pertemuan luar kelas?","check_answer":"Menggunakan sesi sekolah untuk bukti kerja sama dan menilai kontribusi tiap siswa dengan akses penyelesaian yang setara. Alasannya: Proyek menilai kerja sama, bukan ketersediaan waktu keluarga di luar sekolah. Sesi di kelas perlu dimanfaatkan untuk memberi kesempatan menunjukkan kompetensi.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"219":{"concept":"Partisipasi bermakna","theory":"Pihak terkait mempunyai kesempatan menyampaikan kebutuhan dan memeriksa dasar keputusan. Partisipasi bukan hanya hadir atau mendapat giliran, tetapi gagasannya dapat memengaruhi pembahasan.","why_correct":"Komite dan guru memiliki tujuan hubungan keluarga yang sama tetapi bentuk berbeda. Dua jam perlu dirancang berdasarkan tujuan dan kebutuhan, bukan memenangkan pihak.","comparison":"Pertunjukan penuh atau pertemuan penuh tanpa perbandingan kebutuhan mengabaikan peluang menyatukan fungsi kegiatan.","check_question":"Tujuan bersama apa yang dapat menjadi dasar membandingkan usulan komite dan guru?","check_answer":"Menyepakati hasil yang ingin dicapai dan membandingkan rancangan berdasarkan kebutuhan keluarga serta manfaat bagi siswa baru. Alasannya: Komite dan guru memiliki tujuan hubungan keluarga yang sama tetapi bentuk berbeda. Dua jam perlu dirancang berdasarkan tujuan dan kebutuhan, bukan memenangkan pihak.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"220":{"concept":"Kesetaraan kesempatan dan akses","theory":"Kesempatan yang adil memperhatikan hambatan biaya, waktu, bahasa, dan akses. Perlakuan seragam dapat menghasilkan kesempatan berbeda ketika kebutuhan pengguna tidak sama.","why_correct":"Kebersamaan tidak mengharuskan praktik ibadah yang sama. Alternatif setara memungkinkan siswa berpartisipasi tanpa tekanan terhadap keyakinan.","comparison":"Memaksa ikut atau menganggap tidak hadir sebagai kurang kompak menyamakan partisipasi sosial dengan keseragaman ibadah.","check_question":"Apa yang perlu dijaga agar kegiatan alternatif tetap memberi rasa menjadi bagian dari kelas?","check_answer":"Menjelaskan penghormatan terhadap perbedaan dan menyediakan partisipasi alternatif yang setara sambil membangun relasi bersama. Alasannya: Kebersamaan tidak mengharuskan praktik ibadah yang sama. Alternatif setara memungkinkan siswa berpartisipasi tanpa tekanan terhadap keyakinan.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"221":{"concept":"Konflik kepentingan","theory":"Kepentingan pribadi dapat mengganggu independensi keputusan, termasuk ketika belum terbukti ada keberpihakan. Pengungkapan dan pemisahan peran melindungi proses dari pengaruh tersebut.","why_correct":"Hadiah tidak boleh membuat penilaian membaca bergantung pada kesediaan siswa melakukan promosi. Mitra bersedia membahas bentuk dukungan lain.","comparison":"Menerima syarat atau mengubah kriteria pemenang menggeser tujuan pendidikan ke kepentingan promosi.","check_question":"Mengapa syarat promosi perlu dipisahkan dari penentuan pemenang lomba baca?","check_answer":"Menegosiasikan hadiah tanpa kewajiban promosi siswa dan menjaga pemilihan pemenang berdasarkan kriteria membaca sekolah. Alasannya: Hadiah tidak boleh membuat penilaian membaca bergantung pada kesediaan siswa melakukan promosi. Mitra bersedia membahas bentuk dukungan lain.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"222":{"concept":"Komunikasi dua arah","theory":"Komunikasi efektif dinilai dari pemahaman penerima. Mendengar hambatan dan meminta klarifikasi membantu memperbaiki pesan serta respons, bukan hanya memperbanyak informasi.","why_correct":"Pilihan meminjam ada tetapi sulit ditemukan. Sekolah perlu memperjelas informasi dan menangani dampak pada keluarga yang telah membeli.","comparison":"Mengulang surat yang sama atau menyalahkan orang tua melewatkan kelemahan penyajian informasi.","check_question":"Apa yang salah pada komunikasi sekolah meskipun pilihan meminjam sudah tertulis?","check_answer":"Memperjelas pilihan peminjaman pada pesan utama dan membahas solusi keluarga yang sudah membeli tanpa menyalahkan pembaca. Alasannya: Pilihan meminjam ada tetapi sulit ditemukan. Sekolah perlu memperjelas informasi dan menangani dampak pada keluarga yang telah membeli.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"223":{"concept":"Penalaran berbasis bukti","theory":"Petunjuk, persepsi, dan hasil akhir mempunyai kekuatan serta batas berbeda. Kesimpulan perlu mengikuti bukti yang relevan dan diperiksa silang, bukan memilih data yang mendukung dugaan awal.","why_correct":"Dua penjelasan bertentangan dan saksi hanya melihat sebagian kejadian. Pemeriksaan perlu membedakan ajakan berdiskusi dari tekanan sebelum tindakan.","comparison":"Pengakuan satu pihak atau pelantikan cepat tidak menyelesaikan dugaan tekanan; tuduhan belum sama dengan bukti.","check_question":"Informasi saksi apa yang diperlukan untuk membedakan diskusi dan tekanan dalam pemilihan?","check_answer":"Memeriksa keterangan secara terpisah dan dampaknya pada pemilihan sebelum menetapkan pemulihan atau pengesahan hasil. Alasannya: Dua penjelasan bertentangan dan saksi hanya melihat sebagian kejadian. Pemeriksaan perlu membedakan ajakan berdiskusi dari tekanan sebelum tindakan.","reference":null,"reference_note":null},"224":{"concept":"Sekolah yang mempromosikan kesehatan","theory":"Pendekatan health-promoting school menghubungkan kebutuhan kesehatan siswa, pembelajaran, dan dukungan lintas sektor. Sekolah serta layanan kesehatan perlu mengoordinasikan perencanaan dan perannya.","why_correct":"Tujuan pemeriksaan dan pengelolaan hasil belum dijelaskan kepada keluarga. Kebutuhan bantuan segera perlu dipadukan dengan penjelasan serta pengaturan yang aman.","comparison":"Melaksanakan seluruh pemeriksaan dahulu atau menunda semua bantuan mengabaikan keseimbangan kebutuhan layanan dan pemahaman keluarga.","check_question":"Apa yang perlu dijelaskan kepada keluarga sebelum pemeriksaan kesehatan siswa berlangsung?","check_answer":"Menjelaskan tujuan dan alur hasil kepada keluarga serta mengatur dukungan mendesak melalui rujukan yang sesuai. Alasannya: Tujuan pemeriksaan dan pengelolaan hasil belum dijelaskan kepada keluarga. Kebutuhan bantuan segera perlu dipadukan dengan penjelasan serta pengaturan yang aman.","reference":{"title":"WHO–UNESCO (2021), Health-promoting schools: Global standards and indicators","url":"https://www.who.int/publications/i/item/9789240025059"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"225":{"concept":"Pembatasan tujuan dan akses informasi","theory":"Data pribadi digunakan untuk tujuan yang jelas dengan penerima dan akses yang sesuai kebutuhan. Kemudahan teknologi atau hubungan keluarga tidak otomatis memberi hak atas semua informasi.","why_correct":"Status kontak darurat tidak otomatis memberi kewenangan menerima catatan konseling. Penerima informasi dan kebutuhan perlindungan harus dikonfirmasi.","comparison":"Menyerahkan karena hubungan wali atau menolak tanpa klarifikasi tidak memeriksa batas kewenangan dan kepentingan siswa.","check_question":"Mengapa tercatat sebagai kontak darurat belum cukup untuk menerima seluruh catatan konseling?","check_answer":"Memverifikasi kewenangan menerima informasi dan kebutuhan pengungkapan sebelum menyerahkan bagian catatan yang memang relevan. Alasannya: Status kontak darurat tidak otomatis memberi kewenangan menerima catatan konseling. Penerima informasi dan kebutuhan perlindungan harus dikonfirmasi.","reference":null,"reference_note":null},"226":{"concept":"Partisipasi bermakna","theory":"Pihak terkait mempunyai kesempatan menyampaikan kebutuhan dan memeriksa dasar keputusan. Partisipasi bukan hanya hadir atau mendapat giliran, tetapi gagasannya dapat memengaruhi pembahasan.","why_correct":"Pemakaian lapangan dapat diuji dengan jam lebih awal, petugas, dan evaluasi dampak cahaya serta suara terhadap warga.","comparison":"Dukungan komunitas tidak menghapus keluhan; larangan penuh melewatkan alternatif uji yang sudah tersedia.","check_question":"Apa yang perlu dipantau selama uji dua malam agar kesepakatan dapat dievaluasi?","check_answer":"Menguji batas jam, cahaya, dan suara dengan tanggung jawab petugas serta saluran keluhan sebelum izin tetap. Alasannya: Pemakaian lapangan dapat diuji dengan jam lebih awal, petugas, dan evaluasi dampak cahaya serta suara terhadap warga.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"227":{"concept":"Partisipasi bermakna","theory":"Pihak terkait mempunyai kesempatan menyampaikan kebutuhan dan memeriksa dasar keputusan. Partisipasi bukan hanya hadir atau mendapat giliran, tetapi gagasannya dapat memengaruhi pembahasan.","why_correct":"Gagasan guru baru berguna di satu kelas tetapi belum diuji lebih luas. Ruang kontribusi dan uji gagasan membantu tim belajar tanpa mengandalkan senioritas.","comparison":"Memberi guru baru tugas mencatat saja atau mengadopsi langsung tanpa uji tidak menilai isi gagasannya secara proporsional.","check_question":"Bagaimana tim dapat menghargai gagasan guru baru sambil tetap memeriksa kecocokan pada kelas lain?","check_answer":"Memberi peran setara untuk membandingkan gagasan dan pengalaman, lalu menguji bagian penting sebelum menetapkan rancangan bersama. Alasannya: Gagasan guru baru berguna di satu kelas tetapi belum diuji lebih luas. Ruang kontribusi dan uji gagasan membantu tim belajar tanpa mengandalkan senioritas.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"228":{"concept":"Kesetaraan kesempatan dan akses","theory":"Kesempatan yang adil memperhatikan hambatan biaya, waktu, bahasa, dan akses. Perlakuan seragam dapat menghasilkan kesempatan berbeda ketika kebutuhan pengguna tidak sama.","why_correct":"Biaya sama menimbulkan beban berbeda dan pengajuan terbuka berisiko memberi stigma. Bantuan privat atau pengalaman setara perlu dipertimbangkan.","comparison":"Pemerataan biaya atau pengumuman penerima bantuan belum menjamin kesempatan belajar dan martabat keluarga.","check_question":"Mengapa bantuan yang harus diumumkan di kelas dapat menghambat siswa yang membutuhkan?","check_answer":"Mengatur bantuan secara rahasia dan menyediakan pilihan belajar setara sehingga akses tidak ditentukan kemampuan membayar. Alasannya: Biaya sama menimbulkan beban berbeda dan pengajuan terbuka berisiko memberi stigma. Bantuan privat atau pengalaman setara perlu dipertimbangkan.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"229":{"concept":"Keputusan proporsional terhadap risiko","theory":"Manfaat perlu ditimbang bersama bahaya, kemungkinan, dan dampaknya. Pengendalian disiapkan sebelum tindakan; skala kecil atau harga gratis tidak otomatis berarti tanpa risiko.","why_correct":"Rak tidak stabil perlu diamankan segera dengan pilihan berbiaya kecil. Dana utama kemudian dinilai menurut risiko tersisa dan dampak layanan.","comparison":"Membenahi administrasi tanpa mengamankan rak membiarkan risiko; membagi rata atau memakai semua dana untuk satu ruang melewatkan alternatif pengamanan.","check_question":"Mengapa pengamanan rak dapat dilakukan sebelum keputusan pembenahan penuh ditetapkan?","check_answer":"Mengamankan rak segera lalu membandingkan pembenahan berdasarkan risiko tersisa dan dampak layanan sebelum mengalokasikan dana utama. Alasannya: Rak tidak stabil perlu diamankan segera dengan pilihan berbiaya kecil. Dana utama kemudian dinilai menurut risiko tersisa dan dampak layanan.","reference":null,"reference_note":null},"230":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Kemampuan petugas berbeda: hanya satu dapat memimpin orientasi, sedangkan dua memahami laporan. Penugasan perlu menjaga pekerjaan yang tidak dapat digantikan.","comparison":"Pembagian sama rata atau menempatkan petugas khusus pada tugas yang bisa digantikan dapat meninggalkan orientasi tanpa pemimpin.","check_question":"Kemampuan petugas mana yang menjadi batas utama pembagian tugas hari itu?","check_answer":"Menugaskan pemimpin orientasi pada kegiatan siswa dan petugas lain menyelesaikan laporan dengan pemeriksaan pagi yang disepakati. Alasannya: Kemampuan petugas berbeda: hanya satu dapat memimpin orientasi, sedangkan dua memahami laporan. Penugasan perlu menjaga pekerjaan yang tidak dapat digantikan.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"231":{"concept":"Diagnosis sebelum intervensi","theory":"Gejala yang sama dapat mempunyai penyebab berbeda. Menelusuri pola dan menguji beberapa dugaan membantu memilih bantuan yang benar-benar menangani hambatan.","why_correct":"Tiga kelas mempunyai hambatan dan tenggat berbeda. Urutan pendampingan perlu mengikuti urgensi sekaligus bentuk bantuan yang sesuai penyebab.","comparison":"Satu solusi untuk semua atau urutan tanpa tenggat dapat membiarkan kelas paling mendesak tertunda.","check_question":"Apa dua dasar yang perlu dipakai untuk menentukan urutan dan isi pendampingan tiga kelas?","check_answer":"Mengurutkan dukungan berdasarkan urgensi tenggat dan jenis hambatan, lalu memantau penyelesaian tiap kelas sesuai kebutuhannya. Alasannya: Tiga kelas mempunyai hambatan dan tenggat berbeda. Urutan pendampingan perlu mengikuti urgensi sekaligus bentuk bantuan yang sesuai penyebab.","reference":null,"reference_note":null},"232":{"concept":"Penalaran berbasis bukti","theory":"Petunjuk, persepsi, dan hasil akhir mempunyai kekuatan serta batas berbeda. Kesimpulan perlu mengikuti bukti yang relevan dan diperiksa silang, bukan memilih data yang mendukung dugaan awal.","why_correct":"Peserta bermotivasi tinggi dapat memengaruhi kenaikan nilai. Evaluasi perlu membedakan kontribusi program dan karakter awal sebelum perluasan.","comparison":"Kenaikan peserta saja belum membuktikan rancangan memberi manfaat sama pada kelompok lain.","check_question":"Mengapa pemilihan siswa bermotivasi tinggi membatasi kesimpulan keberhasilan program?","check_answer":"Menguji dukungan pada kelompok dengan kebutuhan berbeda dan memeriksa perubahan dari kondisi awal sebelum menetapkan perluasan. Alasannya: Peserta bermotivasi tinggi dapat memengaruhi kenaikan nilai. Evaluasi perlu membedakan kontribusi program dan karakter awal sebelum perluasan.","reference":null,"reference_note":null},"233":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Hibah dan titipan enam bulan mempunyai status serta tanggung jawab berbeda. Inventaris perlu mencatat pembedaan itu meskipun sistem awal belum menyediakan kolom.","comparison":"Mencatat semua sebagai milik sekolah atau mengabaikan titipan tidak menggambarkan hak dan kewajiban penggunaan.","check_question":"Informasi status apa yang harus dibedakan pada dua proyektor tersebut?","check_answer":"Mencatat identitas dan status berbeda melalui catatan pendukung, lalu menetapkan tanggung jawab penggunaan serta perawatan tiap perangkat. Alasannya: Hibah dan titipan enam bulan mempunyai status serta tanggung jawab berbeda. Inventaris perlu mencatat pembedaan itu meskipun sistem awal belum menyediakan kolom.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"234":{"concept":"Evaluasi proses dan hasil","theory":"Keterlaksanaan, jumlah peserta, dan kelengkapan laporan menunjukkan proses. Manfaat program perlu diperiksa pada perubahan yang menjadi tujuan, dengan pembanding kondisi awal yang sesuai.","why_correct":"Pertemuan yang ramai menunjukkan kegiatan berlangsung, tetapi sasaran program adalah dukungan belajar keluarga. Wawancara dapat memberi bukti manfaat yang lebih dekat pada tujuan.","comparison":"Kehadiran dan jumlah pertemuan saja tidak menunjukkan perubahan komunikasi atau dukungan di rumah.","check_question":"Apa yang perlu ditanyakan kepada keluarga agar evaluasi tidak berhenti pada jumlah pertemuan?","check_answer":"Melaporkan pertemuan sebagai proses dan menambah bukti perubahan dukungan keluarga melalui sampel dengan keterbatasan yang dinyatakan. Alasannya: Pertemuan yang ramai menunjukkan kegiatan berlangsung, tetapi sasaran program adalah dukungan belajar keluarga. Wawancara dapat memberi bukti manfaat yang lebih dekat pada tujuan.","reference":null,"reference_note":null},"235":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Jeda guru dapat digabungkan dalam penugasan terkoordinasi dan bahan bersama, dengan pengawasan pada praktik yang memerlukannya.","comparison":"Tugas mandiri penuh atau meminta satu guru mengambil seluruh jadwal tidak sesuai kapasitas dan risiko kegiatan.","check_question":"Bagian pembelajaran mana yang wajib mendapat pengawasan langsung selama guru berhalangan?","check_answer":"Menyusun giliran pendampingan dengan bahan terhubung dan menjadwalkan praktik saat guru yang sesuai tersedia. Alasannya: Jeda guru dapat digabungkan dalam penugasan terkoordinasi dan bahan bersama, dengan pengawasan pada praktik yang memerlukannya.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"236":{"concept":"Keputusan proporsional terhadap risiko","theory":"Manfaat perlu ditimbang bersama bahaya, kemungkinan, dan dampaknya. Pengendalian disiapkan sebelum tindakan; skala kecil atau harga gratis tidak otomatis berarti tanpa risiko.","why_correct":"Perubahan mengurangi antrean tetapi menciptakan paparan kendaraan pemasok. Menjadwal ulang pemasok menangani bahaya pada sumbernya.","comparison":"Menilai sukses dari antrean saja melewatkan risiko baru; satu petugas tidak otomatis meniadakan konflik jalur kendaraan.","check_question":"Mengapa berkurangnya antrean belum cukup untuk menyatakan alur masuk aman?","check_answer":"Memisahkan waktu pemasok dan kedatangan siswa lalu menguji alur dengan pengawasan pada titik pertemuan yang berisiko. Alasannya: Perubahan mengurangi antrean tetapi menciptakan paparan kendaraan pemasok. Menjadwal ulang pemasok menangani bahaya pada sumbernya.","reference":null,"reference_note":null},"237":{"concept":"Pengembangan profesional berbasis praktik","theory":"Belajar guru dihubungkan dengan kebutuhan kelas, uji perubahan yang terjangkau, dan refleksi atas bukti penerapan. Kehadiran pelatihan belum memastikan perubahan praktik.","why_correct":"Kebutuhan umpan balik ada pada delapan guru, sedangkan pelatihan memuat empat peserta yang dapat menguji praktik dan mendampingi rekan. Rencana transfer memperluas manfaat.","comparison":"Jumlah peserta langsung yang lebih besar belum tentu memenuhi kebutuhan utama; transfer tanpa uji belum memastikan mutu.","check_question":"Bagaimana pelatihan empat guru dapat menjawab kebutuhan delapan guru secara bertanggung jawab?","check_answer":"Memilih empat peserta berdasarkan kebutuhan dan kemampuan mendampingi, lalu merancang uji serta berbagi praktik bagi delapan guru. Alasannya: Kebutuhan umpan balik ada pada delapan guru, sedangkan pelatihan memuat empat peserta yang dapat menguji praktik dan mendampingi rekan. Rencana transfer memperluas manfaat.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"238":{"concept":"Penalaran berbasis bukti","theory":"Petunjuk, persepsi, dan hasil akhir mempunyai kekuatan serta batas berbeda. Kesimpulan perlu mengikuti bukti yang relevan dan diperiksa silang, bukan memilih data yang mendukung dugaan awal.","why_correct":"Semua 128 siswa hadir dan memerlukan tempat, walaupun delapan belum lengkap dokumennya. Kebutuhan riil perlu dicatat bersama status administrasi.","comparison":"Angka 120 saja mengurangi kebutuhan layanan nyata; menyamakan seluruh status tanpa keterangan menghilangkan ketepatan administrasi.","check_question":"Mengapa kebutuhan tempat tidak boleh dihitung hanya dari siswa yang sudah aktif di aplikasi?","check_answer":"Menyebut 120 status terkonfirmasi dan kebutuhan layanan 128 siswa dengan keterangan serta rencana pemutakhiran dokumen. Alasannya: Semua 128 siswa hadir dan memerlukan tempat, walaupun delapan belum lengkap dokumennya. Kebutuhan riil perlu dicatat bersama status administrasi.","reference":null,"reference_note":null},"239":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Pemeriksaan jumlah berulang tetapi kesesuaian bahan belum diperiksa. Alur perlu membedakan fungsi kontrol dan menghapus pengulangan yang tidak menambah jaminan.","comparison":"Menambah persetujuan atau menghapus semua pemeriksaan tidak mengatasi kekosongan pemeriksaan mutu bahan.","check_question":"Pemeriksaan apa yang belum ada meskipun pembelian melewati tiga persetujuan?","check_answer":"Membedakan fungsi pemeriksaan dan persetujuan, menghapus pengulangan internal, serta menetapkan pemeriksa mutu bahan dengan batas waktu. Alasannya: Pemeriksaan jumlah berulang tetapi kesesuaian bahan belum diperiksa. Alur perlu membedakan fungsi kontrol dan menghapus pengulangan yang tidak menambah jaminan.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"240":{"concept":"Pembatasan tujuan dan akses informasi","theory":"Data pribadi digunakan untuk tujuan yang jelas dengan penerima dan akses yang sesuai kebutuhan. Kemudahan teknologi atau hubungan keluarga tidak otomatis memberi hak atas semua informasi.","why_correct":"Catatan konseling membutuhkan pembatasan akses berbeda dari jadwal umum. Cadangan juga harus diuji agar benar-benar dapat dipulihkan.","comparison":"Akses penuh atau keberadaan cadangan saja belum menjamin kerahasiaan dan ketersediaan dokumen.","check_question":"Apa dua kelemahan berbeda dalam pengaturan folder dan cadangan sekolah ini?","check_answer":"Memisahkan akses menurut kebutuhan kerja dan sensitivitas, lalu menguji cadangan serta pemulihan dengan penanggung jawab jelas. Alasannya: Catatan konseling membutuhkan pembatasan akses berbeda dari jadwal umum. Cadangan juga harus diuji agar benar-benar dapat dipulihkan.","reference":null,"reference_note":null},"241":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Dua daftar muncul karena kewenangan perubahan dan keputusan akhir belum jelas. Versi bersama serta penanggung jawab keputusan menjaga koordinasi.","comparison":"Memilih daftar terbaru tanpa aturan atau meminta staf menyatukan sendiri belum menetapkan kewenangan perubahan.","check_question":"Apa yang perlu diperjelas agar wali kelas dan tim layanan tidak menerbitkan dua daftar penerima?","check_answer":"Menetapkan satu pemilik daftar final, peran pemberi masukan, dan alur perubahan yang diketahui seluruh pelaksana bantuan. Alasannya: Dua daftar muncul karena kewenangan perubahan dan keputusan akhir belum jelas. Versi bersama serta penanggung jawab keputusan menjaga koordinasi.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"242":{"concept":"Kesetaraan kesempatan dan akses","theory":"Kesempatan yang adil memperhatikan hambatan biaya, waktu, bahasa, dan akses. Perlakuan seragam dapat menghasilkan kesempatan berbeda ketika kebutuhan pengguna tidak sama.","why_correct":"Pemakaian alat meningkat tetapi akses sebagian kelas menurun karena transportasi. Pertukaran jadwal memungkinkan tujuan praktik tercapai lebih merata.","comparison":"Rata-rata pemakaian alat tidak menunjukkan kesempatan setiap kelompok; mempertahankan jadwal mengabaikan hambatan akses.","check_question":"Mengapa peningkatan pemakaian alat belum membuktikan jadwal baru lebih baik bagi semua kelas?","check_answer":"Menguji pertukaran sesi berdasarkan kebutuhan transportasi sambil menjaga penggunaan alat dan memantau kesempatan praktik tiap kelas. Alasannya: Pemakaian alat meningkat tetapi akses sebagian kelas menurun karena transportasi. Pertukaran jadwal memungkinkan tujuan praktik tercapai lebih merata.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"243":{"concept":"Uji perbaikan secara bertahap","theory":"Inovasi diperlakukan sebagai gagasan yang perlu diuji terhadap masalah tertentu. Tujuan, indikator, hasil uji, dan penyesuaian menghubungkan percobaan dengan keputusan perluasan.","why_correct":"Penyebab koreksi tidak digunakan belum diketahui. Sarana kertas memungkinkan uji umpan balik yang dapat ditindaklanjuti sebelum membeli alat.","comparison":"Daya tarik alat atau komentar lama pada media lain belum memastikan hambatan pemanfaatan koreksi teratasi.","check_question":"Mengapa uji perlu mengubah keterpakaian umpan balik, bukan sekadar mengganti medianya?","check_answer":"Memeriksa penyebab dan menguji umpan balik yang dapat ditindaklanjuti dengan sarana tersedia sebelum memilih kebutuhan alat digital. Alasannya: Penyebab koreksi tidak digunakan belum diketahui. Sarana kertas memungkinkan uji umpan balik yang dapat ditindaklanjuti sebelum membeli alat.","reference":null,"reference_note":null},"244":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Tujuan desain dan batas bahan perlu menjadi dasar negosiasi produk jual agar siswa tetap membuat keputusan kreatif dalam empat pertemuan.","comparison":"Pola seragam atau meniru contoh dapat mengurangi pengalaman merancang; karya bebas tanpa alokasi melewatkan batas bahan dan waktu.","check_question":"Bagaimana produk untuk dijual dapat dirancang tanpa menghilangkan kesempatan keputusan kreatif siswa?","check_answer":"Menetapkan capaian desain dan batas bahan, lalu menegosiasikan produk jual yang tetap memberi ruang keputusan siswa. Alasannya: Tujuan desain dan batas bahan perlu menjadi dasar negosiasi produk jual agar siswa tetap membuat keputusan kreatif dalam empat pertemuan.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"245":{"concept":"Diagnosis sebelum intervensi","theory":"Gejala yang sama dapat mempunyai penyebab berbeda. Menelusuri pola dan menguji beberapa dugaan membantu memilih bantuan yang benar-benar menangani hambatan.","why_correct":"Keterlambatan berkaitan dengan jadwal pengembalian dan label yang tidak jelas. Rancangan layanan perlu diperbaiki pada dua hambatan itu.","comparison":"Denda saja memperkuat konsekuensi tanpa memastikan siswa memiliki cara memenuhi aturan yang mudah dipahami.","check_question":"Mengapa menambah denda belum menyelesaikan dua penyebab keterlambatan alat?","check_answer":"Menguji waktu pengembalian yang layak dan identifikasi alat sebelum menilai perlunya konsekuensi tambahan. Alasannya: Keterlambatan berkaitan dengan jadwal pengembalian dan label yang tidak jelas. Rancangan layanan perlu diperbaiki pada dua hambatan itu.","reference":null,"reference_note":null},"246":{"concept":"Keputusan proporsional terhadap risiko","theory":"Manfaat perlu ditimbang bersama bahaya, kemungkinan, dan dampaknya. Pengendalian disiapkan sebelum tindakan; skala kecil atau harga gratis tidak otomatis berarti tanpa risiko.","why_correct":"Pameran malam memberi akses keluarga bekerja tetapi jalur pulang kurang terang. Transportasi bersama dapat menjadi pengendalian dengan biaya terukur.","comparison":"Ruang acara aman belum membuat perjalanan pulang aman; akses keluarga perlu disertai pengendalian risiko.","check_question":"Risiko apa yang masih perlu ditangani walaupun ruang pameran sudah aman?","check_answer":"Menetapkan pengamanan jalur dan transportasi sebagai syarat, lalu menguji skala kegiatan yang dapat memenuhi batas keselamatan. Alasannya: Pameran malam memberi akses keluarga bekerja tetapi jalur pulang kurang terang. Transportasi bersama dapat menjadi pengendalian dengan biaya terukur.","reference":null,"reference_note":null},"247":{"concept":"Penyesuaian dukungan dan tantangan","theory":"Tujuan dapat tetap sama sementara bantuan, cara menunjukkan pemahaman, dan kedalaman tantangan disesuaikan. Variasi dibuat berdasarkan bukti kebutuhan, bukan label kemampuan yang tetap.","why_correct":"Pengguna ramai belum berarti tantangan dapat diakses semua siswa. Dukungan awal perlu membantu siswa kurang percaya diri masuk ke eksplorasi.","comparison":"Memperluas ruang tanpa penyesuaian dapat memperbesar pola hanya siswa tertentu yang mendapat manfaat.","check_question":"Dukungan apa yang perlu diuji sebelum ruang eksplorasi diperluas ke semua kelas?","check_answer":"Menguji bantuan masuk yang bertahap dan pilihan tantangan untuk melihat apakah kelompok berbeda mendapat manfaat sebelum perluasan. Alasannya: Pengguna ramai belum berarti tantangan dapat diakses semua siswa. Dukungan awal perlu membantu siswa kurang percaya diri masuk ke eksplorasi.","reference":null,"reference_note":null},"248":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Tiga sesi terbatas perlu dipilih untuk memperluas wawasan pekerjaan, termasuk bidang yang belum dikenal siswa.","comparison":"Ketenaran alumni atau pekerjaan yang sudah dikenal saja dapat mempertahankan pandangan sempit tentang dunia kerja.","check_question":"Mengapa pengalaman alumni di bidang layanan yang jarang terlihat bernilai bagi tujuan proyek?","check_answer":"Memilih pengalaman beragam yang terkait tujuan belajar dan mengajak siswa membandingkan kontribusi, keterampilan, serta proses pengembangannya. Alasannya: Tiga sesi terbatas perlu dipilih untuk memperluas wawasan pekerjaan, termasuk bidang yang belum dikenal siswa.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"249":{"concept":"Pembatasan tujuan dan akses informasi","theory":"Data pribadi digunakan untuk tujuan yang jelas dengan penerima dan akses yang sesuai kebutuhan. Kemudahan teknologi atau hubungan keluarga tidak otomatis memberi hak atas semua informasi.","why_correct":"Refleksi berisi nama dan persoalan pribadi, sedangkan pengelolaan data layanan AI belum jelas. Uji perlu meminimalkan paparan data dan memakai alternatif yang tersedia.","comparison":"Gratisnya layanan atau kemudahan rangkuman tidak membenarkan unggahan identitas serta masalah pribadi tanpa pengamanan.","check_question":"Informasi apa yang tidak semestinya langsung dikirim ke layanan AI yang tata kelola datanya belum jelas?","check_answer":"Menilai keamanan layanan sebelum uji tanpa data pribadi dan memeriksa ringkasan terhadap sampel yang ditelaah guru. Alasannya: Refleksi berisi nama dan persoalan pribadi, sedangkan pengelolaan data layanan AI belum jelas. Uji perlu meminimalkan paparan data dan memakai alternatif yang tersedia.","reference":null,"reference_note":null},"250":{"concept":"Keputusan proporsional terhadap risiko","theory":"Manfaat perlu ditimbang bersama bahaya, kemungkinan, dan dampaknya. Pengendalian disiapkan sebelum tindakan; skala kecil atau harga gratis tidak otomatis berarti tanpa risiko.","why_correct":"Printer gratis memerlukan tinta khusus dengan biaya tiga tahun lebih tinggi. Demonstrasi dapat menguji apakah fitur tambahannya benar-benar memberi manfaat yang sepadan.","comparison":"Harga awal nol tidak menghapus biaya pemakaian dan ketergantungan pemasok; fitur yang belum diuji belum membenarkan biaya tambahan.","check_question":"Apa yang harus dibandingkan selain harga awal printer?","check_answer":"Menguji manfaat fitur dan membandingkan biaya penggunaan serta dukungan sebelum menerima kewajiban pemeliharaan printer. Alasannya: Printer gratis memerlukan tinta khusus dengan biaya tiga tahun lebih tinggi. Demonstrasi dapat menguji apakah fitur tambahannya benar-benar memberi manfaat yang sepadan.","reference":null,"reference_note":null},"251":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Guru mengedit hampir semua bagian sehingga karya bagus belum menunjukkan siswa memilih bukti dan menyusun argumen. Perbaikan perlu mengembalikan keputusan inti pada siswa.","comparison":"Kualitas produk lomba atau hasil editing guru tidak membuktikan capaian belajar siswa.","check_question":"Bagian pekerjaan apa yang perlu dilakukan siswa sendiri agar karya menjadi bukti kemampuan mereka?","check_answer":"Membatasi bantuan pada pendampingan dan meminta bukti keputusan siswa dalam karya revisi yang dinilai dengan tujuan awal. Alasannya: Guru mengedit hampir semua bagian sehingga karya bagus belum menunjukkan siswa memilih bukti dan menyusun argumen. Perbaikan perlu mengembalikan keputusan inti pada siswa.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"252":{"concept":"Keputusan proporsional terhadap risiko","theory":"Manfaat perlu ditimbang bersama bahaya, kemungkinan, dan dampaknya. Pengendalian disiapkan sebelum tindakan; skala kecil atau harga gratis tidak otomatis berarti tanpa risiko.","why_correct":"Pemilahan melibatkan bahan tajam yang belum dipahami siswa. Bahan aman di sekolah memberi tahap persiapan sebelum kunjungan.","comparison":"Kunjungan langsung atau keterampilan memilah saja tidak memastikan kesiapan terhadap bahaya bahan.","check_question":"Mengapa latihan dengan bahan aman sebaiknya mendahului kunjungan ke usaha daur ulang?","check_answer":"Mengawali proyek dengan bahan aman, keterampilan pemilahan, dan pengendalian risiko sebelum menilai kesiapan kunjungan ke mitra. Alasannya: Pemilahan melibatkan bahan tajam yang belum dipahami siswa. Bahan aman di sekolah memberi tahap persiapan sebelum kunjungan.","reference":null,"reference_note":null},"253":{"concept":"Asesmen dan umpan balik formatif","theory":"Informasi tentang belajar digunakan untuk menentukan langkah perbaikan. Umpan balik bernilai ketika siswa atau guru memahami dan dapat memakai informasi itu dalam tindakan berikutnya.","why_correct":"Jumlah pertanyaan meningkat tetapi banyak menyalin. Pertanyaan asli yang mengungkap salah paham dapat menjadi dasar umpan balik dan tindak lanjut.","comparison":"Jumlah saja menggabungkan penyalinan dan pertanyaan bermakna sehingga mutu penalaran tidak terlihat.","check_question":"Pertanyaan jenis apa yang paling membantu guru menyesuaikan pembelajaran berikutnya?","check_answer":"Menilai keragaman penalaran dan menggunakan salah paham sebagai bahan dialog, lalu memantau perubahan kualitas pertanyaan siswa. Alasannya: Jumlah pertanyaan meningkat tetapi banyak menyalin. Pertanyaan asli yang mengungkap salah paham dapat menjadi dasar umpan balik dan tindak lanjut.","reference":{"title":"EEF (2021), Teacher Feedback to Improve Pupil Learning","url":"https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/feedback"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"254":{"concept":"Kesetaraan kesempatan dan akses","theory":"Kesempatan yang adil memperhatikan hambatan biaya, waktu, bahasa, dan akses. Perlakuan seragam dapat menghasilkan kesempatan berbeda ketika kebutuhan pengguna tidak sama.","why_correct":"Kode digital sulit dipakai siswa kecil sehingga efisiensi yang diharapkan belum tercapai. Jalur kartu dapat menjaga akses dengan catatan bersama.","comparison":"Memaksa satu jalur atau mempertahankan input berulang tidak menyelesaikan hambatan pengguna.","check_question":"Mengapa dua jalur layanan dapat lebih efektif daripada mewajibkan satu kode digital bagi semua siswa?","check_answer":"Menguji kartu dan kode sesuai kemampuan pengguna dengan pencatatan terpadu, lalu menilai kecepatan serta akses layanan. Alasannya: Kode digital sulit dipakai siswa kecil sehingga efisiensi yang diharapkan belum tercapai. Jalur kartu dapat menjaga akses dengan catatan bersama.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"255":{"concept":"Keputusan proporsional terhadap risiko","theory":"Manfaat perlu ditimbang bersama bahaya, kemungkinan, dan dampaknya. Pengendalian disiapkan sebelum tindakan; skala kecil atau harga gratis tidak otomatis berarti tanpa risiko.","why_correct":"Dana pasti cukup untuk satu kelompok dan pembelian tidak dapat dibatalkan. Komitmen awal perlu mengikuti dana pasti, dengan perluasan setelah dukungan terkonfirmasi.","comparison":"Janji donasi untuk tiga kelompok belum menyediakan kepastian menanggung kontrak yang tidak bisa dibatalkan.","check_question":"Mengapa sifat kontrak tidak dapat dibatalkan penting dalam keputusan skala program?","check_answer":"Memulai kelompok prioritas dengan dana pasti dan menetapkan perluasan setelah donasi terkonfirmasi sebelum menambah komitmen pembelian. Alasannya: Dana pasti cukup untuk satu kelompok dan pembelian tidak dapat dibatalkan. Komitmen awal perlu mengikuti dana pasti, dengan perluasan setelah dukungan terkonfirmasi.","reference":null,"reference_note":null},"256":{"concept":"Diagnosis sebelum intervensi","theory":"Gejala yang sama dapat mempunyai penyebab berbeda. Menelusuri pola dan menguji beberapa dugaan membantu memilih bantuan yang benar-benar menangani hambatan.","why_correct":"Minat ada tetapi jadwal transportasi menghalangi hadir. Uji sesi sebelum pulang menangani hambatan akses yang sudah disebut siswa.","comparison":"Hadiah kehadiran menambah motivasi tetapi tidak menyediakan transportasi atau waktu yang sesuai.","check_question":"Mengapa hadiah kehadiran mungkin tidak mengatasi rendahnya partisipasi klub ini?","check_answer":"Menguji sesi yang sesuai akses siswa dan membandingkan partisipasi serta manfaat sebelum menambah insentif kehadiran. Alasannya: Minat ada tetapi jadwal transportasi menghalangi hadir. Uji sesi sebelum pulang menangani hambatan akses yang sudah disebut siswa.","reference":null,"reference_note":null},"257":{"concept":"Penalaran berbasis bukti","theory":"Petunjuk, persepsi, dan hasil akhir mempunyai kekuatan serta batas berbeda. Kesimpulan perlu mengikuti bukti yang relevan dan diperiksa silang, bukan memilih data yang mendukung dugaan awal.","why_correct":"Jawaban kelompok benar dapat berasal dari satu anggota. Pemahaman individual dan pola peran perlu diperiksa sebelum menyimpulkan kerja sama berhasil.","comparison":"Giliran bicara saja tidak membuktikan pemahaman; satu hasil benar belum mewakili kontribusi seluruh anggota.","check_question":"Bukti apa yang dibutuhkan untuk memastikan semua anggota memahami jawaban kelompok?","check_answer":"Menguji pemahaman individual dan pola peran, lalu menyepakati perbaikan kesempatan menjelaskan berdasarkan bukti tambahan. Alasannya: Jawaban kelompok benar dapat berasal dari satu anggota. Pemahaman individual dan pola peran perlu diperiksa sebelum menyimpulkan kerja sama berhasil.","reference":null,"reference_note":null},"258":{"concept":"Supervisi untuk perbaikan pembelajaran","theory":"Observasi menghasilkan bukti yang dibahas melalui refleksi dan tindak lanjut. Keberhasilan ditelusuri pada perubahan praktik serta pengalaman siswa, bukan jumlah observasi saja.","why_correct":"Rencana memuat diskusi tetapi pekerjaan siswa menunjukkan alasan lemah. Observasi fokus pada interaksi relevan membantu menguji pelaksanaan, dengan satu perbaikan terjangkau.","comparison":"Dokumen atau pekerjaan saja tidak menunjukkan bagaimana interaksi berlangsung; revisi rencana belum membuktikan perubahan praktik.","check_question":"Mengapa melihat rencana diskusi belum cukup untuk mengetahui penyebab alasan siswa lemah?","check_answer":"Menetapkan fokus pada alasan jawaban dan mengamati interaksi relevan untuk memilih satu perbaikan yang dapat diuji. Alasannya: Rencana memuat diskusi tetapi pekerjaan siswa menunjukkan alasan lemah. Observasi fokus pada interaksi relevan membantu menguji pelaksanaan, dengan satu perbaikan terjangkau.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"259":{"concept":"Asesmen dan umpan balik formatif","theory":"Informasi tentang belajar digunakan untuk menentukan langkah perbaikan. Umpan balik bernilai ketika siswa atau guru memahami dan dapat memakai informasi itu dalam tindakan berikutnya.","why_correct":"Masukan diberikan menjelang pulang tanpa waktu revisi. Umpan balik memerlukan kesempatan siswa memakai informasi, bukan hanya menerimanya.","comparison":"Mengubah masukan menjadi angka atau menambah komentar tanpa waktu tindak lanjut tidak menyelesaikan hambatan penggunaan.","check_question":"Apa unsur proses yang hilang sehingga umpan balik lisan tidak mengubah pekerjaan siswa?","check_answer":"Menguji masukan dengan waktu revisi dan memeriksa penggunaan umpan balik sebelum menyimpulkan bahwa cara lisan tidak efektif. Alasannya: Masukan diberikan menjelang pulang tanpa waktu revisi. Umpan balik memerlukan kesempatan siswa memakai informasi, bukan hanya menerimanya.","reference":{"title":"EEF (2021), Teacher Feedback to Improve Pupil Learning","url":"https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/feedback"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"260":{"concept":"Penyesuaian dukungan dan tantangan","theory":"Tujuan dapat tetap sama sementara bantuan, cara menunjukkan pemahaman, dan kedalaman tantangan disesuaikan. Variasi dibuat berdasarkan bukti kebutuhan, bukan label kemampuan yang tetap.","why_correct":"Tujuan sama dapat dicapai dengan petunjuk bertahap dan pengayaan dari bahan yang sama. Variasi dukungan tidak selalu memerlukan banyak bahan baru.","comparison":"Tugas seragam atau bahan berbeda untuk semua tidak mempertimbangkan cara sederhana menyesuaikan bantuan.","check_question":"Bagaimana satu bahan bacaan dapat digunakan untuk kebutuhan belajar yang berbeda?","check_answer":"Menggunakan bahan inti sama dengan petunjuk dan tantangan berbeda, lalu menilai kemajuan untuk menyesuaikan bantuan tiap kelompok. Alasannya: Tujuan sama dapat dicapai dengan petunjuk bertahap dan pengayaan dari bahan yang sama. Variasi dukungan tidak selalu memerlukan banyak bahan baru.","reference":null,"reference_note":null},"261":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Aktif memilih langkah dalam permainan belum membuktikan pemahaman pecahan jika siswa menebak. Penjelasan singkat dapat menunjukkan alasan tanpa menghilangkan permainan.","comparison":"Antusiasme atau skor permainan saja tidak memisahkan strategi bernalar dari tebakan.","check_question":"Bukti respons apa yang dapat membedakan siswa memahami pecahan dan siswa sekadar menebak?","check_answer":"Menggunakan penjelasan pilihan untuk menghubungkan permainan dengan konsep dan menilai perubahan pemahaman pada putaran berikutnya. Alasannya: Aktif memilih langkah dalam permainan belum membuktikan pemahaman pecahan jika siswa menebak. Penjelasan singkat dapat menunjukkan alasan tanpa menghilangkan permainan.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"262":{"concept":"Asesmen dan umpan balik formatif","theory":"Informasi tentang belajar digunakan untuk menentukan langkah perbaikan. Umpan balik bernilai ketika siswa atau guru memahami dan dapat memakai informasi itu dalam tindakan berikutnya.","why_correct":"Istilah komentar belum dipahami dan kesalahan berulang. Umpan balik perlu bahasa yang dapat digunakan siswa serta kesempatan perbaikan yang efisien.","comparison":"Komentar makin panjang atau pengurangan komentar tanpa arah belum menjamin siswa memahami langkah revisi.","check_question":"Apa yang perlu berubah agar komentar esai benar-benar dapat digunakan siswa?","check_answer":"Memakai contoh serta bahasa yang dipahami siswa untuk pola umum, dengan masukan khusus dan kesempatan revisi terarah. Alasannya: Istilah komentar belum dipahami dan kesalahan berulang. Umpan balik perlu bahasa yang dapat digunakan siswa serta kesempatan perbaikan yang efisien.","reference":{"title":"EEF (2021), Teacher Feedback to Improve Pupil Learning","url":"https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/feedback"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"263":{"concept":"Pengembangan profesional berbasis praktik","theory":"Belajar guru dihubungkan dengan kebutuhan kelas, uji perubahan yang terjangkau, dan refleksi atas bukti penerapan. Kehadiran pelatihan belum memastikan perubahan praktik.","why_correct":"Teknik baru terhenti karena penilaian padat dan laporan panjang. Dukungan perlu menyesuaikan beban serta memakai bukti respons yang sudah tersedia.","comparison":"Menambah laporan atau mengulang pelatihan tanpa pengaturan beban tidak menyelesaikan hambatan penerapan.","check_question":"Bukti apa yang dapat dipakai agar pemantauan praktik tidak menambah laporan harian panjang?","check_answer":"Memilih uji kecil yang realistis dan menyederhanakan bukti monitoring dengan rekaman respons yang menunjukkan perubahan praktik. Alasannya: Teknik baru terhenti karena penilaian padat dan laporan panjang. Dukungan perlu menyesuaikan beban serta memakai bukti respons yang sudah tersedia.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"264":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Rubrik menilai mutu alasan, bukan kecepatan menulis. Penjelasan lisan dengan rubrik sama mempertahankan konstruk yang dinilai sambil mengurangi hambatan akses.","comparison":"Menurunkan standar atau memaksakan tulisan cepat dapat mengukur kemampuan yang bukan sasaran asesmen.","check_question":"Mengapa jawaban lisan dapat tetap adil jika tujuan dan rubrik asesmennya sama?","check_answer":"Mengizinkan respons lisan tercatat dengan rubrik alasan yang sama dan menjelaskan bahwa dukungan menjaga kesetaraan pengukuran. Alasannya: Rubrik menilai mutu alasan, bukan kecepatan menulis. Penjelasan lisan dengan rubrik sama mempertahankan konstruk yang dinilai sambil mengurangi hambatan akses.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"265":{"concept":"Pengembangan profesional berbasis praktik","theory":"Belajar guru dihubungkan dengan kebutuhan kelas, uji perubahan yang terjangkau, dan refleksi atas bukti penerapan. Kehadiran pelatihan belum memastikan perubahan praktik.","why_correct":"Fokus bukti sudah dikuasai dua guru yang mempunyai kebutuhan partisipasi berbeda. Instrumen ringkas dapat memuat inti bersama dan fokus pengembangan individual.","comparison":"Instrumen sama persis atau fokus tunggal mengabaikan kebutuhan guru yang telah kuat pada sasaran awal.","check_question":"Bagaimana instrumen ringkas dapat menjaga fokus sekolah sambil mengakomodasi kebutuhan dua guru?","check_answer":"Mempertahankan tujuan bersama dengan fokus tambahan sesuai kebutuhan guru dan indikator ringkas yang menangkap perubahan relevan. Alasannya: Fokus bukti sudah dikuasai dua guru yang mempunyai kebutuhan partisipasi berbeda. Instrumen ringkas dapat memuat inti bersama dan fokus pengembangan individual.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"266":{"concept":"Penyesuaian dukungan dan tantangan","theory":"Tujuan dapat tetap sama sementara bantuan, cara menunjukkan pemahaman, dan kedalaman tantangan disesuaikan. Variasi dibuat berdasarkan bukti kebutuhan, bukan label kemampuan yang tetap.","why_correct":"Latihan awal membantu menentukan siapa yang masih memerlukan contoh dan siapa yang siap mencoba mandiri.","comparison":"Contoh penuh untuk semua membuat sebagian siswa pasif; menghapus semua contoh meninggalkan siswa yang membutuhkan bantuan.","check_question":"Untuk apa hasil latihan awal digunakan sebelum guru menentukan banyaknya contoh?","check_answer":"Menggunakan bukti latihan awal untuk membedakan kebutuhan contoh dan tantangan mandiri, lalu menyesuaikan bantuan selama pelajaran. Alasannya: Latihan awal membantu menentukan siapa yang masih memerlukan contoh dan siapa yang siap mencoba mandiri.","reference":null,"reference_note":null},"267":{"concept":"Transfer praktik dengan perhatian pada konteks","theory":"Praktik rujukan perlu dibedakan antara bentuk kegiatan dan mekanisme yang membuatnya bermanfaat. Penerapan pada konteks baru memerlukan penyesuaian dan bukti, bukan penyalinan bentuk saja.","why_correct":"Mengisi tabel dari contoh dan memilih tabel pada informasi baru merupakan tuntutan berbeda. Asesmen perlu menguji pemilihan strategi tanpa menyalin pola.","comparison":"Latihan serupa tidak cukup membuktikan transfer ke situasi baru meskipun jawaban awal benar.","check_question":"Apa yang belum dibuktikan oleh keberhasilan siswa mengisi tabel mengikuti contoh?","check_answer":"Menelaah perbedaan meniru dan memilih strategi, lalu menguji dukungan yang membantu siswa menjelaskan keputusan pada konteks baru. Alasannya: Mengisi tabel dari contoh dan memilih tabel pada informasi baru merupakan tuntutan berbeda. Asesmen perlu menguji pemilihan strategi tanpa menyalin pola.","reference":null,"reference_note":null},"268":{"concept":"Transfer praktik dengan perhatian pada konteks","theory":"Praktik rujukan perlu dibedakan antara bentuk kegiatan dan mekanisme yang membuatnya bermanfaat. Penerapan pada konteks baru memerlukan penyesuaian dan bukti, bukan penyalinan bentuk saja.","why_correct":"Praktik kelompok enam siswa perlu disesuaikan untuk tiga puluh siswa. Pertanyaan awal, peran, dan rangkuman alasan dapat diuji sebagai unsur inti.","comparison":"Menyalin jumlah kelompok atau seluruh bentuk kegiatan belum memastikan mekanisme diskusi bekerja pada kelas lebih besar.","check_question":"Unsur apa yang perlu dipertahankan ketika bentuk diskusi disesuaikan untuk tiga puluh siswa?","check_answer":"Mengidentifikasi fungsi unsur inti dan menguji adaptasi peran serta pertanyaan pada kelompok yang sesuai kapasitas kelas. Alasannya: Praktik kelompok enam siswa perlu disesuaikan untuk tiga puluh siswa. Pertanyaan awal, peran, dan rangkuman alasan dapat diuji sebagai unsur inti.","reference":null,"reference_note":null},"269":{"concept":"Penyesuaian dukungan dan tantangan","theory":"Tujuan dapat tetap sama sementara bantuan, cara menunjukkan pemahaman, dan kedalaman tantangan disesuaikan. Variasi dibuat berdasarkan bukti kebutuhan, bukan label kemampuan yang tetap.","why_correct":"Siswa cepat dapat memperdalam tujuan melalui cara alternatif dan perbandingan alasan sambil bekerja mandiri.","comparison":"Lebih banyak soal sama, mengajar teman terus, atau waktu bebas tidak otomatis memberi tantangan penalaran baru.","check_question":"Apa yang membuat pertanyaan cara alternatif lebih mendalam daripada tambahan soal sejenis?","check_answer":"Meminta cara alternatif dengan alasan dan perbandingan strategi agar siswa memperdalam tujuan sambil bekerja lebih mandiri. Alasannya: Siswa cepat dapat memperdalam tujuan melalui cara alternatif dan perbandingan alasan sambil bekerja mandiri.","reference":null,"reference_note":null},"270":{"concept":"Penalaran berbasis bukti","theory":"Petunjuk, persepsi, dan hasil akhir mempunyai kekuatan serta batas berbeda. Kesimpulan perlu mengikuti bukti yang relevan dan diperiksa silang, bukan memilih data yang mendukung dugaan awal.","why_correct":"Perubahan guru dan komposisi siswa membuat rata-rata sekolah sulit ditafsirkan sebagai dampak pendampingan. Analisis per kelas serta kondisi awal membantu keputusan.","comparison":"Rata-rata tunggal, penyalinan strategi langsung, atau kepuasan dokumen tidak memisahkan perubahan kondisi dan manfaat pendampingan.","check_question":"Mengapa rata-rata sekolah yang tetap belum membuktikan pendampingan tidak bermanfaat?","check_answer":"Menganalisis perubahan per kelas serta kondisi awal dan pelaksanaan sebelum menyimpulkan manfaat atau menentukan perbaikan pendampingan. Alasannya: Perubahan guru dan komposisi siswa membuat rata-rata sekolah sulit ditafsirkan sebagai dampak pendampingan. Analisis per kelas serta kondisi awal membantu keputusan.","reference":null,"reference_note":null},"1":{"concept":"Keadilan prosedural","theory":"Keputusan adil memakai kriteria relevan secara konsisten, memeriksa bukti, dan memberi ruang klarifikasi. Hasil yang sama tidak selalu tepat ketika kondisi yang relevan berbeda.","why_correct":"Data jam mengajar belum mencakup dua tugas tambahan sehingga pemerataan tidak boleh dinilai dari sebagian beban saja. Tenggat dua hari memungkinkan verifikasi terbuka sebelum finalisasi.","comparison":"Menerapkan lebih dahulu memperbesar dampak data tidak lengkap; kesepakatan spontan atau rancangan satu guru belum memastikan perbandingan beban utuh.","check_question":"Mengapa dua tugas tambahan perlu dihitung sebelum menilai pembagian tidak adil?","check_answer":"Menahan finalisasi bagian yang dipersoalkan dan memverifikasi seluruh beban dalam dua hari dengan kriteria yang terbuka. Alasannya: Data jam mengajar belum mencakup dua tugas tambahan sehingga pemerataan tidak boleh dinilai dari sebagian beban saja. Tenggat dua hari memungkinkan verifikasi terbuka sebelum finalisasi.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"2":{"concept":"Keadilan prosedural","theory":"Keputusan adil memakai kriteria relevan secara konsisten, memeriksa bukti, dan memberi ruang klarifikasi. Hasil yang sama tidak selalu tepat ketika kondisi yang relevan berbeda.","why_correct":"Persahabatan tidak menjadi dasar pengecualian. Situasi merawat orang tua perlu diklarifikasi agar dukungan dapat diberikan dengan standar disiplin, batas, dan pemantauan yang jelas.","comparison":"Toleransi tanpa evaluasi melemahkan konsistensi; penyerahan seluruh urusan atau teguran dahulu tidak memadukan tanggung jawab dan kebutuhan dukungan.","check_question":"Apa yang membedakan dukungan yang adil dari kelonggaran karena persahabatan?","check_answer":"Mengklarifikasi kebutuhan keluarga, menerapkan standar yang sama, dan menyepakati dukungan dengan batas serta pemantauan. Alasannya: Persahabatan tidak menjadi dasar pengecualian. Situasi merawat orang tua perlu diklarifikasi agar dukungan dapat diberikan dengan standar disiplin, batas, dan pemantauan yang jelas.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"3":{"concept":"Evaluasi proses dan hasil","theory":"Keterlaksanaan, jumlah peserta, dan kelengkapan laporan menunjukkan proses. Manfaat program perlu diperiksa pada perubahan yang menjadi tujuan, dengan pembanding kondisi awal yang sesuai.","why_correct":"Publikasi dan kesukaan guru belum menunjukkan kebiasaan membaca berubah. Bukti asesmen dan observasi perlu digunakan untuk memeriksa rancangan serta memperbaiki bagian yang tidak berdampak.","comparison":"Melanjutkan karena populer atau menghentikan tanpa telaah tidak menghubungkan mekanisme kegiatan dengan hasil membaca siswa.","check_question":"Bukti mana yang seharusnya lebih menentukan evaluasi program daripada publikasi positif?","check_answer":"Menelaah hasil dan pelaksanaan bersama tim, lalu menentukan komponen yang perlu diuji ulang dengan ukuran perubahan membaca. Alasannya: Publikasi dan kesukaan guru belum menunjukkan kebiasaan membaca berubah. Bukti asesmen dan observasi perlu digunakan untuk memeriksa rancangan serta memperbaiki bagian yang tidak berdampak.","reference":null,"reference_note":null},"4":{"concept":"Penalaran berbasis bukti","theory":"Petunjuk, persepsi, dan hasil akhir mempunyai kekuatan serta batas berbeda. Kesimpulan perlu mengikuti bukti yang relevan dan diperiksa silang, bukan memilih data yang mendukung dugaan awal.","why_correct":"Rubrik yang sama menjaga standar, tetapi komponen yang tidak terdokumentasi perlu diverifikasi sebelum nilai dianggap telah benar.","comparison":"Mempertahankan nilai melewatkan kelemahan bukti; mengulang seluruh penilaian atau menyerahkan sepenuhnya tidak menyasar komponen yang bermasalah.","check_question":"Mengapa penggunaan rubrik yang sama belum menutup kemungkinan perlunya koreksi nilai?","check_answer":"Memverifikasi komponen yang kurang terdokumentasi dengan rubrik yang sama dan menjelaskan hasil peninjauan kepada orang tua. Alasannya: Rubrik yang sama menjaga standar, tetapi komponen yang tidak terdokumentasi perlu diverifikasi sebelum nilai dianggap telah benar.","reference":null,"reference_note":null},"5":{"concept":"Praktik reflektif","theory":"Pemimpin menelaah keputusan serta dampaknya, mengakui bagian yang keliru, dan memperbaiki tindakan. Refleksi mengubah bukti pengalaman menjadi perbaikan yang spesifik.","why_correct":"Data rombel yang belum mutakhir memengaruhi sebagian keputusan, sehingga koreksi perlu menyasar bagian terdampak dan mengurangi gangguan agenda guru.","comparison":"Mempertahankan jadwal atau mengoreksi diam-diam tidak membangun pemahaman bersama; suara protes bukan pengganti pemeriksaan dampak data.","check_question":"Mengapa koreksi tidak cukup hanya dilakukan pada bagian yang paling banyak diprotes?","check_answer":"Mengakui kesalahan data, mengoreksi bagian jadwal yang terdampak, dan membahas penyesuaian untuk mengurangi gangguan agenda. Alasannya: Data rombel yang belum mutakhir memengaruhi sebagian keputusan, sehingga koreksi perlu menyasar bagian terdampak dan mengurangi gangguan agenda guru.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"6":{"concept":"Perlindungan dan kepentingan siswa","theory":"Tindak lanjut perlu mengurangi paparan risiko, menjaga martabat, dan membatasi penyebaran informasi sesuai kebutuhan penanganan. Mencari fakta berjalan bersama langkah perlindungan.","why_correct":"Tangkapan layar belum menggambarkan kejadian utuh. Pemeriksaan terbatas perlu berjalan bersama perlindungan siswa dan komunikasi yang menjaga informasi pribadi.","comparison":"Pernyataan sepihak, pembahasan luas, atau penundaan sampai isu reda belum memastikan kebenaran kejadian dan perlindungan.","check_question":"Mengapa sekolah perlu memverifikasi kejadian sekaligus melindungi siswa sebelum membuat pernyataan rinci?","check_answer":"Memverifikasi kejadian secara terbatas, memastikan kebutuhan perlindungan, dan menyampaikan pembaruan tanpa mengungkap rincian pribadi. Alasannya: Tangkapan layar belum menggambarkan kejadian utuh. Pemeriksaan terbatas perlu berjalan bersama perlindungan siswa dan komunikasi yang menjaga informasi pribadi.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"7":{"concept":"Diagnosis sebelum intervensi","theory":"Gejala yang sama dapat mempunyai penyebab berbeda. Menelusuri pola dan menguji beberapa dugaan membantu memilih bantuan yang benar-benar menangani hambatan.","why_correct":"Pola tiga kelas menjadi hipotesis tentang kehadiran, bukan kepastian penyebab numerasi. Kemampuan awal dan pembelajaran perlu dibandingkan agar prioritas tidak dibangun dari hubungan yang belum teruji.","comparison":"Mengganti prioritas langsung atau mempertahankan diagnosis lama sama-sama menutup pemeriksaan penjelasan alternatif.","check_question":"Variabel apa yang perlu dibandingkan sebelum kehadiran ditetapkan sebagai penyebab utama?","check_answer":"Menguji hubungan kehadiran, kemampuan awal, dan pembelajaran sebelum mengubah prioritas intervensi numerasi. Alasannya: Pola tiga kelas menjadi hipotesis tentang kehadiran, bukan kepastian penyebab numerasi. Kemampuan awal dan pembelajaran perlu dibandingkan agar prioritas tidak dibangun dari hubungan yang belum teruji.","reference":null,"reference_note":null},"8":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Keterbatasan sumber daya menuntut prioritas berdasarkan kebutuhan siswa, kewajiban, manfaat, dan kapasitas, bukan kuatnya tekanan pihak tertentu.","comparison":"Popularitas, kemudahan, atau kedudukan pihak pengusul saja tidak memastikan prioritas menghasilkan manfaat pendidikan.","check_question":"Mengapa tuntutan yang paling cepat dipenuhi belum tentu layak menjadi prioritas pertama?","check_answer":"Menimbang kebutuhan siswa, kewajiban sekolah, bukti manfaat, dan kapasitas pelaksanaan untuk menentukan urutan prioritas. Alasannya: Keterbatasan sumber daya menuntut prioritas berdasarkan kebutuhan siswa, kewajiban, manfaat, dan kapasitas, bukan kuatnya tekanan pihak tertentu.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"9":{"concept":"Keputusan proporsional terhadap risiko","theory":"Manfaat perlu ditimbang bersama bahaya, kemungkinan, dan dampaknya. Pengendalian disiapkan sebelum tindakan; skala kecil atau harga gratis tidak otomatis berarti tanpa risiko.","why_correct":"Walau belum ada kerugian, risiko keselamatan tetap perlu dikendalikan. Pengakuan pertama kali menjadi dasar pembinaan proporsional dan pemeriksaan usulan perbaikan.","comparison":"Menutup kasus karena tidak ada kerugian atau mempermalukan guru tidak menyelesaikan risiko prosedur; teguran saja belum menguji perbaikan.","check_question":"Mengapa tidak adanya kerugian belum cukup untuk menutup penanganan kesalahan ini?","check_answer":"Mengendalikan risiko, membina secara proporsional, dan menilai usulan perbaikan melalui tindak lanjut yang tercatat. Alasannya: Walau belum ada kerugian, risiko keselamatan tetap perlu dikendalikan. Pengakuan pertama kali menjadi dasar pembinaan proporsional dan pemeriksaan usulan perbaikan.","reference":null,"reference_note":null},"10":{"concept":"Penalaran berbasis bukti","theory":"Petunjuk, persepsi, dan hasil akhir mempunyai kekuatan serta batas berbeda. Kesimpulan perlu mengikuti bukti yang relevan dan diperiksa silang, bukan memilih data yang mendukung dugaan awal.","why_correct":"Instrumen eksternal dan internal mengukur aspek berbeda. Perbandingan perlu memeriksa sasaran ukur, kelompok, dan cara pengukuran sebelum menyimpulkan penurunan atau kestabilan.","comparison":"Memilih sumber karena dianggap lebih objektif atau lebih dekat dengan kelas belum menyelesaikan perbedaan konstruk yang diukur.","check_question":"Mengapa hasil dua instrumen tidak boleh langsung dianggap saling membantah?","check_answer":"Membandingkan aspek yang diukur dan mutu kedua sumber untuk merumuskan diagnosis yang dapat digunakan bulan ini. Alasannya: Instrumen eksternal dan internal mengukur aspek berbeda. Perbandingan perlu memeriksa sasaran ukur, kelompok, dan cara pengukuran sebelum menyimpulkan penurunan atau kestabilan.","reference":null,"reference_note":null},"11":{"concept":"Integritas dan akuntabilitas","theory":"Laporan dan pengakuan kontribusi harus mengikuti kenyataan yang dapat diperiksa. Akuntabilitas berarti keputusan dapat dijelaskan dengan bukti, bukan sekadar selesai secara administratif.","why_correct":"Laporan perlu menggambarkan kegiatan yang benar-benar terlaksana. Batas waktu tidak membenarkan pengesahan capaian yang belum terjadi.","comparison":"Janji koreksi kemudian atau kekhawatiran pencairan tidak mengubah kenyataan pelaksanaan yang harus dilaporkan.","check_question":"Apa yang harus dibedakan dalam laporan ketika kegiatan baru terlaksana sebagian?","check_answer":"Melaporkan kemajuan yang sebenarnya dan mengklarifikasi cara pelaporan atau penyesuaian tenggat tanpa menyatakan kegiatan selesai. Alasannya: Laporan perlu menggambarkan kegiatan yang benar-benar terlaksana. Batas waktu tidak membenarkan pengesahan capaian yang belum terjadi.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"12":{"concept":"Integritas dan akuntabilitas","theory":"Laporan dan pengakuan kontribusi harus mengikuti kenyataan yang dapat diperiksa. Akuntabilitas berarti keputusan dapat dijelaskan dengan bukti, bukan sekadar selesai secara administratif.","why_correct":"Keberhasilan melibatkan gagasan guru, kerja tim, dan dukungan komite. Pengakuan perlu mencerminkan kontribusi tersebut, bukan seluruhnya diarahkan pada pimpinan.","comparison":"Menerima atribusi tunggal atau memberi apresiasi tanpa meluruskan cerita publik mempertahankan gambaran kontribusi yang tidak tepat.","check_question":"Bagaimana kepala sekolah dapat menerima penghargaan sambil menjaga pengakuan kontribusi tim?","check_answer":"Mengoreksi pemberitaan mengenai penggagas dan mengakui kontribusi guru, tim, serta komite saat menerima penghargaan. Alasannya: Keberhasilan melibatkan gagasan guru, kerja tim, dan dukungan komite. Pengakuan perlu mencerminkan kontribusi tersebut, bukan seluruhnya diarahkan pada pimpinan.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"13":{"concept":"Keadilan prosedural","theory":"Keputusan adil memakai kriteria relevan secara konsisten, memeriksa bukti, dan memberi ruang klarifikasi. Hasil yang sama tidak selalu tepat ketika kondisi yang relevan berbeda.","why_correct":"Sebagian keberatan didukung data, sebagian berupa kehilangan kenyamanan. Kriteria dan bukti perlu ditelaah agar perubahan adil tanpa menganggap semua penolakan sama.","comparison":"Mengikuti mayoritas atau mengabaikan semua penolakan tidak memisahkan keberatan berbasis bukti dari preferensi pribadi.","check_question":"Mengapa keberatan guru harus dibandingkan menurut dasarnya, bukan jumlah penolaknya saja?","check_answer":"Mengoreksi kriteria yang terbukti tidak adil dan menjelaskan penerapannya sambil menjaga pemerataan layanan serta tenggat. Alasannya: Sebagian keberatan didukung data, sebagian berupa kehilangan kenyamanan. Kriteria dan bukti perlu ditelaah agar perubahan adil tanpa menganggap semua penolakan sama.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"14":{"concept":"Praktik reflektif","theory":"Pemimpin menelaah keputusan serta dampaknya, mengakui bagian yang keliru, dan memperbaiki tindakan. Refleksi mengubah bukti pengalaman menjadi perbaikan yang spesifik.","why_correct":"Umpan balik komunikasi, konsistensi aturan, dan kecepatan layanan menggambarkan dimensi berbeda. Refleksi perlu mempertahankan kekuatan sambil memperbaiki bagian yang lemah.","comparison":"Memilih hanya penilaian positif atau negatif menyederhanakan gambaran kinerja dan menghilangkan peluang perbaikan spesifik.","check_question":"Apa yang dapat diperbaiki tanpa menghapus kemajuan pada konsistensi aturan dan kecepatan layanan?","check_answer":"Menguji perbaikan komunikasi sambil memantau konsistensi aturan dan waktu layanan agar manfaat kepemimpinan tetap terjaga. Alasannya: Umpan balik komunikasi, konsistensi aturan, dan kecepatan layanan menggambarkan dimensi berbeda. Refleksi perlu mempertahankan kekuatan sambil memperbaiki bagian yang lemah.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"15":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Beban tugas berbeda antar kelas sehingga peninjauan perlu menghubungkan tujuan, jumlah, dan waktu siswa bersama guru serta keluarga.","comparison":"Pengurangan sama rata atau batas dari komite saja dapat tidak cocok dengan tujuan dan beban setiap kelas.","check_question":"Mengapa penurunan tugas dengan persentase sama belum tentu menghasilkan penugasan yang proporsional?","check_answer":"Meninjau tujuan dan beban tugas antar kelas bersama guru serta keluarga untuk menyepakati penugasan yang proporsional. Alasannya: Beban tugas berbeda antar kelas sehingga peninjauan perlu menghubungkan tujuan, jumlah, dan waktu siswa bersama guru serta keluarga.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"16":{"concept":"Konflik kepentingan","theory":"Kepentingan pribadi dapat mengganggu independensi keputusan, termasuk ketika belum terbukti ada keberpihakan. Pengungkapan dan pemisahan peran melindungi proses dari pengaruh tersebut.","why_correct":"Hubungan kerabat perlu diungkap dan dikelola melalui penilaian transparan yang independen, meskipun harga dan portofolio tampak baik.","comparison":"Manfaat renovasi tidak menghapus konflik; kedekatan atau penolakan otomatis tidak menggantikan pemeriksaan penawaran yang terbuka.","check_question":"Mengapa harga kompetitif belum cukup untuk menutup persoalan konflik kepentingan penyedia?","check_answer":"Memisahkan bantuan dari pemilihan penyedia, mengungkap hubungan keluarga, dan menggunakan proses penilaian yang dapat diperiksa. Alasannya: Hubungan kerabat perlu diungkap dan dikelola melalui penilaian transparan yang independen, meskipun harga dan portofolio tampak baik.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"17":{"concept":"Uji perbaikan secara bertahap","theory":"Inovasi diperlakukan sebagai gagasan yang perlu diuji terhadap masalah tertentu. Tujuan, indikator, hasil uji, dan penyesuaian menghubungkan percobaan dengan keputusan perluasan.","why_correct":"Manfaat platform belum terbukti dan perangkat terbatas. Uji bersama kedua kelompok guru dengan indikator memberi bukti untuk keputusan perluasan.","comparison":"Pilihan bebas tanpa indikator menyulitkan perbandingan; penerapan penuh atau menunggu semua perangkat tersedia melewatkan uji terukur.","check_question":"Apa yang harus ditetapkan sebelum uji platform agar hasilnya dapat menjadi dasar perluasan?","check_answer":"Menguji platform secara terbatas bersama kedua kelompok guru dengan indikator manfaat dan evaluasi sebelum perluasan. Alasannya: Manfaat platform belum terbukti dan perangkat terbatas. Uji bersama kedua kelompok guru dengan indikator memberi bukti untuk keputusan perluasan.","reference":null,"reference_note":null},"18":{"concept":"Kemitraan berorientasi kebutuhan","theory":"Sekolah dan mitra menyatukan tujuan serta peran untuk menjawab kebutuhan siswa. Banyaknya dukungan atau kegiatan tidak otomatis menunjukkan kualitas kerja sama.","why_correct":"Hambatan ekonomi dan kebutuhan bekerja memengaruhi kehadiran serta belajar. Dukungan perlu menghubungkan keluarga, sekolah, dan mitra, bukan kelonggaran tunggal.","comparison":"Kelonggaran saja belum menghentikan penurunan prestasi; tuntutan kehadiran atau perpindahan langsung melewatkan peluang dukungan terpadu.","check_question":"Mengapa dukungan ekonomi perlu disertai rencana belajar dan pemantauan ketiga siswa?","check_answer":"Menyusun dukungan ekonomi dan rencana belajar bersama keluarga serta mitra, lalu memantau keberlanjutan pendidikan ketiga siswa. Alasannya: Hambatan ekonomi dan kebutuhan bekerja memengaruhi kehadiran serta belajar. Dukungan perlu menghubungkan keluarga, sekolah, dan mitra, bukan kelonggaran tunggal.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"19":{"concept":"Komunikasi dua arah","theory":"Komunikasi efektif dinilai dari pemahaman penerima. Mendengar hambatan dan meminta klarifikasi membantu memperbaiki pesan serta respons, bukan hanya memperbanyak informasi.","why_correct":"Video tidak utuh perlu dilengkapi penjelasan fakta, tetapi sekolah juga perlu memeriksa kemungkinan kelemahan kebijakan.","comparison":"Unggahan video saja atau pembelaan sebelum telaah dapat mengabaikan dampak aturan; menunggu pengaduan membiarkan kebingungan berlanjut.","check_question":"Mengapa klarifikasi perlu sekaligus membuka kemungkinan memperbaiki aturan sekolah?","check_answer":"Menjelaskan fakta dan dasar kebijakan, membuka dialog, serta memeriksa bagian aturan yang mungkin perlu diperbaiki. Alasannya: Video tidak utuh perlu dilengkapi penjelasan fakta, tetapi sekolah juga perlu memeriksa kemungkinan kelemahan kebijakan.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"20":{"concept":"Pembatasan tujuan dan akses informasi","theory":"Data pribadi digunakan untuk tujuan yang jelas dengan penerima dan akses yang sesuai kebutuhan. Kemudahan teknologi atau hubungan keluarga tidak otomatis memberi hak atas semua informasi.","why_correct":"Retensi dan pemrosesan lanjutan belum jelas sehingga klaim anonim belum cukup untuk menilai perlindungan data siswa.","comparison":"Manfaat pedagogis, gratisnya perangkat, atau janji vendor tidak menggantikan pemeriksaan pengelolaan data dan syarat penggunaan.","check_question":"Informasi apa yang masih perlu diminta meskipun vendor menyatakan data dianonimkan?","check_answer":"Meminta rincian pemrosesan dan perlindungan data, lalu menilai kelayakan pilot bersama manfaat pedagogisnya. Alasannya: Retensi dan pemrosesan lanjutan belum jelas sehingga klaim anonim belum cukup untuk menilai perlindungan data siswa.","reference":null,"reference_note":null},"21":{"concept":"Partisipasi bermakna","theory":"Pihak terkait mempunyai kesempatan menyampaikan kebutuhan dan memeriksa dasar keputusan. Partisipasi bukan hanya hadir atau mendapat giliran, tetapi gagasannya dapat memengaruhi pembahasan.","why_correct":"Kedua kelompok memiliki kebutuhan yang masuk akal dan belum mempunyai kriteria bersama. Kesepakatan kriteria serta uji pengaturan membantu memulihkan kerja sama.","comparison":"Keputusan sepihak, rotasi sama, atau perundingan tanpa fasilitasi belum tentu menghasilkan dasar pembagian yang diterima dan sesuai kebutuhan.","check_question":"Mengapa kriteria bersama perlu disepakati sebelum memilih pengaturan ruang dan jadwal?","check_answer":"Menyepakati kriteria bersama, membandingkan kebutuhan kedua tim, dan menguji pengaturan ruang serta jadwal dengan evaluasi. Alasannya: Kedua kelompok memiliki kebutuhan yang masuk akal dan belum mempunyai kriteria bersama. Kesepakatan kriteria serta uji pengaturan membantu memulihkan kerja sama.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"22":{"concept":"Partisipasi bermakna","theory":"Pihak terkait mempunyai kesempatan menyampaikan kebutuhan dan memeriksa dasar keputusan. Partisipasi bukan hanya hadir atau mendapat giliran, tetapi gagasannya dapat memengaruhi pembahasan.","why_correct":"Pengalaman kritik tajam menjadi hambatan berbagi. Norma forum aman dan pilihan kontribusi membantu guru kembali berpartisipasi tanpa paksaan.","comparison":"Penghargaan atau jadwal presentasi belum memperbaiki keamanan forum; menunggu saja tidak mengatasi hambatan pengalaman sebelumnya.","check_question":"Apa yang harus berubah pada forum agar guru memiliki alasan untuk percaya dan berbagi lagi?","check_answer":"Menyepakati norma forum yang aman dan memberi pilihan kontribusi sebelum mengajak guru berbagi praktiknya. Alasannya: Pengalaman kritik tajam menjadi hambatan berbagi. Norma forum aman dan pilihan kontribusi membantu guru kembali berpartisipasi tanpa paksaan.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"23":{"concept":"Diagnosis sebelum intervensi","theory":"Gejala yang sama dapat mempunyai penyebab berbeda. Menelusuri pola dan menguji beberapa dugaan membantu memilih bantuan yang benar-benar menangani hambatan.","why_correct":"Fasilitas dan aturan sudah tersedia, sedangkan hukuman hanya berdampak sementara. Sekolah perlu menelaah kebiasaan serta kondisi penggunaan fasilitas.","comparison":"Menambah hukuman atau aturan tanpa memahami perilaku pada jam istirahat dapat mengulang intervensi yang efeknya singkat.","check_question":"Fakta apa yang menunjukkan bahwa penambahan hukuman bukan satu-satunya jawaban masalah sampah?","check_answer":"Memetakan perilaku saat istirahat bersama siswa dan menguji perbaikan sistem dengan tanggung jawab serta indikator yang jelas. Alasannya: Fasilitas dan aturan sudah tersedia, sedangkan hukuman hanya berdampak sementara. Sekolah perlu menelaah kebiasaan serta kondisi penggunaan fasilitas.","reference":null,"reference_note":null},"24":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Tiga fungsi ruang membawa kebutuhan berbeda. Keputusan memerlukan perbandingan urgensi, dampak siswa, kapasitas, dan alternatif penggunaan.","comparison":"Dukungan terbanyak, satu indikator, atau pembagian tanpa mempertimbangkan fungsi dapat menutup kebutuhan yang lebih mendesak.","check_question":"Mengapa data rendahnya literasi saja belum otomatis meniadakan kebutuhan privasi konseling?","check_answer":"Membandingkan ketiga kebutuhan dengan kriteria urgensi, dampak, alternatif ruang, dan jangkauan manfaat sebelum memutuskan hari itu. Alasannya: Tiga fungsi ruang membawa kebutuhan berbeda. Keputusan memerlukan perbandingan urgensi, dampak siswa, kapasitas, dan alternatif penggunaan.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"25":{"concept":"Kemitraan berorientasi kebutuhan","theory":"Sekolah dan mitra menyatukan tujuan serta peran untuk menjawab kebutuhan siswa. Banyaknya dukungan atau kegiatan tidak otomatis menunjukkan kualitas kerja sama.","why_correct":"Keahlian pemrograman perlu diterjemahkan menjadi materi sesuai usia dan pendampingan anak. Minat siswa belum membuktikan kesiapan rancangan.","comparison":"Gratisnya kelas dan kompetensi teknis tidak otomatis memenuhi kebutuhan pedagogis; kebebasan materi tanpa koordinasi melemahkan tanggung jawab sekolah.","check_question":"Apa yang perlu disepakati sebelum orang tua ahli pemrograman mulai mengajar siswa?","check_answer":"Menyepakati tujuan dan materi, memastikan pendampingan guru serta perlindungan siswa, lalu mengevaluasi kegiatan percobaan. Alasannya: Keahlian pemrograman perlu diterjemahkan menjadi materi sesuai usia dan pendampingan anak. Minat siswa belum membuktikan kesiapan rancangan.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"26":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Program gratis tetap memakai waktu guru dan dapat menggeser prioritas utama. Keselarasan kebutuhan serta biaya peluang perlu diperiksa dalam tenggat tiga hari.","comparison":"Popularitas dan gratisnya pelatihan tidak menjamin kecocokan; menerima semua dukungan dapat membebani program utama.","check_question":"Biaya apa yang tetap timbul walaupun program mitra tidak memungut uang?","check_answer":"Mengklarifikasi beban, menegosiasikan penyesuaian prioritas, dan memutuskan dalam tiga hari berdasarkan manfaat serta waktu guru. Alasannya: Program gratis tetap memakai waktu guru dan dapat menggeser prioritas utama. Keselarasan kebutuhan serta biaya peluang perlu diperiksa dalam tenggat tiga hari.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"27":{"concept":"Evaluasi proses dan hasil","theory":"Keterlaksanaan, jumlah peserta, dan kelengkapan laporan menunjukkan proses. Manfaat program perlu diperiksa pada perubahan yang menjadi tujuan, dengan pembanding kondisi awal yang sesuai.","why_correct":"Mutu kemitraan dinilai dari manfaat pembelajaran yang dihasilkan, bukan jumlah dokumen kerja sama atau seremoni.","comparison":"Banyak MoU menunjukkan aktivitas jejaring, tetapi tidak membuktikan siswa memperoleh manfaat yang lebih besar.","check_question":"Bukti apa yang membedakan kemitraan kecil yang bermutu dari MoU yang hanya seremonial?","check_answer":"Menilai perubahan mutu layanan dan kapasitas sekolah serta manfaat yang bertahan setelah kegiatan bersama berakhir. Alasannya: Mutu kemitraan dinilai dari manfaat pembelajaran yang dihasilkan, bukan jumlah dokumen kerja sama atau seremoni.","reference":null,"reference_note":null},"28":{"concept":"Kemitraan berorientasi kebutuhan","theory":"Sekolah dan mitra menyatukan tujuan serta peran untuk menjawab kebutuhan siswa. Banyaknya dukungan atau kegiatan tidak otomatis menunjukkan kualitas kerja sama.","why_correct":"Jejaring profesional bernilai ketika informasi dan dukungannya diterjemahkan menjadi perbaikan praktik serta layanan sekolah.","comparison":"Keaktifan pimpinan dan banyaknya kontak belum otomatis menghasilkan manfaat yang dirasakan guru.","check_question":"Apa yang harus terjadi setelah kepala sekolah memperoleh informasi program dari jejaring?","check_answer":"Menghubungkan hasil jejaring dengan kebutuhan sekolah dan memastikan pengetahuan atau sumber daya dapat digunakan guru. Alasannya: Jejaring profesional bernilai ketika informasi dan dukungannya diterjemahkan menjadi perbaikan praktik serta layanan sekolah.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"29":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Kewajiban regulatif, manfaat berbasis data, dan kapasitas pelaksanaan perlu dibandingkan. Mendanai semua program dapat menurunkan mutu sehingga prioritas harus eksplisit.","comparison":"Popularitas atau pembagian dana tipis tidak menggantikan pemenuhan kewajiban dan penilaian dampak prioritas.","check_question":"Mengapa membiayai semua program belum tentu merupakan keputusan paling adil bagi siswa?","check_answer":"Memenuhi kewajiban secara memadai lalu membandingkan manfaat, biaya, kelayakan, dan risiko program lain untuk menentukan alokasi. Alasannya: Kewajiban regulatif, manfaat berbasis data, dan kapasitas pelaksanaan perlu dibandingkan. Mendanai semua program dapat menurunkan mutu sehingga prioritas harus eksplisit.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"30":{"concept":"Diagnosis sebelum intervensi","theory":"Gejala yang sama dapat mempunyai penyebab berbeda. Menelusuri pola dan menguji beberapa dugaan membantu memilih bantuan yang benar-benar menangani hambatan.","why_correct":"Numerasi rendah dapat berkaitan dengan prasyarat, kehadiran, pembelajaran, dan asesmen. Diagnosis perlu menguji dugaan sebelum memilih jam tambahan atau aplikasi.","comparison":"Memilih solusi yang tersedia lebih dahulu dapat menangani gejala sambil melewatkan penyebab dominan.","check_question":"Bukti apa yang perlu diperiksa sebelum sekolah memilih aplikasi atau tambahan jam numerasi?","check_answer":"Melakukan diagnosis terfokus dalam dua minggu dengan pekerjaan siswa, kehadiran, observasi, dan asesmen prasyarat. Alasannya: Numerasi rendah dapat berkaitan dengan prasyarat, kehadiran, pembelajaran, dan asesmen. Diagnosis perlu menguji dugaan sebelum memilih jam tambahan atau aplikasi.","reference":null,"reference_note":null},"31":{"concept":"Evaluasi proses dan hasil","theory":"Keterlaksanaan, jumlah peserta, dan kelengkapan laporan menunjukkan proses. Manfaat program perlu diperiksa pada perubahan yang menjadi tujuan, dengan pembanding kondisi awal yang sesuai.","why_correct":"Pelaksanaan 18 program belum menghasilkan perubahan yang diharapkan. Evaluasi dampak dan sumber daya memberi dasar menggabungkan atau menghentikan program lemah.","comparison":"Monitoring jadwal atau mengurangi program termahal saja tidak menjawab program mana yang paling bermanfaat.","check_question":"Mengapa terlaksananya semua program belum membuktikan portofolio program sekolah efektif?","check_answer":"Menilai dampak serta kebutuhan sumber daya tiap program, lalu menggabungkan atau menghentikan yang lemah untuk memperkuat prioritas. Alasannya: Pelaksanaan 18 program belum menghasilkan perubahan yang diharapkan. Evaluasi dampak dan sumber daya memberi dasar menggabungkan atau menghentikan program lemah.","reference":null,"reference_note":null},"32":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Dokumen perlu dipetakan menurut kewajiban, fungsi, dan duplikasi sebelum disederhanakan. Tujuannya mengurangi beban tanpa kehilangan pertanggungjawaban.","comparison":"Digitalisasi atau pembagian tugas mempertahankan duplikasi; menghapus yang paling dikeluhkan dapat menghilangkan dokumen yang wajib.","check_question":"Mengapa mendigitalkan semua format belum tentu mengurangi administrasi yang tidak diperlukan?","check_answer":"Memetakan kewajiban, fungsi, dan duplikasi dokumen untuk menyederhanakan administrasi sambil menjaga kebutuhan pertanggungjawaban. Alasannya: Dokumen perlu dipetakan menurut kewajiban, fungsi, dan duplikasi sebelum disederhanakan. Tujuannya mengurangi beban tanpa kehilangan pertanggungjawaban.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"33":{"concept":"Evaluasi proses dan hasil","theory":"Keterlaksanaan, jumlah peserta, dan kelengkapan laporan menunjukkan proses. Manfaat program perlu diperiksa pada perubahan yang menjadi tujuan, dengan pembanding kondisi awal yang sesuai.","why_correct":"Data kebutuhan siswa dan evaluasi program menjadi dasar mempertahankan, mengubah, atau mengganti kegiatan sesuai tujuan serta kapasitas.","comparison":"Tradisi, kesepakatan, dan contoh sekolah lain dapat membantu, tetapi tidak menggantikan bukti kebutuhan sekolah sendiri.","check_question":"Kapan kegiatan tradisi layak dipertahankan dalam program tahun berikutnya?","check_answer":"Menggunakan data siswa dan evaluasi terdahulu untuk memilih program yang selaras dengan tujuan serta kapasitas sekolah. Alasannya: Data kebutuhan siswa dan evaluasi program menjadi dasar mempertahankan, mengubah, atau mengganti kegiatan sesuai tujuan serta kapasitas.","reference":null,"reference_note":null},"34":{"concept":"Diagnosis sebelum intervensi","theory":"Gejala yang sama dapat mempunyai penyebab berbeda. Menelusuri pola dan menguji beberapa dugaan membantu memilih bantuan yang benar-benar menangani hambatan.","why_correct":"Kunjungan rendah berkaitan dengan kemungkinan hambatan jadwal, minat koleksi, dan dukungan layanan. Pemeriksaan bersama menghindari solusi satu sebab.","comparison":"Menambah buku, mewajibkan kunjungan, atau mengubah ruang dahulu belum memastikan penyebab rendahnya penggunaan.","check_question":"Mengapa koleksi yang cukup baik tidak otomatis menjamin perpustakaan digunakan siswa?","check_answer":"Memeriksa pola penggunaan dan kebutuhan siswa bersama guru serta pustakawan untuk menentukan perbaikan koleksi, jadwal, dan layanan. Alasannya: Kunjungan rendah berkaitan dengan kemungkinan hambatan jadwal, minat koleksi, dan dukungan layanan. Pemeriksaan bersama menghindari solusi satu sebab.","reference":null,"reference_note":null},"35":{"concept":"Diagnosis sebelum intervensi","theory":"Gejala yang sama dapat mempunyai penyebab berbeda. Menelusuri pola dan menguji beberapa dugaan membantu memilih bantuan yang benar-benar menangani hambatan.","why_correct":"Pola hari dan tingkat kelas mempersempit penelusuran, tetapi dugaan keluarga dan pembelajaran masih perlu diklarifikasi.","comparison":"Perubahan jadwal, tuntutan orang tua, atau penghargaan kehadiran sebelum diagnosis belum menyasar penyebab yang terverifikasi.","check_question":"Apa manfaat memetakan absensi menurut siswa dan hari sebelum memilih dukungan?","check_answer":"Memetakan absensi menurut siswa dan hari, lalu mengklarifikasi dugaan keluarga serta pembelajaran sebelum memilih dukungan. Alasannya: Pola hari dan tingkat kelas mempersempit penelusuran, tetapi dugaan keluarga dan pembelajaran masih perlu diklarifikasi.","reference":null,"reference_note":null},"36":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Keputusan perpanjangan menimbang manfaat ke depan, kebutuhan, dan biaya tambahan. Dana yang sudah dikeluarkan tidak dapat dipulihkan hanya dengan memperpanjang kontrak.","comparison":"Diskon dan keinginan menyelamatkan investasi lama tidak membuktikan aplikasi akan memberi manfaat berikutnya.","check_question":"Mengapa investasi tahun lalu tidak cukup menjadi alasan memperpanjang aplikasi yang dampaknya belum terlihat?","check_answer":"Menilai manfaat dan biaya ke depan serta penyebab penggunaan rendah; keputusan perpanjangan tidak didasarkan pada biaya yang telah keluar. Alasannya: Keputusan perpanjangan menimbang manfaat ke depan, kebutuhan, dan biaya tambahan. Dana yang sudah dikeluarkan tidak dapat dipulihkan hanya dengan memperpanjang kontrak.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"37":{"concept":"Integritas dan akuntabilitas","theory":"Laporan dan pengakuan kontribusi harus mengikuti kenyataan yang dapat diperiksa. Akuntabilitas berarti keputusan dapat dijelaskan dengan bukti, bukan sekadar selesai secara administratif.","why_correct":"Selisih kecil tetap perlu ditelusuri melalui transaksi agar koreksi dan perbaikan kontrol mengikuti bukti, tanpa menyimpulkan penyalahgunaan lebih dahulu.","comparison":"Penjelasan bendahara atau surat tanggung jawab belum memverifikasi transaksi; hanya memeriksa nilai besar dapat melewatkan penyebab selisih.","check_question":"Mengapa selisih kecil perlu diperiksa tanpa langsung menganggap bendahara menyalahgunakan dana?","check_answer":"Memverifikasi transaksi, mengoreksi laporan berdasarkan bukti, dan memperbaiki kontrol sesuai penyebab ketidakcocokan yang ditemukan. Alasannya: Selisih kecil tetap perlu ditelusuri melalui transaksi agar koreksi dan perbaikan kontrol mengikuti bukti, tanpa menyimpulkan penyalahgunaan lebih dahulu.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"38":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Kompetensi khusus terkonsentrasi pada dua guru yang mulai kelelahan. Pembagian perlu disertai pengembangan kemampuan rekan agar kapasitas lebih merata.","comparison":"Memindahkan tugas tanpa dukungan atau mempertahankan beban guru andalan tidak mengelola keberlanjutan kerja.","check_question":"Mengapa pemerataan tugas perlu disertai pendampingan guru yang belum berpengalaman?","check_answer":"Memindahkan tugas yang sesuai kapasitas secara bertahap dengan pendampingan agar beban berkurang dan layanan tetap terjaga. Alasannya: Kompetensi khusus terkonsentrasi pada dua guru yang mulai kelelahan. Pembagian perlu disertai pengembangan kemampuan rekan agar kapasitas lebih merata.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"39":{"concept":"Evaluasi proses dan hasil","theory":"Keterlaksanaan, jumlah peserta, dan kelengkapan laporan menunjukkan proses. Manfaat program perlu diperiksa pada perubahan yang menjadi tujuan, dengan pembanding kondisi awal yang sesuai.","why_correct":"Baseline dan indikator sebelum peluncuran memberi pembanding serta arah pengumpulan bukti. Menentukannya setelah berjalan dapat mengubah ukuran mengikuti hasil.","comparison":"Kesepakatan pihak atau kesiapan kegiatan belum menggantikan kesiapan mengukur perubahan yang dituju.","check_question":"Apa yang menjadi sulit dinilai jika program dimulai tanpa kondisi awal dan indikator?","check_answer":"Menetapkan baseline, indikator, target, dan cara pengukuran sebelum peluncuran agar perubahan hasil dapat dinilai. Alasannya: Baseline dan indikator sebelum peluncuran memberi pembanding serta arah pengumpulan bukti. Menentukannya setelah berjalan dapat mengubah ukuran mengikuti hasil.","reference":null,"reference_note":null},"40":{"concept":"Evaluasi proses dan hasil","theory":"Keterlaksanaan, jumlah peserta, dan kelengkapan laporan menunjukkan proses. Manfaat program perlu diperiksa pada perubahan yang menjadi tujuan, dengan pembanding kondisi awal yang sesuai.","why_correct":"Manfaat akademik dan kebersamaan merupakan dimensi berbeda. Sekolah perlu memeriksa tujuan, bukti tiap manfaat, dan biaya peluang sebelum menentukan perubahan.","comparison":"Menghentikan karena satu indikator atau melanjutkan karena disukai sama-sama melewatkan penilaian manfaat dan penggunaan anggaran.","check_question":"Bagaimana kebersamaan dapat dipertimbangkan tanpa mengabaikan tujuan akademik yang belum tercapai?","check_answer":"Memeriksa manfaat sosial yang diklaim dan membandingkan biaya serta alternatif sebelum menetapkan kelanjutan atau perubahan kegiatan. Alasannya: Manfaat akademik dan kebersamaan merupakan dimensi berbeda. Sekolah perlu memeriksa tujuan, bukti tiap manfaat, dan biaya peluang sebelum menentukan perubahan.","reference":null,"reference_note":null},"41":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Pengelolaan sumber daya dinilai dari kesesuaiannya dengan prioritas dan hasil, sambil menjaga efisiensi serta pertanggungjawaban.","comparison":"Banyaknya aset, habisnya dana, atau banyaknya dukungan belum membuktikan sumber daya dipakai untuk manfaat pendidikan.","check_question":"Mengapa penyerapan dana penuh bukan satu-satunya ukuran pengelolaan sumber daya yang baik?","check_answer":"Menilai kesesuaian aturan, transparansi penggunaan, dan manfaat sumber daya terhadap prioritas layanan serta pembelajaran. Alasannya: Pengelolaan sumber daya dinilai dari kesesuaiannya dengan prioritas dan hasil, sambil menjaga efisiensi serta pertanggungjawaban.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"42":{"concept":"Keputusan proporsional terhadap risiko","theory":"Manfaat perlu ditimbang bersama bahaya, kemungkinan, dan dampaknya. Pengendalian disiapkan sebelum tindakan; skala kecil atau harga gratis tidak otomatis berarti tanpa risiko.","why_correct":"Kebutuhan perangkat nyata tetap perlu diuji kelayakan pelaksanaan dan pertanggungjawabannya dalam waktu tersisa.","comparison":"Kecepatan membeli, pembagian ke barang kecil, atau mengejar penyerapan tidak menjamin belanja layak dan berkelanjutan.","check_question":"Apa yang harus diperiksa sebelum menyetujui belanja perangkat pada akhir tahun?","check_answer":"Memeriksa kelayakan pelaksanaan dan pertanggungjawaban kebutuhan perangkat dalam waktu tersisa sebelum menyetujui belanja. Alasannya: Kebutuhan perangkat nyata tetap perlu diuji kelayakan pelaksanaan dan pertanggungjawabannya dalam waktu tersisa.","reference":null,"reference_note":null},"43":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Proyek produktif perlu capaian siswa, peran, biaya pemeliharaan, dan tata kelola agar manfaat pendidikan serta keberlanjutan dapat dinilai.","comparison":"Pendapatan atau kebun luas tanpa rancangan belajar belum memenuhi kedua tujuan; kebebasan tanpa pendampingan meningkatkan risiko.","check_question":"Apa yang membuat kegiatan produktif tetap menjadi pembelajaran, bukan hanya usaha menghasilkan uang?","check_answer":"Merancang proyek belajar produktif dengan capaian siswa, biaya pemeliharaan, tata kelola, dan ukuran keberlanjutan yang jelas. Alasannya: Proyek produktif perlu capaian siswa, peran, biaya pemeliharaan, dan tata kelola agar manfaat pendidikan serta keberlanjutan dapat dinilai.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"44":{"concept":"Uji perbaikan secara bertahap","theory":"Inovasi diperlakukan sebagai gagasan yang perlu diuji terhadap masalah tertentu. Tujuan, indikator, hasil uji, dan penyesuaian menghubungkan percobaan dengan keputusan perluasan.","why_correct":"Ketidakkonsistenan guru, koneksi, dan kerumitan fitur adalah hambatan berbeda yang dapat diperbaiki serta diuji ulang.","comparison":"Mewajibkan penggunaan, mengganti produk, atau menghentikan langsung dapat melewatkan hambatan implementasi yang masih dapat ditangani.","check_question":"Mengapa kegagalan target belum membuktikan konsep absensi digital harus ditinggalkan?","check_answer":"Memperbaiki kerumitan fitur, dukungan guru, dan kendala koneksi lalu menguji ulang dengan ukuran keberhasilan yang jelas. Alasannya: Ketidakkonsistenan guru, koneksi, dan kerumitan fitur adalah hambatan berbeda yang dapat diperbaiki serta diuji ulang.","reference":null,"reference_note":null},"45":{"concept":"Uji perbaikan secara bertahap","theory":"Inovasi diperlakukan sebagai gagasan yang perlu diuji terhadap masalah tertentu. Tujuan, indikator, hasil uji, dan penyesuaian menghubungkan percobaan dengan keputusan perluasan.","why_correct":"Kewirausahaan pendidikan menciptakan manfaat melalui peluang perbaikan, sumber daya, dan risiko yang dikelola.","comparison":"Laba, dukungan mitra, atau keunikan citra adalah sarana; tidak otomatis menunjukkan nilai pendidikan tercipta.","check_question":"Apa ukuran nilai yang membedakan kewirausahaan pendidikan dari sekadar penambahan pendapatan?","check_answer":"Menguji peluang perbaikan belajar, menggerakkan sumber daya, dan mengendalikan risiko untuk menciptakan nilai pendidikan. Alasannya: Kewirausahaan pendidikan menciptakan manfaat melalui peluang perbaikan, sumber daya, dan risiko yang dikelola.","reference":null,"reference_note":null},"46":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Siswa membaca karena kewajiban dan kurang mempunyai pilihan. Inovasi perlu mengubah pengalaman membaca lalu memeriksa keterlibatan yang nyata.","comparison":"Buku tambahan, hadiah jumlah, dan durasi lebih panjang tanpa perubahan pilihan dapat mempertahankan kepatuhan tanpa minat.","check_question":"Perubahan perilaku apa yang menunjukkan inovasi membaca meningkatkan keterlibatan, bukan sekadar kepatuhan?","check_answer":"Menguji rancangan yang memberi pilihan bacaan dan mengukur perubahan keterlibatan berdasarkan minat serta perilaku siswa. Alasannya: Siswa membaca karena kewajiban dan kurang mempunyai pilihan. Inovasi perlu mengubah pengalaman membaca lalu memeriksa keterlibatan yang nyata.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"47":{"concept":"Pengembangan profesional berbasis praktik","theory":"Belajar guru dihubungkan dengan kebutuhan kelas, uji perubahan yang terjangkau, dan refleksi atas bukti penerapan. Kehadiran pelatihan belum memastikan perubahan praktik.","why_correct":"Keahlian satu guru dapat menjadi kapasitas bersama melalui pendampingan, pemeriksaan mutu, batas penggunaan, dan evaluasi belajar.","comparison":"Memusatkan produksi atau bantuan teknis pada satu orang mempertahankan ketergantungan dan tidak memperluas kemampuan rekan.","check_question":"Bagaimana keahlian AI satu guru dapat dikembangkan menjadi kemampuan tim?","check_answer":"Mengajak guru tersebut mendampingi sejawat dengan pemeriksaan mutu bahan, batas penggunaan AI, dan evaluasi dampak belajar. Alasannya: Keahlian satu guru dapat menjadi kapasitas bersama melalui pendampingan, pemeriksaan mutu, batas penggunaan, dan evaluasi belajar.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"48":{"concept":"Transfer praktik dengan perhatian pada konteks","theory":"Praktik rujukan perlu dibedakan antara bentuk kegiatan dan mekanisme yang membuatnya bermanfaat. Penerapan pada konteks baru memerlukan penyesuaian dan bukti, bukan penyalinan bentuk saja.","why_correct":"Penyebab absensi di sekolah sendiri terkait transportasi dan keluarga, sedangkan praktik rujukan bergantung pada gawai. Mekanisme perlu disesuaikan dengan konteks.","comparison":"Menyalin aplikasi dan poin tidak otomatis menangani hambatan transportasi atau akses gawai yang tidak merata.","check_question":"Unsur apa yang harus diuji sebelum praktik pengingat digital dari sekolah lain diadopsi?","check_answer":"Menelaah mekanisme praktik rujukan dan menguji adaptasi yang menjawab hambatan transportasi serta tanggung jawab keluarga. Alasannya: Penyebab absensi di sekolah sendiri terkait transportasi dan keluarga, sedangkan praktik rujukan bergantung pada gawai. Mekanisme perlu disesuaikan dengan konteks.","reference":null,"reference_note":null},"49":{"concept":"Evaluasi proses dan hasil","theory":"Keterlaksanaan, jumlah peserta, dan kelengkapan laporan menunjukkan proses. Manfaat program perlu diperiksa pada perubahan yang menjadi tujuan, dengan pembanding kondisi awal yang sesuai.","why_correct":"Perhatian media dan kesukaan guru belum menunjukkan masalah belajar terselesaikan. Sasaran serta perubahan proses belajar perlu dirumuskan dan diukur.","comparison":"Popularitas, kecanggihan, dan keterlaksanaan mengukur sisi kegiatan yang berbeda dari dampak pendidikan.","check_question":"Mengapa program teknologi belum dapat dinyatakan berhasil hanya karena disukai dan diberitakan?","check_answer":"Menetapkan masalah sasaran dan menguji perubahan belajar untuk menilai nilai tambah program dibanding praktik sebelumnya. Alasannya: Perhatian media dan kesukaan guru belum menunjukkan masalah belajar terselesaikan. Sasaran serta perubahan proses belajar perlu dirumuskan dan diukur.","reference":null,"reference_note":null},"50":{"concept":"Pembatasan tujuan dan akses informasi","theory":"Data pribadi digunakan untuk tujuan yang jelas dengan penerima dan akses yang sesuai kebutuhan. Kemudahan teknologi atau hubungan keluarga tidak otomatis memberi hak atas semua informasi.","why_correct":"Kebutuhan belajar menjadi pintu penilaian teknologi, lalu data siswa, biaya berlangganan, dan batas penggunaan diperiksa bersama manfaatnya.","comparison":"Kecanggihan dan lisensi awal gratis tidak menjamin kebutuhan terjawab atau biaya serta data aman dikelola.","check_question":"Pertanyaan tentang kebutuhan belajar apa yang perlu dijawab sebelum fitur AI dibahas?","check_answer":"Masalah belajar mana yang perlu diatasi, bukti manfaat apa yang dicari, dan batas data serta risiko apa yang harus dipenuhi? Alasannya: Kebutuhan belajar menjadi pintu penilaian teknologi, lalu data siswa, biaya berlangganan, dan batas penggunaan diperiksa bersama manfaatnya.","reference":null,"reference_note":null},"51":{"concept":"Partisipasi bermakna","theory":"Pihak terkait mempunyai kesempatan menyampaikan kebutuhan dan memeriksa dasar keputusan. Partisipasi bukan hanya hadir atau mendapat giliran, tetapi gagasannya dapat memengaruhi pembahasan.","why_correct":"Inovasi memerlukan ruang menguji gagasan dan membicarakan kegagalan dengan aman, sambil menetapkan tujuan serta evaluasi yang jelas.","comparison":"Kritik keras menghambat keterbukaan; kebebasan tanpa pertanggungjawaban tidak menjamin sekolah belajar dari percobaan.","check_question":"Bagaimana sekolah memberi ruang gagal tanpa menghilangkan tanggung jawab atas uji inovasi?","check_answer":"Membuka eksperimen kecil dengan batas risiko dan refleksi berbasis bukti sambil membedakan kesalahan belajar dari kelalaian. Alasannya: Inovasi memerlukan ruang menguji gagasan dan membicarakan kegagalan dengan aman, sambil menetapkan tujuan serta evaluasi yang jelas.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"52":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Keterbatasan dana dapat diatasi dengan memetakan aset, kontribusi alumni, dan mitra terhadap kebutuhan laboratorium yang dirumuskan.","comparison":"Menunggu dana penuh atau menerima semua tawaran tanpa rancangan tidak mengoptimalkan sumber daya untuk tujuan yang sama.","check_question":"Apa yang perlu dipetakan sebelum meminta bantuan alumni dan industri untuk laboratorium STEM?","check_answer":"Memetakan aset dan kebutuhan minimum lalu menguji laboratorium bertahap dengan bantuan yang sudah dipastikan tersedia. Alasannya: Keterbatasan dana dapat diatasi dengan memetakan aset, kontribusi alumni, dan mitra terhadap kebutuhan laboratorium yang dirumuskan.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"53":{"concept":"Transfer praktik dengan perhatian pada konteks","theory":"Praktik rujukan perlu dibedakan antara bentuk kegiatan dan mekanisme yang membuatnya bermanfaat. Penerapan pada konteks baru memerlukan penyesuaian dan bukti, bukan penyalinan bentuk saja.","why_correct":"Hasil tiga kelas belum mengidentifikasi unsur keberhasilan yang dapat diulang. Uji kelas tambahan dan kapasitas mentor diperlukan sebelum perluasan.","comparison":"Perluasan langsung, replikasi tanpa perbandingan, atau penundaan tanpa pengujian tidak menjawab mekanisme keberhasilan.","check_question":"Apa yang harus dibuktikan agar keberhasilan mentoring tidak bergantung pada satu mentor tertentu?","check_answer":"Menguji elemen inti pada kelas tambahan, menyiapkan kapasitas mentor, dan memperluas berdasarkan hasil pemantauan. Alasannya: Hasil tiga kelas belum mengidentifikasi unsur keberhasilan yang dapat diulang. Uji kelas tambahan dan kapasitas mentor diperlukan sebelum perluasan.","reference":null,"reference_note":null},"54":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Adaptasi tiga bulan memerlukan pemetaan tuntutan baru, bagian lama yang masih berfungsi, prioritas, dan dukungan perubahan.","comparison":"Mengganti semua prosedur atau mempertahankan semuanya tidak membedakan kebutuhan perubahan dan praktik yang masih bermanfaat.","check_question":"Bagaimana menentukan prosedur yang harus berubah dan yang layak dipertahankan?","check_answer":"Memetakan proses yang harus berubah dan menyiapkan transisi dalam tiga bulan dengan dukungan peran serta pemantauan hambatan. Alasannya: Adaptasi tiga bulan memerlukan pemetaan tuntutan baru, bagian lama yang masih berfungsi, prioritas, dan dukungan perubahan.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"55":{"concept":"Keputusan proporsional terhadap risiko","theory":"Manfaat perlu ditimbang bersama bahaya, kemungkinan, dan dampaknya. Pengendalian disiapkan sebelum tindakan; skala kecil atau harga gratis tidak otomatis berarti tanpa risiko.","why_correct":"Bukti manfaat terbatas dan tiga risiko memerlukan uji terukur, batas biaya serta beban, dan pemantauan kepatuhan.","comparison":"Menolak semua risiko atau menerapkan penuh tanpa kendali tidak menghasilkan pembelajaran yang proporsional terhadap ketidakpastian.","check_question":"Batas apa yang perlu ditetapkan sebelum inovasi diuji agar risikonya dapat dikendalikan?","check_answer":"Menguji pada skala terbatas dengan mitigasi biaya dan beban, indikator kepatuhan, serta batas penghentian yang jelas. Alasannya: Bukti manfaat terbatas dan tiga risiko memerlukan uji terukur, batas biaya serta beban, dan pemantauan kepatuhan.","reference":null,"reference_note":null},"56":{"concept":"Evaluasi proses dan hasil","theory":"Keterlaksanaan, jumlah peserta, dan kelengkapan laporan menunjukkan proses. Manfaat program perlu diperiksa pada perubahan yang menjadi tujuan, dengan pembanding kondisi awal yang sesuai.","why_correct":"Lomba dan kunjungan menunjukkan pengakuan, tetapi manfaat akhir perlu diperiksa pada pengalaman serta hasil belajar siswa.","comparison":"Penghargaan dan publikasi tidak menggantikan bukti bahwa praktik atau pengalaman siswa berubah.","check_question":"Bukti apa yang harus dicari setelah inovasi memenangkan lomba?","check_answer":"Menilai perubahan pengalaman serta hasil belajar dan memeriksa apakah manfaatnya bertahan setelah program berjalan. Alasannya: Lomba dan kunjungan menunjukkan pengakuan, tetapi manfaat akhir perlu diperiksa pada pengalaman serta hasil belajar siswa.","reference":null,"reference_note":null},"57":{"concept":"Asesmen dan umpan balik formatif","theory":"Informasi tentang belajar digunakan untuk menentukan langkah perbaikan. Umpan balik bernilai ketika siswa atau guru memahami dan dapat memakai informasi itu dalam tindakan berikutnya.","why_correct":"Nilai tinggi dan penjelasan runtut belum menjamin siswa dapat bernalar. Pola interaksi serta penjelasan alasan perlu dibahas dengan guru.","comparison":"Menyetujui efisiensi atau mengganti metode tanpa telaah dapat melewatkan siswa yang hanya meniru prosedur.","check_question":"Apa bukti tambahan yang diperlukan untuk membedakan peniruan prosedur dan pemahaman siswa?","check_answer":"Membahas bukti interaksi dan penalaran bersama guru lalu menyepakati perubahan yang akan diuji pada observasi berikutnya. Alasannya: Nilai tinggi dan penjelasan runtut belum menjamin siswa dapat bernalar. Pola interaksi serta penjelasan alasan perlu dibahas dengan guru.","reference":{"title":"EEF (2021), Teacher Feedback to Improve Pupil Learning","url":"https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/feedback"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"58":{"concept":"Supervisi untuk perbaikan pembelajaran","theory":"Observasi menghasilkan bukti yang dibahas melalui refleksi dan tindak lanjut. Keberhasilan ditelusuri pada perubahan praktik serta pengalaman siswa, bukan jumlah observasi saja.","why_correct":"Siklus observasi, refleksi, dan tindak lanjut menghubungkan bukti kelas dengan perbaikan yang dapat diperiksa.","comparison":"Peringkat, keseragaman metode, atau kelengkapan perangkat sebagai tujuan utama tidak memastikan perbaikan pengalaman siswa.","check_question":"Bagian siklus apa yang memastikan hasil observasi tidak berhenti sebagai laporan?","check_answer":"Menyepakati siklus observasi, refleksi, dan tindak lanjut untuk memperbaiki praktik serta pengalaman belajar siswa. Alasannya: Siklus observasi, refleksi, dan tindak lanjut menghubungkan bukti kelas dengan perbaikan yang dapat diperiksa.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"59":{"concept":"Diagnosis sebelum intervensi","theory":"Gejala yang sama dapat mempunyai penyebab berbeda. Menelusuri pola dan menguji beberapa dugaan membantu memilih bantuan yang benar-benar menangani hambatan.","why_correct":"Prasyarat, absensi, komposisi, dan pembelajaran dapat saling memengaruhi nilai. Analisis bersama perlu membandingkan bukti tiap faktor.","comparison":"Menyalahkan guru atau komposisi siswa saja membuat diagnosis terlalu tunggal untuk data yang berlapis.","check_question":"Mengapa nilai kelas paralel perlu dibandingkan bersama kemampuan awal dan kehadiran?","check_answer":"Memetakan kemampuan awal, kehadiran, dan proses bersama guru untuk memilih hipotesis serta faktor yang dapat diintervensi. Alasannya: Prasyarat, absensi, komposisi, dan pembelajaran dapat saling memengaruhi nilai. Analisis bersama perlu membandingkan bukti tiap faktor.","reference":null,"reference_note":null},"60":{"concept":"Pengembangan profesional berbasis praktik","theory":"Belajar guru dihubungkan dengan kebutuhan kelas, uji perubahan yang terjangkau, dan refleksi atas bukti penerapan. Kehadiran pelatihan belum memastikan perubahan praktik.","why_correct":"Hambatan heterogenitas perlu diperinci lalu dihubungkan dengan penyesuaian strategi, dukungan, dan bukti penerapan.","comparison":"Tenggat baru, strategi seragam, atau pelatihan dahulu tidak otomatis menyelesaikan hambatan spesifik kelas.","check_question":"Dukungan apa yang perlu disepakati selain memperpanjang tenggat penerapan strategi?","check_answer":"Mengklarifikasi hambatan spesifik dan menyepakati penyesuaian strategi, dukungan, serta bukti penerapan yang akan diperiksa. Alasannya: Hambatan heterogenitas perlu diperinci lalu dihubungkan dengan penyesuaian strategi, dukungan, dan bukti penerapan.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"61":{"concept":"Asesmen dan umpan balik formatif","theory":"Informasi tentang belajar digunakan untuk menentukan langkah perbaikan. Umpan balik bernilai ketika siswa atau guru memahami dan dapat memakai informasi itu dalam tindakan berikutnya.","why_correct":"Video menunjukkan beberapa siswa baru siap merespons setelah tiga sampai empat detik. Uji jeda pada pertanyaan tertentu memberi bukti, bukan asumsi, tentang respons siswa.","comparison":"Instruksi waktu seragam atau penggantian semua aktivitas belum menguji hubungan jeda dan respons pada pertanyaan yang relevan.","check_question":"Bagaimana rekaman tiga sampai empat detik membantu menguji anggapan bahwa menunggu membuat kelas pasif?","check_answer":"Membahas rekaman waktu tunggu dan mencoba jeda lebih panjang pada pertanyaan tertentu dengan pemantauan respons siswa. Alasannya: Video menunjukkan beberapa siswa baru siap merespons setelah tiga sampai empat detik. Uji jeda pada pertanyaan tertentu memberi bukti, bukan asumsi, tentang respons siswa.","reference":{"title":"EEF (2021), Teacher Feedback to Improve Pupil Learning","url":"https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/feedback"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"62":{"concept":"Partisipasi bermakna","theory":"Pihak terkait mempunyai kesempatan menyampaikan kebutuhan dan memeriksa dasar keputusan. Partisipasi bukan hanya hadir atau mendapat giliran, tetapi gagasannya dapat memengaruhi pembahasan.","why_correct":"Pengalaman mencari kesalahan membuat guru tidak natural. Tujuan pengembangan dan kepercayaan perlu dibangun agar bukti observasi lebih bermakna.","comparison":"Observasi mendadak atau pergantian pengamat tanpa pembahasan tujuan tidak otomatis memperbaiki rasa aman.","check_question":"Mengapa rasa aman guru berpengaruh pada kualitas data supervisi?","check_answer":"Menyepakati tujuan pengembangan pada pra-observasi dan membangun kepercayaan melalui beberapa siklus dengan umpan balik. Alasannya: Pengalaman mencari kesalahan membuat guru tidak natural. Tujuan pengembangan dan kepercayaan perlu dibangun agar bukti observasi lebih bermakna.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"63":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Dokumen lengkap dan materi selesai belum menunjukkan kesempatan berpikir atau pemahaman mayoritas siswa. Supervisi perlu memeriksa respons belajar.","comparison":"Tempat duduk atau penjelasan lebih runtut saja tidak memastikan siswa memperoleh kesempatan membangun dan menunjukkan pemahaman.","check_question":"Mengapa keterlaksanaan rencana tidak cukup jika hanya 20 persen siswa aktif?","check_answer":"Menelaah kesempatan siswa berpikir, bukti pemahaman, dan respons guru sebelum menentukan perbaikan interaksi belajar. Alasannya: Dokumen lengkap dan materi selesai belum menunjukkan kesempatan berpikir atau pemahaman mayoritas siswa. Supervisi perlu memeriksa respons belajar.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"64":{"concept":"Pengembangan profesional berbasis praktik","theory":"Belajar guru dihubungkan dengan kebutuhan kelas, uji perubahan yang terjangkau, dan refleksi atas bukti penerapan. Kehadiran pelatihan belum memastikan perubahan praktik.","why_correct":"Guru senior tetap memerlukan pengembangan, tetapi fokus dapat dipilih bersama sesuai tantangan profesionalnya.","comparison":"Reputasi dan peran mentor tidak menggantikan kebutuhan bukti pengembangan diri; penyerahan urusan tanpa dialog tidak membangun komitmen.","check_question":"Mengapa guru yang menjadi mentor tetap perlu memiliki fokus pengembangan pribadi?","check_answer":"Menegaskan pengembangan berlaku bagi semua dan menyepakati fokus menantang yang dipilih bersama guru senior. Alasannya: Guru senior tetap memerlukan pengembangan, tetapi fokus dapat dipilih bersama sesuai tantangan profesionalnya.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"65":{"concept":"Asesmen dan umpan balik formatif","theory":"Informasi tentang belajar digunakan untuk menentukan langkah perbaikan. Umpan balik bernilai ketika siswa atau guru memahami dan dapat memakai informasi itu dalam tindakan berikutnya.","why_correct":"Kelemahan bersama ada pada penggunaan hasil asesmen. Belajar bersama perlu diikuti uji penyesuaian pembelajaran sesuai mata pelajaran masing-masing.","comparison":"Satu pelatihan umum atau satu format seragam belum membuktikan guru memakai informasi asesmen dalam keputusan mengajar.","check_question":"Bukti apa yang menunjukkan guru memakai hasil asesmen, bukan sekadar melaksanakannya?","check_answer":"Menyelenggarakan belajar bersama dari pekerjaan siswa, menguji respons tiap mata pelajaran, dan membahas perubahan hasil. Alasannya: Kelemahan bersama ada pada penggunaan hasil asesmen. Belajar bersama perlu diikuti uji penyesuaian pembelajaran sesuai mata pelajaran masing-masing.","reference":{"title":"EEF (2021), Teacher Feedback to Improve Pupil Learning","url":"https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/feedback"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"66":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Proyek memberi kreativitas dan kolaborasi, tetapi tujuan konsep belum tercapai. Tujuan, aktivitas, dan asesmen perlu ditelaah tanpa menghapus manfaat yang sudah ada.","comparison":"Antusiasme atau produk saja belum menjawab target konsep; menolak proyek langsung melewatkan peluang memperbaiki rancangan.","check_question":"Apa yang perlu diperbaiki agar proyek tetap kreatif sekaligus meningkatkan pemahaman konsep?","check_answer":"Menelaah keselarasan proyek dan asesmen lalu menguji dukungan konsep yang mempertahankan kreativitas serta kolaborasi. Alasannya: Proyek memberi kreativitas dan kolaborasi, tetapi tujuan konsep belum tercapai. Tujuan, aktivitas, dan asesmen perlu ditelaah tanpa menghapus manfaat yang sudah ada.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"67":{"concept":"Penyesuaian dukungan dan tantangan","theory":"Tujuan dapat tetap sama sementara bantuan, cara menunjukkan pemahaman, dan kedalaman tantangan disesuaikan. Variasi dibuat berdasarkan bukti kebutuhan, bukan label kemampuan yang tetap.","why_correct":"Peningkatan kesulitan untuk semua menguntungkan siswa cepat tetapi membuat kelompok lain pasif. Dukungan dan tantangan perlu dibedakan sesuai asesmen.","comparison":"Tujuan seragam tidak mengharuskan bantuan dan tingkat tantangan yang seragam pada setiap tahap belajar.","check_question":"Bagaimana menjaga siswa cepat tertantang tanpa membuat siswa lain semakin tertinggal?","check_answer":"Merancang dukungan dan tantangan sesuai kebutuhan kelompok lalu memeriksa kemajuan semua siswa menuju tujuan belajar. Alasannya: Peningkatan kesulitan untuk semua menguntungkan siswa cepat tetapi membuat kelompok lain pasif. Dukungan dan tantangan perlu dibedakan sesuai asesmen.","reference":null,"reference_note":null},"68":{"concept":"Pengembangan profesional berbasis praktik","theory":"Belajar guru dihubungkan dengan kebutuhan kelas, uji perubahan yang terjangkau, dan refleksi atas bukti penerapan. Kehadiran pelatihan belum memastikan perubahan praktik.","why_correct":"Kesadaran dari video perlu diterjemahkan menjadi strategi yang dipilih guru, indikator uji, dan refleksi bukti.","comparison":"Teknik wajib atau observasi tanpa diskusi tidak mengembangkan keputusan profesional guru berdasarkan konteks.","check_question":"Mengapa guru perlu dilibatkan memilih strategi, bukan hanya menerima satu teknik wajib?","check_answer":"Membantu guru memilih satu strategi sesuai konteks, mencoba dengan indikator jelas, dan merefleksikan bukti pada siklus berikutnya. Alasannya: Kesadaran dari video perlu diterjemahkan menjadi strategi yang dipilih guru, indikator uji, dan refleksi bukti.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"69":{"concept":"Evaluasi proses dan hasil","theory":"Keterlaksanaan, jumlah peserta, dan kelengkapan laporan menunjukkan proses. Manfaat program perlu diperiksa pada perubahan yang menjadi tujuan, dengan pembanding kondisi awal yang sesuai.","why_correct":"Administrasi mendukung pembelajaran, sedangkan bukti proses dan pemahaman siswa menunjukkan kualitas yang hendak dinilai.","comparison":"Kelengkapan dokumen atau penantian asesmen akhir dapat menunda penanganan hambatan yang sudah terlihat di kelas.","check_question":"Mengapa administrasi lengkap tidak menutup kebutuhan memperbaiki kesempatan bertanya dan variasi tugas?","check_answer":"Mengutamakan bukti proses dan pemahaman siswa, dengan administrasi sebagai pendukung penilaian kualitas pembelajaran. Alasannya: Administrasi mendukung pembelajaran, sedangkan bukti proses dan pemahaman siswa menunjukkan kualitas yang hendak dinilai.","reference":null,"reference_note":null},"70":{"concept":"Supervisi untuk perbaikan pembelajaran","theory":"Observasi menghasilkan bukti yang dibahas melalui refleksi dan tindak lanjut. Keberhasilan ditelusuri pada perubahan praktik serta pengalaman siswa, bukan jumlah observasi saja.","why_correct":"Keberhasilan supervisi memerlukan bukti perubahan praktik dari waktu ke waktu dan kaitannya dengan pengalaman atau hasil siswa.","comparison":"Siklus, formulir, kepuasan, dan selesainya rekomendasi adalah bukti proses yang belum menjamin perubahan belajar.","check_question":"Apa bukti tambahan yang diperlukan setelah dua siklus supervisi dinyatakan selesai?","check_answer":"Menelusuri perubahan praktik guru dari waktu ke waktu beserta perubahan pengalaman atau hasil belajar siswa. Alasannya: Keberhasilan supervisi memerlukan bukti perubahan praktik dari waktu ke waktu dan kaitannya dengan pengalaman atau hasil siswa.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"101":{"concept":"Integritas dan akuntabilitas","theory":"Laporan dan pengakuan kontribusi harus mengikuti kenyataan yang dapat diperiksa. Akuntabilitas berarti keputusan dapat dijelaskan dengan bukti, bukan sekadar selesai secara administratif.","why_correct":"Selisih kuitansi dan pengeluaran membuat dasar pengesahan belum dapat dipercaya. Laporan harus mengikuti transaksi nyata yang dapat diperiksa.","comparison":"Mengesahkan dahulu, menghapus transaksi, atau mengubah angka saja belum memastikan kebenaran bukti.","check_question":"Mengapa kuitansi yang tersedia belum cukup untuk menandatangani laporan ini?","check_answer":"Meminta laporan disesuaikan dengan pengeluaran nyata dan bukti yang dapat diverifikasi. Alasannya: Selisih kuitansi dan pengeluaran membuat dasar pengesahan belum dapat dipercaya. Laporan harus mengikuti transaksi nyata yang dapat diperiksa.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"102":{"concept":"Komunikasi dua arah","theory":"Komunikasi efektif dinilai dari pemahaman penerima. Mendengar hambatan dan meminta klarifikasi membantu memperbaiki pesan serta respons, bukan hanya memperbanyak informasi.","why_correct":"Nada kritik dan isi kritik merupakan dua hal berbeda. Meminta contoh arahan membantu menemukan perubahan yang membingungkan tanpa membalas emosi.","comparison":"Mengutamakan nada, menjelaskan sepihak, atau menunda substansi belum mengidentifikasi masalah arahan.","check_question":"Informasi apa yang perlu diminta dari guru agar kritik tentang arahan dapat ditindaklanjuti?","check_answer":"Menanggapi substansi kritik dengan tenang dan meminta contoh arahan yang perlu diperjelas. Alasannya: Nada kritik dan isi kritik merupakan dua hal berbeda. Meminta contoh arahan membantu menemukan perubahan yang membingungkan tanpa membalas emosi.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"103":{"concept":"Praktik reflektif","theory":"Pemimpin menelaah keputusan serta dampaknya, mengakui bagian yang keliru, dan memperbaiki tindakan. Refleksi mengubah bukti pengalaman menjadi perbaikan yang spesifik.","why_correct":"Kesalahan tanggal berasal dari pimpinan dan sudah memengaruhi agenda keluarga guru. Koreksi perlu disertai pengakuan serta pertimbangan dampak.","comparison":"Mengirim undangan baru saja menyembunyikan penyebab; mempertahankan tanggal atau memaksa penyesuaian membebankan kesalahan pada peserta.","check_question":"Mengapa koreksi tanggal perlu disertai pembahasan dampaknya pada guru?","check_answer":"Mengakui kesalahan, mengirim koreksi yang jelas, dan mempertimbangkan dampaknya pada peserta rapat. Alasannya: Kesalahan tanggal berasal dari pimpinan dan sudah memengaruhi agenda keluarga guru. Koreksi perlu disertai pengakuan serta pertimbangan dampak.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"104":{"concept":"Konflik kepentingan","theory":"Kepentingan pribadi dapat mengganggu independensi keputusan, termasuk ketika belum terbukti ada keberpihakan. Pengungkapan dan pemisahan peran melindungi proses dari pengaruh tersebut.","why_correct":"Hubungan keluarga dapat memengaruhi atau dianggap memengaruhi penilaian. Kriteria terbuka dan pelepasan peran penilai menjaga proses tetap independen.","comparison":"Tetap memutuskan sendiri atau mengutamakan yang dikenal tidak mengelola konflik; melarang kerabat mendaftar belum menggantikan penilaian terbuka.","check_question":"Mengapa memakai kriteria yang sama belum cukup jika kepala sekolah tetap menentukan pemenang?","check_answer":"Mengungkap hubungan keluarga dan menyerahkan penilaian kepada panitia dengan kriteria transparan. Alasannya: Hubungan keluarga dapat memengaruhi atau dianggap memengaruhi penilaian. Kriteria terbuka dan pelepasan peran penilai menjaga proses tetap independen.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"105":{"concept":"Penalaran berbasis bukti","theory":"Petunjuk, persepsi, dan hasil akhir mempunyai kekuatan serta batas berbeda. Kesimpulan perlu mengikuti bukti yang relevan dan diperiksa silang, bukan memilih data yang mendukung dugaan awal.","why_correct":"Pesan anonim adalah petunjuk untuk diperiksa, bukan bukti bahwa guru bersalah. Klarifikasi harus mendahului penetapan tindak lanjut.","comparison":"Menganggap tuduhan benar terlalu cepat; mengabaikannya melewatkan petunjuk; menyebarkannya memperluas penilaian yang belum teruji.","check_question":"Apa perbedaan fungsi pesan anonim sebagai petunjuk dan sebagai dasar keputusan?","check_answer":"Melakukan klarifikasi dan memeriksa informasi sebelum menetapkan tindak lanjut. Alasannya: Pesan anonim adalah petunjuk untuk diperiksa, bukan bukti bahwa guru bersalah. Klarifikasi harus mendahului penetapan tindak lanjut.","reference":null,"reference_note":null},"106":{"concept":"Perlindungan dan kepentingan siswa","theory":"Tindak lanjut perlu mengurangi paparan risiko, menjaga martabat, dan membatasi penyebaran informasi sesuai kebutuhan penanganan. Mencari fakta berjalan bersama langkah perlindungan.","why_correct":"Siswa membutuhkan rasa aman agar bersedia memberi informasi. Membatasi penyebaran dan merencanakan perlindungan memungkinkan tindak lanjut tanpa mempermalukannya.","comparison":"Membuka cerita di depan teman meningkatkan paparan; menyuruh menghindar memindahkan beban; janji rahasia mutlak dapat menghambat perlindungan.","check_question":"Mengapa menjaga kerahasiaan tidak berarti menjanjikan bahwa laporan tidak akan ditindaklanjuti?","check_answer":"Mendengarkan siswa, membatasi penyebaran laporan, dan menyiapkan langkah perlindungan. Alasannya: Siswa membutuhkan rasa aman agar bersedia memberi informasi. Membatasi penyebaran dan merencanakan perlindungan memungkinkan tindak lanjut tanpa mempermalukannya.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"107":{"concept":"Keadilan prosedural","theory":"Keputusan adil memakai kriteria relevan secara konsisten, memeriksa bukti, dan memberi ruang klarifikasi. Hasil yang sama tidak selalu tepat ketika kondisi yang relevan berbeda.","why_correct":"Prestasi dan kewajiban piket merupakan dasar penilaian yang berbeda. Tanpa keadaan khusus, standar tanggung jawab tetap berlaku.","comparison":"Pengecualian berbasis prestasi atau pemindahan piket ke guru lain memberi keuntungan yang tidak relevan dengan kewajiban.","check_question":"Jika tidak ada kedaruratan, apakah prestasi menjadi alasan yang relevan untuk membebaskan piket? Jelaskan.","check_answer":"Menjelaskan bahwa prestasi tidak menghapus tanggung jawab yang berlaku bagi seluruh guru. Alasannya: Prestasi dan kewajiban piket merupakan dasar penilaian yang berbeda. Tanpa keadaan khusus, standar tanggung jawab tetap berlaku.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"108":{"concept":"Komunikasi dua arah","theory":"Komunikasi efektif dinilai dari pemahaman penerima. Mendengar hambatan dan meminta klarifikasi membantu memperbaiki pesan serta respons, bukan hanya memperbanyak informasi.","why_correct":"Kesulitan orang tua memahami presentasi menunjukkan perlunya menyesuaikan cara menjelaskan, bukan sekadar mengulang isi.","comparison":"Mempertahankan gaya atau menyalahkan kemampuan pendengar tidak memeriksa bagian penjelasan yang membingungkan.","check_question":"Apa yang perlu ditanyakan kepada orang tua sebelum memperbaiki presentasi program?","check_answer":"Meminta contoh bagian yang tidak jelas dan memperbaiki cara menjelaskan program. Alasannya: Kesulitan orang tua memahami presentasi menunjukkan perlunya menyesuaikan cara menjelaskan, bukan sekadar mengulang isi.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"109":{"concept":"Komunikasi dua arah","theory":"Komunikasi efektif dinilai dari pemahaman penerima. Mendengar hambatan dan meminta klarifikasi membantu memperbaiki pesan serta respons, bukan hanya memperbanyak informasi.","why_correct":"Evaluasi dimulai dari status pekerjaan dan hambatan tim, bukan kesimpulan bahwa keterlambatan pasti akibat kemalasan.","comparison":"Teguran sebelum klarifikasi berisiko salah diagnosis; menunda atau mengambil alih semua tugas melewatkan penyebab keterlambatan.","check_question":"Informasi apa yang perlu diperiksa sebelum menyimpulkan penyebab tugas tim terlambat?","check_answer":"Menanyakan hambatan dan memeriksa kemajuan pekerjaan sebelum memberi umpan balik. Alasannya: Evaluasi dimulai dari status pekerjaan dan hambatan tim, bukan kesimpulan bahwa keterlambatan pasti akibat kemalasan.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"110":{"concept":"Konflik kepentingan","theory":"Kepentingan pribadi dapat mengganggu independensi keputusan, termasuk ketika belum terbukti ada keberpihakan. Pengungkapan dan pemisahan peran melindungi proses dari pengaruh tersebut.","why_correct":"Hadiah pribadi berkaitan dengan transaksi sekolah sehingga dapat memengaruhi kepercayaan pada keputusan pengadaan berikutnya.","comparison":"Transaksi yang sudah selesai tidak otomatis menghilangkan konflik kepentingan; menerima diam-diam atau menyamarkan hadiah tidak menjaga integritas.","check_question":"Mengapa waktu pemberian hadiah setelah pembelian tidak otomatis membuatnya layak diterima?","check_answer":"Menolak hadiah pribadi dan menjaga hubungan pengadaan tetap profesional. Alasannya: Hadiah pribadi berkaitan dengan transaksi sekolah sehingga dapat memengaruhi kepercayaan pada keputusan pengadaan berikutnya.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"111":{"concept":"Penalaran berbasis bukti","theory":"Petunjuk, persepsi, dan hasil akhir mempunyai kekuatan serta batas berbeda. Kesimpulan perlu mengikuti bukti yang relevan dan diperiksa silang, bukan memilih data yang mendukung dugaan awal.","why_correct":"Dua rekap yang berbeda perlu ditelusuri ke catatan sumber sebelum angka bulanan ditetapkan.","comparison":"Memilih angka yang lebih tinggi, lebih rendah, atau lebih mudah digunakan tidak membuktikan ketepatan rekap.","check_question":"Mengapa membandingkan dua jumlah akhir saja belum menyelesaikan perbedaan catatan kehadiran?","check_answer":"Menelusuri sumber perbedaan dan mencocokkan bukti sebelum mengesahkan rekap. Alasannya: Dua rekap yang berbeda perlu ditelusuri ke catatan sumber sebelum angka bulanan ditetapkan.","reference":null,"reference_note":null},"112":{"concept":"Praktik reflektif","theory":"Pemimpin menelaah keputusan serta dampaknya, mengakui bagian yang keliru, dan memperbaiki tindakan. Refleksi mengubah bukti pengalaman menjadi perbaikan yang spesifik.","why_correct":"Efektivitas instruksi sepihak dinilai dari dampaknya pada kerja dan kontribusi tim, bukan hanya cepatnya instruksi diterima.","comparison":"Kecepatan pelaksanaan atau kepatuhan belum menunjukkan bahwa tim memahami dan dapat memberi masukan yang diperlukan.","check_question":"Bukti apa yang dapat membedakan tim yang sekadar patuh dari tim yang memahami instruksi?","check_answer":"Mengumpulkan umpan balik tentang pemahaman, inisiatif, dan hasil kerja tim. Alasannya: Efektivitas instruksi sepihak dinilai dari dampaknya pada kerja dan kontribusi tim, bukan hanya cepatnya instruksi diterima.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"113":{"concept":"Integritas dan akuntabilitas","theory":"Laporan dan pengakuan kontribusi harus mengikuti kenyataan yang dapat diperiksa. Akuntabilitas berarti keputusan dapat dijelaskan dengan bukti, bukan sekadar selesai secara administratif.","why_correct":"Pengakuan kontribusi harus mengikuti siapa yang benar-benar menggagas kegiatan. Koreksi atribusi menjaga kepercayaan dan keadilan.","comparison":"Membiarkan nama pimpinan atau memberi penghargaan tanpa membetulkan atribusi mempertahankan informasi yang keliru.","check_question":"Apa yang harus dikoreksi agar penghargaan kepada penggagas kegiatan benar-benar adil?","check_answer":"Mengoreksi atribusi dan mengakui guru yang menyusun kegiatan. Alasannya: Pengakuan kontribusi harus mengikuti siapa yang benar-benar menggagas kegiatan. Koreksi atribusi menjaga kepercayaan dan keadilan.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"114":{"concept":"Perlindungan dan kepentingan siswa","theory":"Tindak lanjut perlu mengurangi paparan risiko, menjaga martabat, dan membatasi penyebaran informasi sesuai kebutuhan penanganan. Mencari fakta berjalan bersama langkah perlindungan.","why_correct":"Tujuan motivasi tidak menghapus risiko mempermalukan siswa melalui publikasi nilai. Sekolah perlu memikirkan dampak dan cara umpan balik yang aman.","comparison":"Menambah paparan atau menganggap semua siswa termotivasi oleh perbandingan mengabaikan kebutuhan dan martabat siswa.","check_question":"Mengapa publikasi nilai seluruh siswa belum tentu menjadi cara motivasi yang tepat?","check_answer":"Meninjau cara pemberian umpan balik agar perkembangan siswa didukung tanpa mempermalukan mereka. Alasannya: Tujuan motivasi tidak menghapus risiko mempermalukan siswa melalui publikasi nilai. Sekolah perlu memikirkan dampak dan cara umpan balik yang aman.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"115":{"concept":"Komunikasi dua arah","theory":"Komunikasi efektif dinilai dari pemahaman penerima. Mendengar hambatan dan meminta klarifikasi membantu memperbaiki pesan serta respons, bukan hanya memperbanyak informasi.","why_correct":"Orang tua membutuhkan alasan perubahan, bukan hanya pengumuman jadwal. Saluran pertanyaan membantu memeriksa apakah penjelasan dipahami.","comparison":"Menunggu mereka terbiasa atau mengulang jadwal tidak menjawab alasan; jawaban guru yang tidak diselaraskan dapat menambah kebingungan.","check_question":"Apa informasi yang belum dipenuhi jika sekolah hanya mengirim ulang jadwal baru?","check_answer":"Menjelaskan alasan perubahan dan menyediakan saluran untuk pertanyaan orang tua. Alasannya: Orang tua membutuhkan alasan perubahan, bukan hanya pengumuman jadwal. Saluran pertanyaan membantu memeriksa apakah penjelasan dipahami.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"116":{"concept":"Partisipasi bermakna","theory":"Pihak terkait mempunyai kesempatan menyampaikan kebutuhan dan memeriksa dasar keputusan. Partisipasi bukan hanya hadir atau mendapat giliran, tetapi gagasannya dapat memengaruhi pembahasan.","why_correct":"Dua klaim izin perlu diverifikasi dan dibandingkan dengan kebutuhan penggunaan ruang. Mediasi membutuhkan dasar bersama.","comparison":"Siapa yang lebih dahulu mengeluh atau pembagian sama rata belum tentu sesuai izin dan kebutuhan kegiatan.","check_question":"Apa dua hal yang perlu diperiksa sebelum membagi waktu penggunaan ruang?","check_answer":"Memeriksa kesepakatan penggunaan ruang dan memfasilitasi penyelesaian berdasarkan kebutuhan kegiatan. Alasannya: Dua klaim izin perlu diverifikasi dan dibandingkan dengan kebutuhan penggunaan ruang. Mediasi membutuhkan dasar bersama.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"117":{"concept":"Kemitraan berorientasi kebutuhan","theory":"Sekolah dan mitra menyatukan tujuan serta peran untuk menjawab kebutuhan siswa. Banyaknya dukungan atau kegiatan tidak otomatis menunjukkan kualitas kerja sama.","why_correct":"Kemitraan dimulai dari tujuan belajar dan peran yang disepakati. Banyaknya relawan bukan ukuran pertama relevansi dukungan.","comparison":"Menyerahkan rancangan atau menetapkan jadwal dahulu membuat kegiatan belum terikat pada kebutuhan membaca anak.","check_question":"Apa yang perlu disepakati sebelum warga dijadwalkan membantu kegiatan membaca?","check_answer":"Mengidentifikasi mitra dan menyepakati tujuan kegiatan yang mendukung kebutuhan belajar siswa. Alasannya: Kemitraan dimulai dari tujuan belajar dan peran yang disepakati. Banyaknya relawan bukan ukuran pertama relevansi dukungan.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"118":{"concept":"Kesetaraan kesempatan dan akses","theory":"Kesempatan yang adil memperhatikan hambatan biaya, waktu, bahasa, dan akses. Perlakuan seragam dapat menghasilkan kesempatan berbeda ketika kebutuhan pengguna tidak sama.","why_correct":"Tujuan kerja sama tetap dijaga, sementara pengaturan waktunya dapat disesuaikan setelah memahami kendala keluarga.","comparison":"Mempertahankan jadwal, menghapus tugas, atau membebaskan siswa tanpa alternatif tidak menyatukan tujuan belajar dan akses partisipasi.","check_question":"Bagian mana yang perlu dipertahankan dan bagian mana yang dapat disesuaikan dalam tugas kelompok ini?","check_answer":"Membahas tujuan tugas dan kendala waktu untuk mencari pengaturan yang memungkinkan siswa berpartisipasi. Alasannya: Tujuan kerja sama tetap dijaga, sementara pengaturan waktunya dapat disesuaikan setelah memahami kendala keluarga.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"119":{"concept":"Partisipasi bermakna","theory":"Pihak terkait mempunyai kesempatan menyampaikan kebutuhan dan memeriksa dasar keputusan. Partisipasi bukan hanya hadir atau mendapat giliran, tetapi gagasannya dapat memengaruhi pembahasan.","why_correct":"Kritik pribadi mengaburkan masalah prioritas. Mengembalikan diskusi pada kebutuhan siswa dan kriteria membuat usulan dapat dibandingkan.","comparison":"Waktu bicara yang sama saja tidak menyediakan dasar keputusan; memilih cepat atau menunda belum menyelesaikan perbedaan prioritas.","check_question":"Mengapa memberi waktu bicara sama belum cukup untuk menentukan kegiatan prioritas?","check_answer":"Mengembalikan pembahasan pada kebutuhan siswa dan kriteria prioritas yang disepakati. Alasannya: Kritik pribadi mengaburkan masalah prioritas. Mengembalikan diskusi pada kebutuhan siswa dan kriteria membuat usulan dapat dibandingkan.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"120":{"concept":"Kesetaraan kesempatan dan akses","theory":"Kesempatan yang adil memperhatikan hambatan biaya, waktu, bahasa, dan akses. Perlakuan seragam dapat menghasilkan kesempatan berbeda ketika kebutuhan pengguna tidak sama.","why_correct":"Hambatan bahasa memerlukan dukungan interaksi yang menghargai identitas siswa. Perkenalan bersama membantu membangun hubungan.","comparison":"Memaksa bahasa, membiarkan sendiri, atau mengandalkan terjemahan saja belum membangun penerimaan sosial.","check_question":"Mengapa penyesuaian tidak semestinya hanya dibebankan kepada siswa baru?","check_answer":"Membangun kegiatan perkenalan yang menghargai perbedaan dan membantu komunikasi siswa. Alasannya: Hambatan bahasa memerlukan dukungan interaksi yang menghargai identitas siswa. Perkenalan bersama membantu membangun hubungan.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"121":{"concept":"Konflik kepentingan","theory":"Kepentingan pribadi dapat mengganggu independensi keputusan, termasuk ketika belum terbukti ada keberpihakan. Pengungkapan dan pemisahan peran melindungi proses dari pengaruh tersebut.","why_correct":"Manfaat buku perlu ditimbang bersama syarat promosi kepada siswa. Bantuan pendidikan tidak otomatis membenarkan setiap kewajiban komersial.","comparison":"Mengecilkan logo tidak menilai batas kemitraan; menerima langsung atau menolak tanpa telaah melewatkan pemeriksaan syarat.","check_question":"Mengapa ukuran logo bukan satu-satunya hal yang perlu diperiksa dalam bantuan buku?","check_answer":"Memeriksa kesesuaian syarat bantuan dengan kepentingan pendidikan dan batas kemitraan sekolah. Alasannya: Manfaat buku perlu ditimbang bersama syarat promosi kepada siswa. Bantuan pendidikan tidak otomatis membenarkan setiap kewajiban komersial.","reference":{"title":"OECD (2020), Public Integrity Handbook","url":"https://www.oecd.org/en/publications/2020/05/oecd-public-integrity-handbook_598692a5.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"122":{"concept":"Komunikasi dua arah","theory":"Komunikasi efektif dinilai dari pemahaman penerima. Mendengar hambatan dan meminta klarifikasi membantu memperbaiki pesan serta respons, bukan hanya memperbanyak informasi.","why_correct":"Rincian kegiatan yang keliru perlu dikoreksi dengan informasi resmi yang jelas dan mudah diperiksa.","comparison":"Melarang komunikasi atau menyalahkan orang tua tidak serta-merta memperbaiki isi informasi yang telah beredar.","check_question":"Apa yang harus disediakan agar orang tua dapat membedakan informasi resmi dan rincian yang keliru?","check_answer":"Menyediakan klarifikasi yang mudah dibagikan dan mengarahkan mereka pada sumber resmi sekolah. Alasannya: Rincian kegiatan yang keliru perlu dikoreksi dengan informasi resmi yang jelas dan mudah diperiksa.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"123":{"concept":"Partisipasi bermakna","theory":"Pihak terkait mempunyai kesempatan menyampaikan kebutuhan dan memeriksa dasar keputusan. Partisipasi bukan hanya hadir atau mendapat giliran, tetapi gagasannya dapat memengaruhi pembahasan.","why_correct":"Penyelesaian konflik siswa perlu mendengar kedua pihak dan memeriksa kejadian, bukan menerima saling tuduh sebagai fakta.","comparison":"Menghukum langsung, memenangkan satu kelompok, atau hanya meminta berdamai belum menjelaskan penyebab perselisihan.","check_question":"Mengapa kesepakatan damai perlu didahului pemahaman kejadian pertandingan?","check_answer":"Mendengarkan pihak terkait dan memfasilitasi penyelesaian dengan aturan yang adil. Alasannya: Penyelesaian konflik siswa perlu mendengar kedua pihak dan memeriksa kejadian, bukan menerima saling tuduh sebagai fakta.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"124":{"concept":"Sekolah yang mempromosikan kesehatan","theory":"Pendekatan health-promoting school menghubungkan kebutuhan kesehatan siswa, pembelajaran, dan dukungan lintas sektor. Sekolah serta layanan kesehatan perlu mengoordinasikan perencanaan dan perannya.","why_correct":"Edukasi kesehatan bermanfaat jika kebutuhan siswa diterjemahkan menjadi materi, kelompok sasaran, dan pembagian peran sekolah-puskesmas. Kerja sama perlu dirancang sebelum pelaksanaan.","comparison":"Menyerahkan seluruh rancangan mengabaikan pengetahuan sekolah tentang siswa; menambah materi dapat mengurangi fokus; jumlah hadir mengukur jangkauan, bukan pemahaman kesehatan.","check_question":"Jika materi puskesmas belum sesuai kebutuhan siswa, apa yang harus disepakati sebelum jadwal kegiatan ditetapkan?","check_answer":"Menyepakati materi, sasaran, dan peran berdasarkan kebutuhan kesehatan siswa. Alasannya: Edukasi kesehatan bermanfaat jika kebutuhan siswa diterjemahkan menjadi materi, kelompok sasaran, dan pembagian peran sekolah-puskesmas. Kerja sama perlu dirancang sebelum pelaksanaan.","reference":{"title":"WHO–UNESCO (2021), Health-promoting schools: Global standards and indicators","url":"https://www.who.int/publications/i/item/9789240025059"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"125":{"concept":"Penalaran berbasis bukti","theory":"Petunjuk, persepsi, dan hasil akhir mempunyai kekuatan serta batas berbeda. Kesimpulan perlu mengikuti bukti yang relevan dan diperiksa silang, bukan memilih data yang mendukung dugaan awal.","why_correct":"Informasi izin yang bertentangan belum menyediakan dasar tindakan yang sah. Sekolah perlu mengklarifikasi keputusan keluarga melalui pihak yang berwenang.","comparison":"Memilih pesan yang datang terakhir atau yang memudahkan kegiatan tidak menjamin keabsahan izin.","check_question":"Mengapa izin kegiatan tidak boleh ditentukan hanya dari urutan pesan ayah dan ibu?","check_answer":"Mengklarifikasi perbedaan izin kepada orang tua sebelum menentukan keikutsertaan anak. Alasannya: Informasi izin yang bertentangan belum menyediakan dasar tindakan yang sah. Sekolah perlu mengklarifikasi keputusan keluarga melalui pihak yang berwenang.","reference":null,"reference_note":null},"126":{"concept":"Partisipasi bermakna","theory":"Pihak terkait mempunyai kesempatan menyampaikan kebutuhan dan memeriksa dasar keputusan. Partisipasi bukan hanya hadir atau mendapat giliran, tetapi gagasannya dapat memengaruhi pembahasan.","why_correct":"Latihan siswa dan kenyamanan warga sama-sama perlu diperhatikan. Pembahasan waktu serta tingkat kebisingan memungkinkan kesepakatan yang dapat dijalankan.","comparison":"Mengabaikan keluhan atau menghentikan semua latihan melewatkan peluang pengaturan yang memenuhi kedua kebutuhan.","check_question":"Pengaturan apa yang dapat dibahas agar persiapan siswa tidak mengabaikan kenyamanan warga?","check_answer":"Mendengarkan keluhan dan meninjau waktu serta tingkat kebisingan kegiatan. Alasannya: Latihan siswa dan kenyamanan warga sama-sama perlu diperhatikan. Pembahasan waktu serta tingkat kebisingan memungkinkan kesepakatan yang dapat dijalankan.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"127":{"concept":"Partisipasi bermakna","theory":"Pihak terkait mempunyai kesempatan menyampaikan kebutuhan dan memeriksa dasar keputusan. Partisipasi bukan hanya hadir atau mendapat giliran, tetapi gagasannya dapat memengaruhi pembahasan.","why_correct":"Guru baru memerlukan kesempatan bicara dan tanggapan yang menghargai isi gagasannya. Pelibatan bermakna lebih dari sekadar hadir di rapat.","comparison":"Meminta lebih percaya diri tanpa mengubah pola diskusi tetap menempatkan hambatan pada guru baru saja.","check_question":"Apa perubahan pola diskusi yang membuat guru baru benar-benar dapat berkontribusi?","check_answer":"Memberi ruang bicara yang setara dan membangun kebiasaan mendengar gagasan berdasarkan isinya. Alasannya: Guru baru memerlukan kesempatan bicara dan tanggapan yang menghargai isi gagasannya. Pelibatan bermakna lebih dari sekadar hadir di rapat.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"128":{"concept":"Kesetaraan kesempatan dan akses","theory":"Kesempatan yang adil memperhatikan hambatan biaya, waktu, bahasa, dan akses. Perlakuan seragam dapat menghasilkan kesempatan berbeda ketika kebutuhan pengguna tidak sama.","why_correct":"Kegiatan untuk semua keluarga perlu dirancang agar biaya tidak menjadi syarat tersembunyi partisipasi atau alasan mempermalukan keluarga.","comparison":"Biaya seragam dapat menimbulkan beban berbeda; pengecualian terbuka dapat memberi stigma.","check_question":"Mengapa biaya yang sama belum tentu menghasilkan kesempatan hadir yang setara?","check_answer":"Merancang partisipasi yang tidak mensyaratkan pengeluaran di luar kemampuan keluarga. Alasannya: Kegiatan untuk semua keluarga perlu dirancang agar biaya tidak menjadi syarat tersembunyi partisipasi atau alasan mempermalukan keluarga.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"129":{"concept":"Keputusan proporsional terhadap risiko","theory":"Manfaat perlu ditimbang bersama bahaya, kemungkinan, dan dampaknya. Pengendalian disiapkan sebelum tindakan; skala kecil atau harga gratis tidak otomatis berarti tanpa risiko.","why_correct":"Atap bocor menyangkut kelayakan dan keselamatan ruang belajar, sedangkan dekorasi terutama memperbaiki penampilan kantor. Fungsi dan risiko membedakan prioritas.","comparison":"Pembagian sama rata tidak mempertimbangkan tingkat kebutuhan; dekorasi atau penundaan tidak menangani risiko ruang belajar.","check_question":"Fakta apa yang membuat kedua usulan tidak layak diberi prioritas sama?","check_answer":"Memprioritaskan keselamatan dan kelayakan ruang belajar dengan memperbaiki atap yang bocor. Alasannya: Atap bocor menyangkut kelayakan dan keselamatan ruang belajar, sedangkan dekorasi terutama memperbaiki penampilan kantor. Fungsi dan risiko membedakan prioritas.","reference":null,"reference_note":null},"130":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Pendamping yang sama tidak dapat memenuhi dua kebutuhan secara penuh pada waktu bersamaan. Jadwal atau penugasan perlu disesuaikan berdasarkan kebutuhan kegiatan.","comparison":"Bergantian tanpa telaah atau mengandalkan kemandirian peserta belum memastikan pendampingan memadai.","check_question":"Apa batas sumber daya yang harus diselesaikan sebelum kedua kegiatan dapat tetap berjalan?","check_answer":"Meninjau prioritas dan menyesuaikan jadwal atau penugasan agar pendampingan mencukupi. Alasannya: Pendamping yang sama tidak dapat memenuhi dua kebutuhan secara penuh pada waktu bersamaan. Jadwal atau penugasan perlu disesuaikan berdasarkan kebutuhan kegiatan.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"131":{"concept":"Diagnosis sebelum intervensi","theory":"Gejala yang sama dapat mempunyai penyebab berbeda. Menelusuri pola dan menguji beberapa dugaan membantu memilih bantuan yang benar-benar menangani hambatan.","why_correct":"Penurunan kehadiran merupakan gejala. Pola siswa, hari, dan alasan ketidakhadiran membantu memilih intervensi yang sesuai penyebab.","comparison":"Pengingat, target, atau tuntutan kepada orang tua yang seragam dapat melewatkan penyebab yang berbeda.","check_question":"Mengapa pengingat hadir belum menjadi langkah perbaikan yang cukup pada tahap awal?","check_answer":"Menelusuri pola ketidakhadiran dan penyebabnya sebelum memilih intervensi. Alasannya: Penurunan kehadiran merupakan gejala. Pola siswa, hari, dan alasan ketidakhadiran membantu memilih intervensi yang sesuai penyebab.","reference":null,"reference_note":null},"132":{"concept":"Evaluasi proses dan hasil","theory":"Keterlaksanaan, jumlah peserta, dan kelengkapan laporan menunjukkan proses. Manfaat program perlu diperiksa pada perubahan yang menjadi tujuan, dengan pembanding kondisi awal yang sesuai.","why_correct":"Tujuan dan indikator sudah tersedia sehingga hasil tiga bulan dapat dibandingkan dengannya. Pelaksanaan merupakan bagian evaluasi, bukan bukti manfaat tunggal.","comparison":"Jumlah kegiatan dan kesukaan siswa saja belum menunjukkan pencapaian tujuan yang disepakati.","check_question":"Apa perbedaan menghitung kegiatan terlaksana dan menilai manfaatnya bagi siswa?","check_answer":"Membandingkan pelaksanaan dan hasil dengan tujuan serta indikator yang sudah disepakati. Alasannya: Tujuan dan indikator sudah tersedia sehingga hasil tiga bulan dapat dibandingkan dengannya. Pelaksanaan merupakan bagian evaluasi, bukan bukti manfaat tunggal.","reference":null,"reference_note":null},"133":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Inventaris menghubungkan identitas perangkat dengan lokasi, kondisi, dan tanggung jawab penggunaannya.","comparison":"Jumlah saja tidak menunjukkan keberadaan atau kondisi; pencatatan yang ditunda kehilangan informasi awal.","check_question":"Mengapa inventaris perlu memuat penanggung jawab dan lokasi, bukan hanya jumlah perangkat?","check_answer":"Mencatat identitas, lokasi, penanggung jawab, dan kondisi perangkat dalam inventaris sekolah. Alasannya: Inventaris menghubungkan identitas perangkat dengan lokasi, kondisi, dan tanggung jawab penggunaannya.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"134":{"concept":"Evaluasi proses dan hasil","theory":"Keterlaksanaan, jumlah peserta, dan kelengkapan laporan menunjukkan proses. Manfaat program perlu diperiksa pada perubahan yang menjadi tujuan, dengan pembanding kondisi awal yang sesuai.","why_correct":"Ukuran keberhasilan diturunkan dari tujuan setiap kegiatan. Indikator hasil berbeda dari jadwal dan jumlah aktivitas.","comparison":"Indikator seragam dapat tidak cocok dengan tujuan yang berbeda; selesai sesuai kalender belum berarti hasil tercapai.","check_question":"Mengapa jumlah peserta tidak dapat menjadi ukuran keberhasilan yang sama untuk semua kegiatan?","check_answer":"Menetapkan indikator hasil yang sesuai dengan tujuan setiap kegiatan. Alasannya: Ukuran keberhasilan diturunkan dari tujuan setiap kegiatan. Indikator hasil berbeda dari jadwal dan jumlah aktivitas.","reference":null,"reference_note":null},"135":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Ketidakhadiran guru memerlukan penugasan pengganti dan bahan yang mendukung keberlanjutan pembelajaran kelas.","comparison":"Tugas mandiri, penggabungan kelas, atau tuntutan mengajar saat cuti tidak otomatis memastikan layanan yang sesuai.","check_question":"Apa dua unsur yang harus tersedia agar kelas tetap memperoleh layanan selama guru cuti?","check_answer":"Menetapkan pengganti dan bahan pembelajaran yang sesuai dengan kebutuhan kelas. Alasannya: Ketidakhadiran guru memerlukan penugasan pengganti dan bahan yang mendukung keberlanjutan pembelajaran kelas.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"136":{"concept":"Diagnosis sebelum intervensi","theory":"Gejala yang sama dapat mempunyai penyebab berbeda. Menelusuri pola dan menguji beberapa dugaan membantu memilih bantuan yang benar-benar menangani hambatan.","why_correct":"Ketidaktertiban penjemputan perlu diperiksa melalui alur, titik antrean, dan peran sebelum prosedur diubah.","comparison":"Menambah aturan tanpa mengetahui titik masalah dapat memindahkan kemacetan atau tidak menangani penyebabnya.","check_question":"Bagian alur penjemputan apa yang perlu diamati sebelum menentukan perbaikan?","check_answer":"Mengamati alur penjemputan dan mengidentifikasi titik kemacetan serta risiko keselamatan. Alasannya: Ketidaktertiban penjemputan perlu diperiksa melalui alur, titik antrean, dan peran sebelum prosedur diubah.","reference":null,"reference_note":null},"137":{"concept":"Diagnosis sebelum intervensi","theory":"Gejala yang sama dapat mempunyai penyebab berbeda. Menelusuri pola dan menguji beberapa dugaan membantu memilih bantuan yang benar-benar menangani hambatan.","why_correct":"Kebutuhan pelatihan ditentukan dari kesenjangan kompetensi guru yang berpengaruh pada pembelajaran.","comparison":"Popularitas pelatihan atau pemerataan kesempatan saja belum memastikan materi menjawab kebutuhan.","check_question":"Bukti apa yang sebaiknya digunakan untuk memilih tema pelatihan tahun berikutnya?","check_answer":"Menggunakan data kebutuhan kompetensi dan prioritas pembelajaran untuk memilih pelatihan. Alasannya: Kebutuhan pelatihan ditentukan dari kesenjangan kompetensi guru yang berpengaruh pada pembelajaran.","reference":null,"reference_note":null},"138":{"concept":"Penalaran berbasis bukti","theory":"Petunjuk, persepsi, dan hasil akhir mempunyai kekuatan serta batas berbeda. Kesimpulan perlu mengikuti bukti yang relevan dan diperiksa silang, bukan memilih data yang mendukung dugaan awal.","why_correct":"Perencanaan layanan memerlukan jumlah siswa yang konsisten dengan data sumber. Perbedaan aplikasi harus direkonsiliasi.","comparison":"Mengambil salah satu angka tanpa penelusuran dapat menghasilkan kebutuhan layanan yang keliru.","check_question":"Mengapa memilih angka aplikasi yang paling baru belum otomatis menyelesaikan selisih data?","check_answer":"Memeriksa identitas dan status siswa untuk menyelaraskan data berdasarkan bukti. Alasannya: Perencanaan layanan memerlukan jumlah siswa yang konsisten dengan data sumber. Perbedaan aplikasi harus direkonsiliasi.","reference":null,"reference_note":null},"139":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Keputusan rapat menjadi tindakan ketika keluaran, penanggung jawab, tenggat, dan pemantauan jelas.","comparison":"Rapat lebih sering atau lebih singkat saja tidak menyelesaikan keputusan yang tidak dilaksanakan.","check_question":"Informasi apa yang perlu dicatat pada setiap keputusan agar dapat ditindaklanjuti?","check_answer":"Mencatat keputusan, penanggung jawab, dan tenggat tindak lanjut yang jelas. Alasannya: Keputusan rapat menjadi tindakan ketika keluaran, penanggung jawab, tenggat, dan pemantauan jelas.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"140":{"concept":"Keputusan proporsional terhadap risiko","theory":"Manfaat perlu ditimbang bersama bahaya, kemungkinan, dan dampaknya. Pengendalian disiapkan sebelum tindakan; skala kecil atau harga gratis tidak otomatis berarti tanpa risiko.","why_correct":"Satu laptop merupakan titik kegagalan tunggal. Cadangan dan pengamanan akses menjaga dokumen tetap tersedia tanpa memperluas akses sembarangan.","comparison":"Menunggu laptop rusak atau menyalin tanpa pengamanan belum mengelola risiko kehilangan dan akses dokumen.","check_question":"Risiko apa yang tetap ada jika semua dokumen hanya disimpan pada satu laptop?","check_answer":"Membuat cadangan yang aman dengan akses sesuai kewenangan dan jadwal pemutakhiran. Alasannya: Satu laptop merupakan titik kegagalan tunggal. Cadangan dan pengamanan akses menjaga dokumen tetap tersedia tanpa memperluas akses sembarangan.","reference":null,"reference_note":null},"141":{"concept":"Keselarasan prioritas dan sumber daya","theory":"Dana, waktu, tenaga, dan sarana terbatas. Pengelolaan perlu menghubungkan kebutuhan dengan kapasitas, fungsi tugas, dan hasil; memilih satu penggunaan juga mengurangi kesempatan penggunaan lain.","why_correct":"Nama petugas belum menjelaskan hasil yang harus dikerjakan. Keluaran dan tenggat memberi dasar koordinasi serta penilaian penyelesaian.","comparison":"Membagi jumlah tugas sama atau hanya menambah pengawasan belum mendefinisikan tanggung jawab setiap petugas.","check_question":"Mengapa surat pembagian tugas yang hanya berisi nama dan jabatan belum cukup?","check_answer":"Menyepakati peran, keluaran, dan cara pelaporan agar tanggung jawab dapat dipahami. Alasannya: Nama petugas belum menjelaskan hasil yang harus dikerjakan. Keluaran dan tenggat memberi dasar koordinasi serta penilaian penyelesaian.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"142":{"concept":"Evaluasi proses dan hasil","theory":"Keterlaksanaan, jumlah peserta, dan kelengkapan laporan menunjukkan proses. Manfaat program perlu diperiksa pada perubahan yang menjadi tujuan, dengan pembanding kondisi awal yang sesuai.","why_correct":"Kesulitan siswa setelah perubahan jadwal perlu ditelusuri agar perbaikan menyasar dampak nyata pada akses dan pembelajaran.","comparison":"Mempertahankan jadwal atau mengembalikan seluruh jadwal tanpa pemeriksaan dapat melewatkan bagian perubahan yang sebenarnya bermasalah.","check_question":"Apa yang perlu dibandingkan sebelum menentukan apakah jadwal harus diperbaiki?","check_answer":"Membandingkan pola kesulitan dan pelaksanaan jadwal sebelum menentukan penyesuaian. Alasannya: Kesulitan siswa setelah perubahan jadwal perlu ditelusuri agar perbaikan menyasar dampak nyata pada akses dan pembelajaran.","reference":null,"reference_note":null},"143":{"concept":"Uji perbaikan secara bertahap","theory":"Inovasi diperlakukan sebagai gagasan yang perlu diuji terhadap masalah tertentu. Tujuan, indikator, hasil uji, dan penyesuaian menghubungkan percobaan dengan keputusan perluasan.","why_correct":"Aplikasi merupakan sarana. Kebutuhan belajar harus dirumuskan lebih dahulu agar fitur dan biaya dapat dinilai terhadap masalah yang nyata.","comparison":"Memilih fitur, kemudahan, atau mencoba aplikasi tanpa masalah sasaran tidak memberi ukuran keberhasilan solusi.","check_question":"Mengapa kebutuhan belajar harus ditentukan sebelum aplikasi dipilih?","check_answer":"Mengidentifikasi kebutuhan belajar sebelum menilai apakah aplikasi menjadi solusi yang sesuai. Alasannya: Aplikasi merupakan sarana. Kebutuhan belajar harus dirumuskan lebih dahulu agar fitur dan biaya dapat dinilai terhadap masalah yang nyata.","reference":null,"reference_note":null},"144":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Kebun menjadi tempat belajar sains apabila aktivitas dan sumber daya dihubungkan dengan tujuan yang ingin dicapai siswa.","comparison":"Ketertarikan dan keindahan saja tidak menjamin kegiatan mengembangkan pemahaman sains.","check_question":"Apa yang membedakan kebun untuk pembelajaran dari kebun sebagai dekorasi sekolah?","check_answer":"Menghubungkan kegiatan kebun dengan tujuan belajar dan sumber daya yang tersedia. Alasannya: Kebun menjadi tempat belajar sains apabila aktivitas dan sumber daya dihubungkan dengan tujuan yang ingin dicapai siswa.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"145":{"concept":"Uji perbaikan secara bertahap","theory":"Inovasi diperlakukan sebagai gagasan yang perlu diuji terhadap masalah tertentu. Tujuan, indikator, hasil uji, dan penyesuaian menghubungkan percobaan dengan keputusan perluasan.","why_correct":"Respons rendah memberi informasi tentang rancangan yang perlu diperbaiki. Hambatan harus diperiksa sebelum melanjutkan atau menghentikan uji.","comparison":"Menambah bacaan, memperpanjang rancangan sama, atau menghentikan langsung belum menjelaskan hambatan penggunaan.","check_question":"Apa yang harus dipelajari dari respons rendah sebelum memutuskan nasib membaca digital?","check_answer":"Memeriksa hambatan dan menggunakan hasil uji coba untuk memperbaiki rancangan. Alasannya: Respons rendah memberi informasi tentang rancangan yang perlu diperbaiki. Hambatan harus diperiksa sebelum melanjutkan atau menghentikan uji.","reference":null,"reference_note":null},"146":{"concept":"Keputusan proporsional terhadap risiko","theory":"Manfaat perlu ditimbang bersama bahaya, kemungkinan, dan dampaknya. Pengendalian disiapkan sebelum tindakan; skala kecil atau harga gratis tidak otomatis berarti tanpa risiko.","why_correct":"Kegiatan baru perlu mengidentifikasi bahaya dan menyiapkan pendampingan sebelum peserta terpapar risiko.","comparison":"Skala kecil atau waktu singkat tidak otomatis menghilangkan bahaya; pendampingan setelah kegiatan terlambat mencegah risiko.","check_question":"Mengapa uji coba kecil tetap memerlukan pengendalian risiko sebelum dimulai?","check_answer":"Mengidentifikasi risiko dan menyiapkan pengendalian serta pendampingan sebelum pelaksanaan. Alasannya: Kegiatan baru perlu mengidentifikasi bahaya dan menyiapkan pendampingan sebelum peserta terpapar risiko.","reference":null,"reference_note":null},"147":{"concept":"Uji perbaikan secara bertahap","theory":"Inovasi diperlakukan sebagai gagasan yang perlu diuji terhadap masalah tertentu. Tujuan, indikator, hasil uji, dan penyesuaian menghubungkan percobaan dengan keputusan perluasan.","why_correct":"Uji kecil membutuhkan tujuan dan indikator penggunaan agar sekolah belajar apakah pojok membantu siswa belajar mandiri.","comparison":"Jumlah bahan dan luas penerapan tidak membuktikan manfaat; penggunaan tanpa tujuan sulit dievaluasi.","check_question":"Apa yang perlu ditetapkan agar uji pojok belajar menghasilkan informasi untuk keputusan berikutnya?","check_answer":"Memulai uji kecil dengan tujuan dan indikator penggunaan yang jelas. Alasannya: Uji kecil membutuhkan tujuan dan indikator penggunaan agar sekolah belajar apakah pojok membantu siswa belajar mandiri.","reference":null,"reference_note":null},"148":{"concept":"Kemitraan berorientasi kebutuhan","theory":"Sekolah dan mitra menyatukan tujuan serta peran untuk menjawab kebutuhan siswa. Banyaknya dukungan atau kegiatan tidak otomatis menunjukkan kualitas kerja sama.","why_correct":"Kontribusi alumni relevan jika pengalaman mereka sesuai tujuan pengenalan pekerjaan dan tahap perkembangan siswa.","comparison":"Ketenaran atau format yang seragam tidak menjamin pengalaman dapat dipahami dan berguna bagi usia siswa.","check_question":"Mengapa pekerjaan alumni yang paling terkenal belum tentu menjadi pilihan narasumber terbaik?","check_answer":"Mencocokkan pengalaman alumni dengan tujuan pembelajaran dan kebutuhan usia siswa. Alasannya: Kontribusi alumni relevan jika pengalaman mereka sesuai tujuan pengenalan pekerjaan dan tahap perkembangan siswa.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"149":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Soal buatan AI perlu ditinjau guru terhadap tujuan, ketepatan isi, dan kebutuhan siswa sebelum digunakan.","comparison":"Pemeriksaan oleh AI sendiri atau pembatasan pada soal mudah tidak menggantikan tanggung jawab profesional guru.","check_question":"Mengapa soal yang tampak mudah tetap perlu ditinjau guru meskipun dibuat AI?","check_answer":"Memastikan soal ditinjau guru dan penggunaannya sesuai tujuan serta kebutuhan siswa. Alasannya: Soal buatan AI perlu ditinjau guru terhadap tujuan, ketepatan isi, dan kebutuhan siswa sebelum digunakan.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"150":{"concept":"Keputusan proporsional terhadap risiko","theory":"Manfaat perlu ditimbang bersama bahaya, kemungkinan, dan dampaknya. Pengendalian disiapkan sebelum tindakan; skala kecil atau harga gratis tidak otomatis berarti tanpa risiko.","why_correct":"Harga gratis belum menunjukkan kelayakan. Perangkat perlu dinilai dari manfaat belajar, kebutuhan penggunaan, dan biaya keberlanjutan.","comparison":"Menerima karena gratis atau menilai hanya fitur melewatkan biaya dan kesesuaian kebutuhan.","check_question":"Biaya atau kebutuhan apa yang masih harus diperiksa walaupun perangkat diberikan gratis?","check_answer":"Memeriksa manfaat, syarat bantuan, dan kemampuan sekolah merawat perangkat. Alasannya: Harga gratis belum menunjukkan kelayakan. Perangkat perlu dinilai dari manfaat belajar, kebutuhan penggunaan, dan biaya keberlanjutan.","reference":null,"reference_note":null},"151":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Pameran ramai mengukur perhatian, sedangkan kemampuan menjelaskan proses menunjukkan pengalaman belajar siswa.","comparison":"Keindahan produk atau banyaknya pengunjung belum membuktikan siswa memahami cara membuat karya.","check_question":"Mengapa penjelasan proses oleh siswa lebih bermakna daripada keramaian pameran untuk menilai pembelajaran?","check_answer":"Meninjau apakah kegiatan membangun pemahaman siswa selain menghasilkan tampilan karya. Alasannya: Pameran ramai mengukur perhatian, sedangkan kemampuan menjelaskan proses menunjukkan pengalaman belajar siswa.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"152":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Potensi lingkungan dipilih berdasarkan kesesuaiannya dengan tujuan dan kebutuhan belajar, bukan hanya peluang kegiatan.","comparison":"Meniru usaha sekitar atau mengejar produk jual tanpa capaian belajar dapat mengaburkan fungsi pendidikan.","check_question":"Apa yang perlu dicocokkan antara potensi lingkungan dan tujuan kegiatan keterampilan siswa?","check_answer":"Memetakan potensi lokal dan menghubungkannya dengan pengalaman belajar yang bermakna. Alasannya: Potensi lingkungan dipilih berdasarkan kesesuaiannya dengan tujuan dan kebutuhan belajar, bukan hanya peluang kegiatan.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"153":{"concept":"Asesmen dan umpan balik formatif","theory":"Informasi tentang belajar digunakan untuk menentukan langkah perbaikan. Umpan balik bernilai ketika siswa atau guru memahami dan dapat memakai informasi itu dalam tindakan berikutnya.","why_correct":"Pertanyaan siswa dapat mengungkap pemahaman serta kebingungan mereka. Waktu bertanya perlu tujuan dan cara menindaklanjuti respons.","comparison":"Jumlah pertanyaan saja tidak menunjukkan mutu pemahaman; pertanyaan yang tidak ditindaklanjuti kehilangan fungsi belajar.","check_question":"Bagaimana guru memakai pertanyaan siswa untuk menentukan langkah pembelajaran berikutnya?","check_answer":"Menyiapkan uji coba dan mengamati kualitas pertanyaan serta keterlibatan siswa. Alasannya: Pertanyaan siswa dapat mengungkap pemahaman serta kebingungan mereka. Waktu bertanya perlu tujuan dan cara menindaklanjuti respons.","reference":{"title":"EEF (2021), Teacher Feedback to Improve Pupil Learning","url":"https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/feedback"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"154":{"concept":"Kesetaraan kesempatan dan akses","theory":"Kesempatan yang adil memperhatikan hambatan biaya, waktu, bahasa, dan akses. Perlakuan seragam dapat menghasilkan kesempatan berbeda ketika kebutuhan pengguna tidak sama.","why_correct":"Formulir daring membantu komunikasi jika dapat diakses dan dipahami orang tua yang menjadi pengguna.","comparison":"Kemudahan petugas saja tidak menunjukkan kemudahan keluarga; satu saluran dapat mengecualikan pengguna yang kesulitan akses.","check_question":"Siapa yang perlu dilibatkan untuk memastikan formulir daring benar-benar mempermudah komunikasi?","check_answer":"Merancang formulir berdasarkan informasi yang diperlukan dan kemudahan akses keluarga. Alasannya: Formulir daring membantu komunikasi jika dapat diakses dan dipahami orang tua yang menjadi pengguna.","reference":{"title":"OECD (2025), School partnerships addressing child well-being and digital technology","url":"https://www.oecd.org/en/publications/school-partnerships-addressing-child-well-being-and-digital-technology_3c946a99-en.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"155":{"concept":"Keputusan proporsional terhadap risiko","theory":"Manfaat perlu ditimbang bersama bahaya, kemungkinan, dan dampaknya. Pengendalian disiapkan sebelum tindakan; skala kecil atau harga gratis tidak otomatis berarti tanpa risiko.","why_correct":"Komitmen program perlu menyesuaikan dana yang pasti tersedia, dengan alternatif apabila sumbangan tidak terkumpul.","comparison":"Janji sumbangan bukan kepastian pembiayaan; menambah skala sebelum dana tersedia meningkatkan risiko penghentian.","check_question":"Apa perbedaan dana yang dijanjikan dan dana yang dapat dijadikan dasar komitmen program?","check_answer":"Menetapkan rancangan sesuai sumber daya terkonfirmasi dan menyiapkan alternatif bila dana tidak mencukupi. Alasannya: Komitmen program perlu menyesuaikan dana yang pasti tersedia, dengan alternatif apabila sumbangan tidak terkumpul.","reference":null,"reference_note":null},"156":{"concept":"Diagnosis sebelum intervensi","theory":"Gejala yang sama dapat mempunyai penyebab berbeda. Menelusuri pola dan menguji beberapa dugaan membantu memilih bantuan yang benar-benar menangani hambatan.","why_correct":"Sedikitnya pengguna perlu ditelusuri ke kebutuhan, akses, waktu, atau cara layanan dikenalkan.","comparison":"Promosi atau insentif tanpa pemeriksaan belum menjelaskan mengapa siswa tidak menggunakan layanan.","check_question":"Apa yang perlu ditanyakan kepada siswa sebelum menyimpulkan layanan konsultasi tidak dibutuhkan?","check_answer":"Menggali alasan rendahnya penggunaan sebelum menilai keberhasilan layanan. Alasannya: Sedikitnya pengguna perlu ditelusuri ke kebutuhan, akses, waktu, atau cara layanan dikenalkan.","reference":null,"reference_note":null},"157":{"concept":"Asesmen dan umpan balik formatif","theory":"Informasi tentang belajar digunakan untuk menentukan langkah perbaikan. Umpan balik bernilai ketika siswa atau guru memahami dan dapat memakai informasi itu dalam tindakan berikutnya.","why_correct":"Bukti distribusi kesempatan menjawab membantu guru melihat siapa yang terlibat dan siapa yang belum mendapat ruang belajar.","comparison":"Label kurang adil atau tuntutan siswa lebih aktif melewatkan pola kesempatan yang diciptakan guru.","check_question":"Mengapa meminta siswa lebih aktif belum cukup jika kesempatan menjawab tetap terbatas?","check_answer":"Menggunakan bukti distribusi kesempatan menjawab untuk mendiskusikan perbaikan partisipasi. Alasannya: Bukti distribusi kesempatan menjawab membantu guru melihat siapa yang terlibat dan siapa yang belum mendapat ruang belajar.","reference":{"title":"EEF (2021), Teacher Feedback to Improve Pupil Learning","url":"https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/feedback"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"158":{"concept":"Supervisi untuk perbaikan pembelajaran","theory":"Observasi menghasilkan bukti yang dibahas melalui refleksi dan tindak lanjut. Keberhasilan ditelusuri pada perubahan praktik serta pengalaman siswa, bukan jumlah observasi saja.","why_correct":"Supervisi bertujuan membantu perbaikan praktik dan pengalaman belajar; dokumen menjadi salah satu bukti pendukung.","comparison":"Kelengkapan berkas atau penilaian kinerja tanpa proses perbaikan mempersempit fungsi supervisi.","check_question":"Apa yang perlu diperiksa selain kelengkapan dokumen untuk menilai perbaikan pembelajaran?","check_answer":"Menjelaskan bahwa supervisi membantu perbaikan praktik dan pengalaman belajar siswa. Alasannya: Supervisi bertujuan membantu perbaikan praktik dan pengalaman belajar; dokumen menjadi salah satu bukti pendukung.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"159":{"concept":"Asesmen dan umpan balik formatif","theory":"Informasi tentang belajar digunakan untuk menentukan langkah perbaikan. Umpan balik bernilai ketika siswa atau guru memahami dan dapat memakai informasi itu dalam tindakan berikutnya.","why_correct":"Kesepakatan pertanyaan terbuka perlu waktu uji dan bukti respons siswa agar manfaatnya dapat diperiksa.","comparison":"Pertemuan tanpa bukti atau hitungan pertanyaan saja tidak menunjukkan perubahan cara berpikir siswa.","check_question":"Bukti apa yang perlu dibawa guru setelah mencoba pertanyaan terbuka?","check_answer":"Menentukan waktu uji coba dan bukti perubahan untuk dibahas pada pertemuan berikutnya. Alasannya: Kesepakatan pertanyaan terbuka perlu waktu uji dan bukti respons siswa agar manfaatnya dapat diperiksa.","reference":{"title":"EEF (2021), Teacher Feedback to Improve Pupil Learning","url":"https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/feedback"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"160":{"concept":"Penyesuaian dukungan dan tantangan","theory":"Tujuan dapat tetap sama sementara bantuan, cara menunjukkan pemahaman, dan kedalaman tantangan disesuaikan. Variasi dibuat berdasarkan bukti kebutuhan, bukan label kemampuan yang tetap.","why_correct":"Asesmen awal dipakai untuk menyesuaikan bantuan dan tantangan sambil menjaga tujuan belajar.","comparison":"Tambahan waktu, pengelompokan, atau penurunan kesulitan untuk semua belum menjawab kebutuhan yang berbeda.","check_question":"Mengapa mengelompokkan siswa belum cukup jika dukungan dan tantangan tetap sama?","check_answer":"Membahas penyesuaian dukungan dan tantangan berdasarkan kebutuhan belajar siswa. Alasannya: Asesmen awal dipakai untuk menyesuaikan bantuan dan tantangan sambil menjaga tujuan belajar.","reference":null,"reference_note":null},"161":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Antusiasme merupakan informasi keterlibatan, tetapi pemahaman konsep perlu dibuktikan melalui respons siswa.","comparison":"Menambah penjelasan atau mengurangi permainan tanpa memeriksa pemahaman belum menentukan bagian belajar yang perlu diperbaiki.","check_question":"Pertanyaan apa yang dapat diajukan kepada siswa untuk memeriksa konsep setelah bermain?","check_answer":"Memeriksa hubungan kegiatan dengan pemahaman konsep melalui bukti respons siswa. Alasannya: Antusiasme merupakan informasi keterlibatan, tetapi pemahaman konsep perlu dibuktikan melalui respons siswa.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"162":{"concept":"Asesmen dan umpan balik formatif","theory":"Informasi tentang belajar digunakan untuk menentukan langkah perbaikan. Umpan balik bernilai ketika siswa atau guru memahami dan dapat memakai informasi itu dalam tindakan berikutnya.","why_correct":"Angka menunjukkan hasil, sedangkan umpan balik spesifik membantu siswa mengetahui bagian yang perlu diperbaiki dan langkahnya.","comparison":"Angka lebih rinci, komentar seragam, atau perbandingan teman tidak otomatis memberikan arah perbaikan individual.","check_question":"Informasi apa yang belum diberikan kepada siswa jika guru hanya menuliskan angka?","check_answer":"Membahas pemberian umpan balik spesifik yang membantu siswa menentukan langkah belajar berikutnya. Alasannya: Angka menunjukkan hasil, sedangkan umpan balik spesifik membantu siswa mengetahui bagian yang perlu diperbaiki dan langkahnya.","reference":{"title":"EEF (2021), Teacher Feedback to Improve Pupil Learning","url":"https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/feedback"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"163":{"concept":"Pengembangan profesional berbasis praktik","theory":"Belajar guru dihubungkan dengan kebutuhan kelas, uji perubahan yang terjangkau, dan refleksi atas bukti penerapan. Kehadiran pelatihan belum memastikan perubahan praktik.","why_correct":"Pelatihan belum menjadi perubahan praktik jika hambatan penerapan belum ditangani. Uji yang terjangkau menghubungkan pengetahuan dengan tindakan.","comparison":"Mengulang pelatihan, menuntut semua materi sekaligus, atau membuat laporan tidak menyelesaikan hambatan di kelas.","check_question":"Apa yang perlu disepakati agar hasil pelatihan asesmen mulai digunakan dalam pembelajaran?","check_answer":"Mendiskusikan hambatan penerapan dan menyepakati uji praktik yang terjangkau. Alasannya: Pelatihan belum menjadi perubahan praktik jika hambatan penerapan belum ditangani. Uji yang terjangkau menghubungkan pengetahuan dengan tindakan.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"164":{"concept":"Penyesuaian dukungan dan tantangan","theory":"Tujuan dapat tetap sama sementara bantuan, cara menunjukkan pemahaman, dan kedalaman tantangan disesuaikan. Variasi dibuat berdasarkan bukti kebutuhan, bukan label kemampuan yang tetap.","why_correct":"Hambatan membaca instruksi tidak sama dengan kelemahan gagasan. Bantuan akses perlu diberikan tanpa menurunkan tujuan yang dinilai.","comparison":"Menurunkan tujuan atau menilai hanya kemampuan membaca dapat mencampurkan hambatan akses dengan pemahaman isi.","check_question":"Kemampuan apa yang sudah ditunjukkan siswa dan hambatan apa yang perlu dibantu?","check_answer":"Membahas dukungan akses instruksi dan cara memperoleh bukti pemahaman siswa secara sesuai. Alasannya: Hambatan membaca instruksi tidak sama dengan kelemahan gagasan. Bantuan akses perlu diberikan tanpa menurunkan tujuan yang dinilai.","reference":null,"reference_note":null},"165":{"concept":"Keselarasan konstruktif — constructive alignment","theory":"Tujuan, aktivitas belajar, dan asesmen perlu mengarah pada kemampuan yang sama. Produk menarik atau tugas selesai belum membuktikan kemampuan sasaran telah terbentuk.","why_correct":"Kesulitan menjelaskan alasan menjadi dasar fokus supervisi pada kesempatan bernalar dan bukti penjelasan siswa.","comparison":"Fokus dokumen atau ketertiban kelas saja tidak menjawab kebutuhan penalaran yang ditemukan.","check_question":"Bukti siswa apa yang perlu dikumpulkan untuk menilai kemajuan pada fokus supervisi ini?","check_answer":"Memilih fokus praktik yang membantu guru mengembangkan penalaran dan penjelasan siswa. Alasannya: Kesulitan menjelaskan alasan menjadi dasar fokus supervisi pada kesempatan bernalar dan bukti penjelasan siswa.","reference":{"title":"Biggs (1996), Enhancing teaching through constructive alignment","url":"https://doi.org/10.1007/BF00138871"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"166":{"concept":"Asesmen dan umpan balik formatif","theory":"Informasi tentang belajar digunakan untuk menentukan langkah perbaikan. Umpan balik bernilai ketika siswa atau guru memahami dan dapat memakai informasi itu dalam tindakan berikutnya.","why_correct":"Dominasi penjelasan guru perlu dibahas bersama bukti kesempatan siswa berpikir, bertanya, dan menjelaskan.","comparison":"Menilai gaya guru tanpa bukti atau menambah aktivitas tanpa tujuan belum memastikan siswa membangun pemahaman.","check_question":"Kesempatan berpikir apa yang belum terlihat ketika siswa hanya menyalin penjelasan guru?","check_answer":"Mendiskusikan kesempatan siswa berpikir dan menunjukkan pemahaman selama pembelajaran. Alasannya: Dominasi penjelasan guru perlu dibahas bersama bukti kesempatan siswa berpikir, bertanya, dan menjelaskan.","reference":{"title":"EEF (2021), Teacher Feedback to Improve Pupil Learning","url":"https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/feedback"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"167":{"concept":"Evaluasi proses dan hasil","theory":"Keterlaksanaan, jumlah peserta, dan kelengkapan laporan menunjukkan proses. Manfaat program perlu diperiksa pada perubahan yang menjadi tujuan, dengan pembanding kondisi awal yang sesuai.","why_correct":"Kelas tenang menunjukkan suasana, bukan otomatis pemahaman. Respons dan pekerjaan siswa diperlukan untuk memeriksa belajar.","comparison":"Ketenangan atau kepatuhan saja dapat menutupi siswa yang belum memahami materi.","check_question":"Apa yang perlu diminta dari siswa untuk membedakan tenang karena memahami dan tenang tanpa memahami?","check_answer":"Meminta bukti respons atau pekerjaan siswa untuk menilai pemahaman selain ketenangan kelas. Alasannya: Kelas tenang menunjukkan suasana, bukan otomatis pemahaman. Respons dan pekerjaan siswa diperlukan untuk memeriksa belajar.","reference":null,"reference_note":null},"168":{"concept":"Pengembangan profesional berbasis praktik","theory":"Belajar guru dihubungkan dengan kebutuhan kelas, uji perubahan yang terjangkau, dan refleksi atas bukti penerapan. Kehadiran pelatihan belum memastikan perubahan praktik.","why_correct":"Praktik rekan menjadi bahan belajar jika unsur yang relevan dipilih, dicoba, dan dievaluasi sesuai kelas guru.","comparison":"Menyalin seluruh praktik atau hanya mengamati tanpa tindak lanjut tidak memastikan kesesuaian konteks.","check_question":"Apa yang perlu ditetapkan sebelum guru mencoba praktik rekan di kelasnya sendiri?","check_answer":"Mengatur belajar antarguru dengan fokus dan refleksi penerapan yang jelas. Alasannya: Praktik rekan menjadi bahan belajar jika unsur yang relevan dipilih, dicoba, dan dievaluasi sesuai kelas guru.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."},"169":{"concept":"Penyesuaian dukungan dan tantangan","theory":"Tujuan dapat tetap sama sementara bantuan, cara menunjukkan pemahaman, dan kedalaman tantangan disesuaikan. Variasi dibuat berdasarkan bukti kebutuhan, bukan label kemampuan yang tetap.","why_correct":"Siswa yang cepat perlu kedalaman atau variasi penalaran, bukan otomatis tambahan pekerjaan sejenis.","comparison":"Lebih banyak latihan yang sama dapat menambah beban tanpa meningkatkan tantangan berpikir.","check_question":"Apa perbedaan menambah jumlah soal dan memperdalam tantangan bagi siswa cepat?","check_answer":"Membahas pengayaan yang menambah kedalaman berpikir daripada hanya menambah jumlah pekerjaan. Alasannya: Siswa yang cepat perlu kedalaman atau variasi penalaran, bukan otomatis tambahan pekerjaan sejenis.","reference":null,"reference_note":null},"170":{"concept":"Supervisi untuk perbaikan pembelajaran","theory":"Observasi menghasilkan bukti yang dibahas melalui refleksi dan tindak lanjut. Keberhasilan ditelusuri pada perubahan praktik serta pengalaman siswa, bukan jumlah observasi saja.","why_correct":"Manfaat pendampingan ditelusuri melalui perubahan praktik guru serta pengalaman belajar siswa.","comparison":"Jumlah pertemuan, laporan, dan kepuasan merupakan bukti proses yang belum memastikan dampak belajar.","check_question":"Bukti apa yang diperlukan selain laporan pertemuan untuk menyatakan pendampingan berhasil?","check_answer":"Memeriksa perubahan praktik dan dampaknya pada pengalaman belajar siswa dengan bukti yang relevan. Alasannya: Manfaat pendampingan ditelusuri melalui perubahan praktik guru serta pengalaman belajar siswa.","reference":{"title":"OECD, Education leadership","url":"https://www.oecd.org/en/topics/policy-issues/education-leadership.html"},"reference_note":"Rujukan menjelaskan konsep; penerapannya pada kasus merupakan penalaran pembelajaran SIMANTAB."}};
